
/* games.js */
/* Curatorial analysis is original commentary; factual references are attached per work. */
const games=[];
function exhibit(id,year,title,en,maker,tags,style,color,impact,position,innovation,unique,boundary,relations,sources,edition='首发版本'){games.push({id,year,title,en,maker,tags,style,color,impact,position,innovation,unique,boundary,relations,sources,edition,personal:!['pong','space-invaders','mario','tetris','doom','pokemon','ocarina','wow','minecraft','gta-v','re4-2005'].includes(id)});}
exhibit('death-stranding',2019,'死亡搁浅','DEATH STRANDING','Kojima Productions',['world','design','culture'],'strand','#9dcedd','让跋涉成为玩法，让连接成为回报。',
'在开放世界普遍追求更密集战斗与奖励的时期，《死亡搁浅》把通常被省略的“赶路”推到舞台中央。它的历史价值在于重新分配游戏的注意力：山坡、重量、距离和他人的劳动，都成为玩家必须认真对待的对象。它不是异步联网的起点，却是将公共建设与孤独旅程结合得极为鲜明的大型作品。',
'负重会影响平衡，地形会改变路线成本，梯子、绳索、道路与索道则逐步改写地图。玩家先感受运输的摩擦，才能理解基础设施的价值。异步共享让陌生人的建筑出现在旅途中，帮助行为由此进入资源循环，而不只是剧情中的道德宣言。',
'荒凉景观、音乐进入的时机与漫长步行共同制造节奏。电影可以展示孤独，却很难让观众亲自承担一段路的成本，再在看见一座桥时产生具体的感激；这里的情绪来自行动前后的落差。',
'重复配送、冗长讲解与战斗部分并不一定同样有效。它提出了一条有辨识度的设计路线，但不能据此宣布“连接型游戏”已经成为成熟行业门类。',
[['系列前作脉络','《合金装备 V：幻痛》','同一创作者此前对开放任务、工具与路线选择的探索，可帮助理解本作如何把操作系统从渗透转向运输。'],['设计比较','《黑暗之魂》与《风之旅人》','可比较陌生人痕迹、有限交流与共同在场的情感；这是一种策展比较，不等于把某一具体机制认定为直接借用。'],['直接续作','《死亡搁浅 2：冥滩之上》','扩大行动选择与环境变化，也继续追问连接的意义。','death-stranding-2']],
[['PlayStation · 死亡搁浅 2（系列背景）','https://www.playstation.com/en-hk/games/death-stranding-2-on-the-beach/']], '2019 原作；展图含导演剪辑版素材');
exhibit('death-stranding-2',2025,'死亡搁浅 2：冥滩之上','DEATH STRANDING 2: ON THE BEACH','Kojima Productions',['world','technology','culture'],'strand','#f4ad6b','当连接成为系统，重新追问连接本身。',
'它更适合作为一种新设计路线的扩展样本，而不是已经盖棺定论的历史转折。前作证明配送与公共建设可以支撑大型游戏，续作则尝试让这套结构容纳更多行动路径、环境变化和更高密度的戏剧演出。',
'变化的天气、时间与地形状态使路线判断面对新的变量；正面交战、潜行或绕行之间的选择更有分量。从系统设计看，核心问题是如何增加可选手段，又不让运输与地形失去存在感。',
'它保留了“为后来的人留下什么”的公共建设想象，同时把这种想象放入更加不稳定的世界。在宏大制作中继续围绕劳动、牵挂和依赖展开，是这组作品具有作者辨识度的原因。',
'更顺畅和更丰富不自动意味着更有开创性。续作的长期行业影响仍需观察；本馆重点记录它如何调整前作的设计张力，不以发行时的讨论热度代替历史结论。',
[['直接前作','《死亡搁浅》','承接负重运输、异步共享与连接网络，并增加环境和行动变量。','death-stranding'],['创作者脉络','《合金装备 V：幻痛》','潜行与装备选择可放在同一创作者的设计脉络中讨论；不把两部作品简单等同。']],
[['PlayStation · 作品介绍与发行日期','https://www.playstation.com/en-hk/games/death-stranding-2-on-the-beach/']], '2025 首发；长期影响待观察');
exhibit('spider-man',2018,'漫威蜘蛛侠','MARVEL’S SPIDER-MAN','Insomniac Games',['design','world'],'comic','#ff6865','把“成为蜘蛛侠”做成可持续的身体体验。',
'它的价值是超级英雄授权游戏的成熟整合：把城市移动、近战、角色演出和开放世界任务统一到一个足够可信的英雄幻想中。它没有发明蛛丝摆荡，却把高频移动打磨成即使没有任务奖励也愿意反复执行的核心体验。',
'摆荡、跃出、贴墙与落地之间的动画衔接降低了失误带来的割裂感，镜头和速度反馈共同维持流动性。战斗把空中动作、环境物件和道具嵌入连击，使角色能力同时服务于视觉表现与操作决策。',
'纽约既是任务容器，也是角色身体的延伸；玩家对城市的理解由街道导航变成楼宇高度、转向空间和落差。彼得的日常困境又为英雄能力提供反向尺度，让强大与责任在同一角色身上成立。',
'地图清单、重复据点与部分强制流程保留了标准开放世界的痕迹。它更有说服力的定位是类型完成度标杆，而非开放世界语法的发明者。',
[['同角色前史','《Spider-Man 2》（2004）','更早的城市摆荡游戏说明，这种英雄体验有长期积累；2018 年的成就是重新组织与打磨。'],['设计比较','《蝙蝠侠：阿卡姆》系列','连击、反制与潜行捕猎可用于比较超级英雄动作游戏的通用语言，不据此断言每项机制的来源。'],['系列延续','《迈尔斯·莫拉莱斯》→《漫威蜘蛛侠 2》','独立衍生作建立另一位主角的操作身份，第二部进一步展开双主角结构。','spider-man-2']],
[['PlayStation · 漫威蜘蛛侠重制版','https://www.playstation.com/en-us/games/marvels-spider-man-remastered/'],['PlayStation · 系列作品','https://www.playstation.com/en-us/explore-marvels-spider-man/']], '2018 原作；展图采用重制版素材');
exhibit('spider-man-2',2023,'漫威蜘蛛侠 2','MARVEL’S SPIDER-MAN 2','Insomniac Games',['technology','design','world'],'comic','#ff7777','双主角与高速城市，检验续作的工业能力。',
'它把前作建立的超级英雄体验推向更高的流动速度与演出规模。行业意义主要在于续作生产的系统整合：扩展地图、两位英雄与更复杂的能力组合，仍要让玩家始终保持动作的连贯感。',
'蛛网翼把滑翔加入摆荡，风道与城市尺度成为移动设计的一部分。彼得与迈尔斯拥有不同能力，又共享一套操作基础；快速切换的价值在于减少叙事视角和游玩视角之间的等待。',
'两名蜘蛛侠面对同一座城市，却承担不同的人际关系与责任。移动的快感、共生体力量的侵入性和双主角对照，使它的特色不只是地图面积增加，而是同一种英雄身份的不同表达。',
'更快的加载、更大的地图并不单独构成新类型。叙事节奏、配角篇幅和任务变化仍是评价它的关键；本馆将其定位为成熟系列的技术与体验扩展。',
[['直接前作','《漫威蜘蛛侠》','沿用城市摆荡与动作体系，扩大移动速度、空间和演出规模。','spider-man'],['必要桥梁','《漫威蜘蛛侠：迈尔斯·莫拉莱斯》','为迈尔斯建立独立能力、社交关系与主角身份，是理解双主角结构的重要中间作品。']],
[['PlayStation · 双主角、蛛网翼与城市','https://www.playstation.com/en-us/games/marvels-spider-man-2/']]);
exhibit('wukong',2024,'黑神话：悟空','BLACK MYTH: WUKONG','Game Science · 游戏科学',['culture','technology','design'],'ink','#d4b880','让中国文化成为大型动作游戏的主体。',
'它的突出意义位于文化表达与制作工业的交汇处：中国团队以《西游记》为叙事根基，让本土建筑、造像、声音和审美承担全球发行作品的核心表达。这里的突破不必被夸大为“第一款中国单机”，而应放在国产高规格买断制动作游戏的生产与传播路径中观察。',
'棍势、闪避、法术与变身围绕首领战组织资源分配，玩家在进攻窗口内选择积累或兑现伤害。章回结构把区域探索与高强度遭遇分段编排，章末动画再以不同形式延展人物与主题。',
'熟悉的神话在美术细节、怪物身份和残缺叙述之间重新陌生化。它的不可替代之处，是文化材料与高规格交互体验共同出现，而不只是在通用动作模板上更换角色皮肤。',
'高质量首领战不意味着探索指引、空气墙和场景可读性没有代价。其长期作用还取决于后续团队能否把人才、流程和市场信心转化为持续作品，不能只从一款作品推断整个产业已经成熟。',
[['文学来源','《西游记》','直接文化根基；理解原著人物关系，可以增加对本作改写与留白的辨识。'],['团队前史','《斗战神》','部分主创此前参与的西游题材项目，可作为创作者与题材积累的背景，不能等同于玩法直接前作。'],['设计比较','《战神》与《黑暗之魂》','分别帮助讨论演出驱动的动作冒险和遭遇学习；相似之处不等于本作可以被单一类型完全解释。']],
[['PlayStation Store · 官方作品说明','https://store.playstation.com/en-us/concept/10007144']], '2024 首发；产业长期影响待观察');
exhibit('metro',2019,'地铁：离去','METRO EXODUS','4A Games',['world','design','technology'],'terminal','#e5b57b','离开隧道，仍让每一次呼吸有重量。',
'《离去》是线性叙事射击向区域开放结构转型的有代表性案例。它没有把整部作品摊平成一张大地图，而是以列车串联旅程，在不同区域保留探索自由，同时用章节控制季节、环境与故事节奏。',
'防毒面具、滤芯、武器维护和随身工具把信息与操作放回人物身体。搜刮与潜行由资源压力获得意义；列车上的同行者则让两个战斗区域之间的停顿成为生活片段，而不是菜单切换。',
'它的末日感来自脆弱而具体的物质：面罩上的污迹、武器的可靠性、陌生聚落的秩序。公路旅程的结构让环境变化成为希望与危险的共同来源，这是连续大地图未必能提供的节奏。',
'半开放区域并不意味着所有任务都允许完全自由的系统解法；部分动作与交互也以迟缓换取质感。2019 原作与后来的增强版需要区分，后者的渲染特性不能倒写成首发版本的全部成就。',
[['直接前作','《地铁 2033》→《地铁：最后的曙光》','建立资源紧张、地下社会与具身界面的基础，《离去》把它们带到更广阔的地表。'],['设计比较','《潜行者：切尔诺贝利的阴影》','可比较东欧末日空间、资源压力与荒野探索；两者在叙事控制与模拟开放度上有明显区别。']],
[['Deep Silver · 官方作品介绍','https://www.deepsilver.com/games/metro-exodus']], '2019 原作；区别于增强版');
exhibit('astro',2024,'宇宙机器人','ASTRO BOT','Team ASOBI',['design','technology','culture'],'gallery','#8dccff','把硬件的能力，翻译成手中的乐趣。',
'它延续三维平台游戏的核心传统，同时把当代手柄的触觉能力与关卡创意紧密结合。其价值不在于提出一个前所未见的类型，而在于展示短关卡、高变化密度与精细反馈如何形成一部完整的大型平台作品。',
'能力往往只服务于一段紧凑关卡：先用低风险场景建立理解，再改变空间条件，最后组合挑战。触觉、扳机与动画帮助玩家识别材质与作用力，硬件特征因而参与玩法，而不只是作为演示功能存在。',
'PlayStation 历史角色被放进可寻找、可互动的空间，平台品牌的记忆由图鉴变成游玩。它的明亮气质有严密的制作支撑：每次跳跃、落地与机关反馈都在维护玩家的信任。',
'它与任天堂平台设计有清晰的可比较传统；“完成度极高”和“发明了平台游戏”应当分开。长期影响尚需时间验证，当前更适合视为触觉平台设计与品牌记忆展陈的鲜明案例。',
[['系列前史','《ASTRO BOT Rescue Mission》→《ASTRO’s Playroom》','从 VR 的空间互动，到随 PS5 提供的手柄展示，再扩展为完整关卡冒险。'],['设计比较','《超级马力欧银河》','比较围绕单个关卡创意快速建立、变化与收束的设计组织方式，不把比较写成未经证实的直接影响。']],
[['PlayStation · ASTRO BOT 官方介绍','https://www.playstation.com/en-hk/games/astro-bot/']], '2024 独立作品，非《ASTRO’s Playroom》');
exhibit('re4',2023,'生化危机 4：重制版','RESIDENT EVIL 4','Capcom',['design','technology'],'horror','#b8c99c','经典重制，是重新分配压力。',
'它的历史位置建立在 2005 年原作之上。原作对越肩射击与动作恐怖的影响，不能全部算作重制版的新贡献；2023 版值得研究的是经典重制如何保留遭遇节奏，又重新适应现代移动、瞄准与叙事期待。',
'允许移动射击后，敌人的进攻压力与空间围堵需要重新组织。刀具格挡为近身危险增加主动回应，但耐久又让安全感具有成本；角色行动的现代化因此伴随敌人节奏和资源经济的再平衡。',
'村庄、城堡与孤岛的递进，加上商人、背包与装备成长，仍保持原作独特的冒险节奏。重制版让玩家既认出记忆中的局面，又不能完全沿用旧的肌肉记忆，这是有效重制比画质翻新更重要的地方。',
'它的价值主要是再设计而非类型起源。更现代的操作也改变了原作“停下才能精确攻击”的特殊紧张感，两种版本可以分别成立，不必把新版视为对旧版的全面替代。',
[['直接原作','《生化危机 4》（2005）','越肩视角与遭遇结构的历史贡献，应首先归于这部作品。','re4-2005'],['制作脉络','《生化危机 2：重制版》','同属卡普空现代重制路线，可比较空间重构、人物表现与恐怖节奏的调整。'],['版本比较','《生化危机 4》原作与重制版','同一场战斗在两种移动规则下产生不同压力，是理解重制设计的理想对照。','re4-2005']],
[['Capcom · 2023 重制版官方介绍','https://www.residentevil.com/re4/en-asia/']], '2023 重制版；原作另设独立展品');
exhibit('gt7',2022,'跑车浪漫旅 7','GRAN TURISMO 7','Polyphony Digital',['culture','technology','design'],'racing','#8abfe9','让汽车文化成为可以驾驶的收藏。',
'GT7 延续系列把驾驶模拟、车辆收藏和汽车知识组织到同一产品中的传统。它并非赛车模拟的起点，更像是一部把长期车辆资产、制作经验与爱好者文化汇入当代主机的综合作品。',
'驾照训练分解驾驶技能，咖啡厅菜单引导收藏，车辆介绍与品牌内容为获得一辆车提供历史语境。摄影、调校与比赛形成不同深度的参与方式，使汽车不只是一组性能参数。',
'一辆车可以同时是驾驶工具、设计对象和时代文物。玩家在观看、理解、购买、改装与驾驶之间往返，知识不再只是游戏外的百科附录；这也是游戏博物馆可以向 GT7 学习的策展方法。',
'模拟精度、车辆获取节奏与联网依赖应分别评价。收藏经济有时会与自由试驾的愿望冲突；也不能把系列多年积累的汽车文化叙事全部描述成 GT7 的首次发明。',
[['系列起点','《Gran Turismo》（1997）','将量产车、驾照训练和升级收藏组织成具有持续吸引力的驾驶生涯。'],['直接前史','《GT Sport》','积累在线竞赛与当代展示技术；GT7 重新强调更完整的收藏和生涯体验。'],['策展比较','《Forza Motorsport》系列','适合比较汽车模拟如何兼顾竞赛深度、展示与大众进入门槛，并非单向继承关系。']],
[['Gran Turismo · GT7 官方产品页','https://www.gran-turismo.com/us/products/gt7/'],['Gran Turismo · GT7 官方手册','https://www.gran-turismo.com/us/gt7/manual/']]);
exhibit('rdr2',2018,'荒野大镖客：救赎 2','RED DEAD REDEMPTION 2','Rockstar Games',['world','technology','culture'],'western','#ff947f','以工业规模，雕刻一个正在消逝的时代。',
'它是高预算开放世界在环境密度、角色演出和日常细节上的重要标杆。其行业意义不只是“地图逼真”，而是让大量相互呼应的动画、声音、行为与叙事共同维持一个世界的可信度。',
'营地提供持续关系，路上的偶遇与动物行为让旅程产生不完全依赖主线的记忆。慢速拾取、照料与移动把人物身体嵌进环境，但任务中的电影式调度又保持较强的作者控制。',
'在推进故事的同时，玩家被允许花时间观察一个生活方式的尾声。它的情绪由长时段陪伴与细微变化积累，不只是某段过场动画的功劳；世界的可信让人物的处境变得可感。',
'自由探索与严格任务脚本之间存在明显张力，精细动画也会带来操作摩擦。它代表高成本内容整合的极端能力，不能简单被当作所有团队都应复制的生产标准。',
[['系列前作','《荒野大镖客：救赎》（2010）','发行上的前作；《救赎 2》的故事时间更早。两者共同构成西部时代消退的叙事。'],['同工作室脉络','《GTA V》','共享大型开放世界的制作积累，但城市讽刺与西部挽歌采用不同的行动节奏。','gta-v']],
[['Rockstar · Steam 官方作品页','https://store.steampowered.com/app/1174180/']]);
exhibit('detroit',2018,'底特律：变人','DETROIT: BECOME HUMAN','Quantic Dream',['design','culture'],'terminal','#83d5fa','把选择的后果，变成叙事的结构。',
'它是分支式互动叙事在高规格表演与可视化结构上的代表作。选择叙事远早于本作存在；它的贡献是把多主角、场景条件和人物存亡整合到可追踪、可回访的电影式体验中。',
'倒计时迫使玩家在不完整信息下行动，调查改变可用选项，章节流程图则展示已经走过与尚未触及的分支。失败常常成为故事继续的条件，而不只是要求重来的提示。',
'三名主角使同一社会冲突拥有不同的观察距离。玩家知道一个选择可能关闭另一条人生路径，便会对亲手促成的结果承担不同于观看电影的责任；流程图又把这种责任转成可研究的叙事网络。',
'复杂分支不必然意味着议题同样复杂：仿生人与现实社会历史之间的类比仍可以被批评。重玩也可能让道德选择变成解锁清单，这是作品结构自身的张力。',
[['创作前史','《暴雨》与《超凡双生》','同工作室在动作提示、表演捕捉和多视角叙事上的持续积累。'],['角色起源','《Kara》技术演示（2012）','卡菈的早期形象来自工作室技术短片，后来进入完整互动故事。'],['媒介比较','文字冒险与互动电影传统','把本作放回较长的分支叙事历史，才能区分制作规模与机制首创。']],
[['Quantic Dream · Steam 官方作品页','https://store.steampowered.com/app/1222140/'],['Quantic Dream · Kara 创作背景','https://blog.dev.quanticdream.com/page/20/']]);
exhibit('portal',2007,'传送门','PORTAL','Valve',['design','technology'],'gallery','#8bcfee','用一条空间规则，改写你对房间的理解。',
'《传送门》是机制、教学和叙事高度一致的短篇游戏范本。它把连通两个表面的空间规则压缩成易懂的工具，再让玩家逐步突破日常空间直觉；体量有限，却能持续产生认知上的变化。',
'谜题先隔离变量，再让动量、重力、视线与空间连接组合起来。测试设施让重复试验具有叙事理由，GLaDOS 的语言又让规则教学同时承担角色塑造与世界暗示。',
'叙事并非解谜之间的插播：玩家越理解系统，越能理解自己与系统管理者之间的关系。幽默、冷峻空间与机械规则形成统一语气，使最后的突破同时是空间能力与叙事身份的转变。',
'它不是传送概念的首次出现，也不靠庞大的开放世界证明价值。其历史地位更来自对单个核心规则的高密度展开，以及在短时间内完成的完整情绪弧线。',
[['直接设计前身','《Narbacular Drop》（2005）','学生作品中的成对传送门机制是理解《传送门》来历的重要节点。'],['制作与世界背景','《半衰期 2》','Valve 的引擎与第一人称叙事积累提供背景；本作将交互重心从射击转向空间推理。'],['直接续作','《传送门 2》','扩展测试材料、设施历史与双人合作，展示核心规则的另一层组合潜力。']],
[['Valve · Steam 官方作品页','https://store.steampowered.com/app/400/'],['DigiPen · Narbacular Drop','https://www.digipen.edu/showcase/student-games/narbacular-drop']]);
exhibit('it-takes-two',2021,'双人成行','IT TAKES TWO','Hazelight Studios',['design','culture'],'fable','#edca7e','把两个人的关系，写进操作规则。',
'它是围绕强制双人合作组织整部作品的鲜明案例。合作并非附加模式，而是关卡、叙事、镜头与发行体验的共同前提；作品因此能在每一段都假设“另一个人确实在场”。',
'两名玩家常拿到不同但互补的工具，必须相互解释、等待与配合。关卡不断更换机制，避免整段旅程只是在同一动作上增加难度；好友通行证则降低了组建双人组合的购买门槛。',
'和解不是只由角色说出来，现实玩家也必须学会协作。分屏让彼此的处境始终可见，家庭物件变成冒险尺度，让私人关系与夸张空间持续互相映照。',
'合作的强制性也意味着对搭档、时间和操作水平有要求；机制变化快，会牺牲某些系统的长期深挖。其家庭叙事与玩家关系也并不总能完全同频。',
[['作者前史','《兄弟：双子传说》','同一创作者更早将两名角色的控制关系用于情感表达，实际操控结构与本作不同。'],['同工作室前作','《逃出生天》','建立强制双人、持续分屏和合作叙事的制作基础。'],['同工作室后续','《双影奇境》（Split Fiction）','继续拓展双人互补能力与高变化密度的关卡路线，属于团队设计脉络的延续。']],
[['EA · 双人成行官方介绍','https://www.ea.com/en/games/it-takes-two/it-takes-two'],['EA · 好友通行证','https://www.ea.com/en/games/it-takes-two/it-takes-two/features/itt-friends-pass'],['EA · Split Fiction','https://www.ea.com/en/games/split-fiction/split-fiction']]);
exhibit('titanfall-2',2016,'泰坦陨落 2','TITANFALL 2','Respawn Entertainment',['design','technology'],'terminal','#e9b879','让移动、射击与关卡创意同时加速。',
'它在第一人称射击中提供了一种非常集中的单人战役范本：并非用更长流程累积规模，而是围绕移动能力持续提出新的空间问题。与前作的多人基础相比，续作让铁驭与泰坦的关系获得完整叙事。',
'蹬墙、滑行与空中射击改变了敌人和掩体的价值；玩家需要阅读路线而非只寻找掩体。战役中的机制变化则让相同移动能力在不同空间条件下产生新含义，巨大泰坦又提供另一种速度和力量尺度。',
'BT 同时是角色、载具与战斗系统。玩家既在叙事中认识它，也靠它完成行动目标，因此人与机器的信任由反复合作建立，而不完全依靠对白。',
'它不等于所有机制的首创者，也不能只用商业表现解释其价值。战役的独特密度与多人系统是两种评价对象；这里重点收录的是两者如何共享一套移动基础。',
[['直接前作','《Titanfall》','建立铁驭跑酷与泰坦切换的基础，续作增加完整单人战役。'],['设计比较','《镜之边缘》与《半衰期 2》','分别可用于比较第一人称身体移动与围绕关卡创意推进的战役节奏，非直接因果断言。'],['同宇宙后续','《Apex Legends》','延续部分世界观与射击手感积累，但弱化蹬墙与泰坦，转向英雄团队竞技。']],
[['EA · Titanfall 2 官方介绍','https://www.ea.com/en/games/titanfall/titanfall-2']]);
exhibit('witcher-3',2015,'巫师 3：狂猎','THE WITCHER 3: WILD HUNT','CD Projekt Red',['world','culture','design'],'fable','#d3bfa0','让支线人物，拥有不亚于主线的重量。',
'《巫师 3》的代表性在于把有作者表达的任务叙事铺进大型开放世界。它不是对话选择或道德灰度的发明者，却让大量支线也拥有动机、冲突与后果，使“地图上的一个问号”有机会成为一段可记住的人生。',
'猎魔委托通常从调查开始，信息逐步改变玩家对怪物与人的判断；战斗是解决问题的一部分，而不总是最终解释。固定主角提供稳定的职业和价值背景，使选择具有角色语境，而非任意身份扮演。',
'乡村恐惧、战争遗留和私人欲望彼此纠缠，宏大世界由许多并不宏大的生活组成。杰洛特的专业身份让玩家在接受雇佣与判断是非之间往返，这种职业视角是它区别于通用救世主幻想的关键。',
'优秀叙事不代表每处探索点都有同样质量，调查操作与战斗深度也可以单独讨论。它展示了任务写作与开放世界结合的高完成度，同时也需要大量内容生产投入。',
[['直接前作','《巫师》→《巫师 2：国王刺客》','积累固定主角、政治冲突和选择后果，再将这些能力铺向更广阔的地图。'],['文学来源','安杰伊·萨普科夫斯基的《猎魔人》小说','人物与世界观的直接文学根基；游戏在此基础上展开自己的后续叙事。'],['作品内部延伸','《石之心》与《血与酒》','分别展示更集中的人物悲剧与具有独立地域气质的扩展篇章。']],
[['CD Projekt Red · 巫师 3 官方介绍','https://www.thewitcher.com/mt/en/witcher3']]);
exhibit('sifu',2022,'师父','SIFU','Sloclap',['design','culture'],'ink','#e9a298','每一次重来，都在身体上留下时间。',
'《师父》在相对紧凑的制作规模中，把近身动作的熟练过程与衰老规则连接起来。它不靠大量装备或地图延长体验，而让玩家反复进入熟悉场所，以更准确的判断替代最初的慌乱。',
'结构值、格挡、闪避与位置关系要求玩家管理围攻，而不是只背一套连招。死亡后的复起消耗年龄，并改变生命与攻击的权衡；因此失败既是学习反馈，也是贯穿一轮挑战的有限资源支出。',
'年龄让“付出代价”可见，关卡重访则让修炼真正发生在玩家身上。动作编排、空间构图与环境物件共同形成武术电影式节奏，但完成这段节奏需要亲手判断时机。',
'严苛的初期学习与重复练习可能成为进入门槛。它的可贵之处是规则与主题的集中，而不是动作系统在所有维度都比其他格斗游戏更复杂。',
[['同工作室前作','《Absolver》','更早探索近身武术与攻防学习；《师父》转向更集中的单人关卡结构。'],['文化脉络','功夫电影与武术训练','是理解构图、动作节奏和修炼主题的参照，不应把文化借鉴简化成某一游戏的直接继承。'],['设计比较','《只狼：影逝二度》','可比较防御压力与节奏学习，但双方对群战、移动和成长的组织方式不同。']],
[['PlayStation · Sifu 官方介绍','https://www.playstation.com/en-us/games/sifu/'],['Sloclap · 死亡与衰老设计说明','https://blog.playstation.com/2021/11/18/how-sifus-death-and-aging-system-functions/']]);
exhibit('re4-2005',2005,'生化危机 4','RESIDENT EVIL 4 · ORIGINAL','Capcom',['design','technology'],'horror','#b7c799','重新定义越肩视角下的危险距离。',
'2005 年的《生化危机 4》是动作恐怖与第三人称射击演化中的关键作品。它将固定镜头时代的空间压迫重新组织为角色肩后的近距离判断，让瞄准部位、敌人反应与场地围堵形成一种易于感知的战斗语言。',
'攻击腿部或头部可以制造不同的硬直与体术机会，瞄准时不能移动则迫使玩家在精准攻击和重新站位之间切换。敌群不只是血量目标，它们持续争夺空间，令每一次停步都有风险。',
'村庄开场把有限弹药、被围追的路线和暂时安全的建筑压缩进同一场遭遇。随后商人、背包整理、装备升级和场景变化不断调节压力，使恐怖与游乐场式动作奇观保持独特的交替节奏。',
'越肩视角并非本作凭空发明；其地位来自镜头、战斗和关卡的有效整合与广泛示范作用。它也改变了系列早期偏探索解谜的恐怖结构，因此革新同时意味着取舍。',
[['系列前史','《生化危机》与《生化危机 2》','保留资源管理、解谜与恐怖基底，却显著改变镜头和遭遇节奏。'],['行业比较','《战争机器》与《死亡空间》','是讨论此后越肩动作与恐怖设计的重要后续坐标；具体影响应结合各团队访谈判断。'],['直接重制','《生化危机 4：重制版》（2023）','以可移动射击和刀具格挡重新平衡原作的压力结构。','re4']],
[['Capcom · 原作官方页面','https://www.residentevil.com/4/'],['Capcom · 原作与重制版关系','https://www.residentevil.com/re4/en-asia/']], '2005 原作，与 2023 重制版分别收录');
exhibit('gta-v',2013,'侠盗猎车手 V','GRAND THEFT AUTO V','Rockstar North · Rockstar Games',['world','technology','culture'],'racing','#a5d2aa','开放城市的工业整合，与持续演化的线上社会。',
'GTA V 的代表性来自综合能力：城市模拟、驾驶与射击、多主角任务和流行文化讽刺被组织成极高完成度的开放世界。之后的 GTA Online 又把一次发行的作品延长为长期运营的线上空间，这两部分应分别理解。',
'主线通过三名主角在不同身份与位置之间切换，让大型任务拥有多视角调度。城市中的载具、交通、警察与物理交互则为非脚本事件提供基础；线上模式进一步把内容、成长与社交组织为持续循环。',
'洛圣都不仅是风景，还是关于消费、阶层、媒体和欲望的讽刺舞台。玩家可以追随任务，也可以在同一套城市规则下自行制造事件，这种作者叙事与玩家表演并置的状态构成系列辨识度。',
'世界的自由与任务的严格脚本并不总是一致。GTA Online 的商业生态也不等同于单人作品的叙事成就；长寿与规模不能替代对具体设计质量的判断。',
[['系列积累','《GTA III》→《圣安地列斯》→《GTA IV》','三维城市、活动密度、物理与叙事表现逐代积累，解释了第五部为何更像工业体系的集成。'],['同工作室延伸','《荒野大镖客：救赎 2》','将高密度世界与角色演出积累转入更缓慢的西部叙事。','rdr2']],
[['Rockstar · Steam 官方作品页','https://store.steampowered.com/app/271590/']], '2013 单人原作；另讨论 GTA Online');
exhibit('pong',1972,'乓','PONG','Atari · Allan Alcorn',['medium','culture'],'terminal','#d6e7c9','让屏幕上的互动成为大众生意。',
'Pong 的历史贡献主要是商业化与大众传播。早于它的电子游戏与家用网球游戏已经存在，但它用几乎不需要解释的操作，让电子互动进入酒吧与街机经营空间，帮助产业找到可复制的商业形式。',
'两块球拍、一颗球与直接反馈把复杂技术转译成身体直觉。击球后的速度、方向和声音足以支撑对抗；短局与投币机制让经营者可以围绕单位时间和持续挑战组织收益。',
'它把电视屏幕从被动观看的媒介变成两个人共同争夺的场地。今天看来近乎空白的画面，在当时承载的是一种新的公共行为：玩家能够立即改变屏幕，并与旁人共享结果。',
'不能称它为“第一款电子游戏”。它更准确的坐标，是早期游戏从技术实验走向大众商业娱乐的重要转折，家用 Pong 又属于随后扩展的另一阶段。',
[['更早背景','Magnavox Odyssey 的网球游戏','Pong 之前已存在相似电视网球体验，说明其商业成就应与概念首创分开。'],['直接延伸','Home Pong（1975）','从公共街机空间走向家庭，把类似交互带入客厅。'],['产业后续','《太空侵略者》','将街机循环推向更强的单人挑战与高分追逐。','space-invaders']],
[['The Strong · Pong 历史馆藏','https://www.museumofplay.org/games/pong/']]);
exhibit('space-invaders',1978,'太空侵略者','SPACE INVADERS','Taito · Tomohiro Nishikado',['medium','design','culture'],'terminal','#a6c9af','把难度、声音与高分组织成持续压力。',
'《太空侵略者》是街机文化走向更广泛大众的重要节点。它让玩家面对持续逼近的敌阵，围绕分数与重复挑战组织体验，为街机黄金时代提供了高度易读、又能不断提高技巧的结构。',
'敌阵逐渐逼近，掩体会被破坏，越来越稀疏的敌人又会带来速度变化。规则几乎不增加，压力却持续变化；音效与节奏共同强化了这种逼迫感。',
'它展示了紧张感可以由极少的状态变化构成，而不依赖复杂画面或故事。敌阵的图像识别度又使游戏形象能够离开屏幕，成为大众文化中关于电子游戏的视觉符号。',
'高分追逐与射击并非全部始于本作，其贡献在于把这些元素组织成强传播力的产品。关于硬币短缺等流行传说不作为本馆的历史论据。',
[['商业前史','《Pong》','建立大众街机的商业可行性，本作将重心转向单人迎战与分数。','pong'],['后续类型','《Galaxian》与《Galaga》','固定屏幕射击进一步发展敌人队形、运动与攻击变化。']],
[['The Strong · Space Invaders 历史馆藏','https://www.museumofplay.org/games/space-invaders/']]);
exhibit('tetris',1984,'俄罗斯方块','TETRIS','Alexey Pajitnov',['design','culture'],'gallery','#a4c1ef','以极少规则，构造没有语言门槛的深度。',
'俄罗斯方块代表一种跨设备、语言和年龄传播的纯规则设计。它的生命力并不依赖固定角色或故事，落块、旋转与消行形成可反复解释、也可反复挑战的基本结构。',
'当前方块的摆放会改变之后所有选择的质量。短期腾出空间与长期保留布局之间存在持续权衡，时间压力又阻止玩家永远等待理想答案；复杂性由规则组合而非规则数量产生。',
'玩家亲手制造堆积，也亲手消除混乱。紧张与释放来自同一空间状态的转换，因此它可以在不同视觉包装下保持核心身份，是理解“机制本身具有表达力”的理想样本。',
'1984 年的起点与后来掌机、联网和竞技版本的功能不能混写。便携设备的普及放大了它的影响，但并不意味着所有后续标准规则都存在于最初版本。',
[['非电子游戏来源','拼板与五格骨牌谜题','几何拼合是理解其设计根基的重要背景；实时下落与消行把静态拼图转成持续决策。'],['传播节点','Game Boy 版《Tetris》（1989）','便携硬件与低语言门槛形成强适配，使规则进入更日常的时间片段。'],['后续演化','《Tetris Effect》与《Tetris 99》','分别展示视听体验和多人竞争如何扩展同一核心规则。']],
[['Tetris · 官方历史与作品信息','https://tetris.com/']]);
exhibit('mario',1985,'超级马力欧兄弟','SUPER MARIO BROS.','Nintendo R&D4',['design','culture'],'gallery','#e7a587','让关卡自己教会玩家如何行动。',
'它是横版平台设计的经典语法样本，也是任天堂家用机时代的重要代表。滚动场景、移动手感和关卡教学并非由它一项项从零发明，却在这里形成特别清晰、可持续展开的整体。',
'开场通过敌人、砖块、问号方块和地形安排，让玩家逐步发现跳跃、碰撞与奖励。后续关卡改变这些元素的位置关系，使已有知识面对新的风险，而不必不断增加说明文字。',
'奔跑惯性、跳跃弧线和落点判断让角色的身体具有可学习性。隐藏奖励使熟悉的路线仍保留再探索空间，通关、速度和秘密由此成为不同玩家都能追逐的目标。',
'无文字教学不等于没有失败成本，历史版本的难度与有限续关也构成门槛。它帮助家用机扩张的作用需要放在任天堂平台、渠道和其他作品共同形成的体系中看待。',
[['角色与动作前史','《大金刚》与《Mario Bros.》','角色动作和平台空间逐步积累，最终转成持续向前的横向冒险。'],['系列后续','《超级马力欧兄弟 3》与《超级马力欧 64》','分别扩展二维能力组织与三维行动空间，延续“用关卡变化展开基本动作”的方法。'],['设计比较','《宇宙机器人》','从当代作品回看平台教学与关卡变化的长久生命力。','astro']],
[['Nintendo · Iwata Asks：马力欧的早期设计','https://www.nintendo.com/en-gb/Iwata-Asks/Iwata-Asks-New-Super-Mario-Bros-Wii/Volume-1/1-Mario-Couldn-t-Jump-At-First/1-Mario-Couldn-t-Jump-At-First-210699.html']]);
exhibit('doom',1993,'毁灭战士','DOOM','id Software',['technology','design','culture'],'horror','#e7a179','让高速空间、联网与玩家创作一起扩张。',
'DOOM 是第一人称射击走向大众的重要节点，其意义超出一套战斗规则：实时空间表现、共享软件传播、局域网对战和玩家制作内容共同组成了作品影响力。它让游戏同时成为技术展示与社群平台。',
'快速移动、武器差异和敌人行为把房间变成需要持续阅读的战斗空间。数据文件与引擎的组织方式有利于替换关卡和内容，玩家由使用者逐渐变成扩展作品的人。',
'它的速度来自视觉、声音、动作反馈与资源配置的共同作用。关卡不只是走廊背景，而是可以被探索、被理解、也被重新创作的结构；这种开放性使作品不完全受官方内容寿命约束。',
'原作不应被描述为现代意义上的完整多边形三维世界，其空间表示有明确限制。它也不是第一款第一人称游戏，成就在于技术效率、产品设计与分发生态的有效结合。',
[['直接技术前史','《Wolfenstein 3D》','id Software 更早的高速第一人称射击探索；DOOM 进一步丰富空间、光照与遭遇设计。'],['同团队后续','《Quake》','推进真正的三维几何、网络对战与模组生态，是理解后续引擎文化的重要节点。']],
[['The Strong · DOOM 历史馆藏','https://www.museumofplay.org/games/doom/']], '1993 原作；展图来自官方再发行合集');
exhibit('pokemon',1996,'宝可梦 红／绿','POKÉMON RED / GREEN','Game Freak · Nintendo',['culture','world','design'],'gallery','#e6b4ac','让收集的终点，出现在另一个人手里。',
'《宝可梦 红／绿》把收集、养成和交换组织成了具有现实社交后果的游戏结构。其文化意义不仅是角色数量众多，而在于掌机之间的连接成为理解与完成这套世界的一部分。',
'版本差异、交换进化和通信对战让单机旅程延伸到现实中的同伴。不同属性与队伍选择形成易进入的策略层次，捕获和命名又使数值单位获得私人记忆。',
'一只宝可梦可以同时是战斗选择、收藏缺口和朋友赠予的对象。系统因此把数字资产变成关系的载体，而动画、卡牌等后续媒介进一步让同一世界在不同生活场景里可见。',
'跨媒介帝国不是首发软件单独完成的，需要持续角色设计、发行与授权共同作用。日版红／绿与之后海外红／蓝的版本差异也应保留，不能简单互换名称与年份。',
[['类型根基','日式角色扮演与收集玩法传统','回合战斗和成长系统已有长期积累，本作把重点进一步转向生物收集与玩家交换。'],['直接续作','《宝可梦 金／银》','在原有世界关系上扩展时间、养成与探索结构。'],['跨媒介延伸','宝可梦动画与卡牌游戏','是共享角色世界的扩展，不等同于电子游戏玩法的直接续作。']],
[['Pokémon · 红／绿版本与通信介绍','https://www.pokemon.co.jp/ex/VCAMAP/game/']], '1996 日本首发：红／绿');
exhibit('ocarina',1998,'塞尔达传说：时之笛','THE LEGEND OF ZELDA: OCARINA OF TIME','Nintendo EAD',['design','technology'],'fable','#d5d3a3','为三维世界建立看、走与战斗的秩序。',
'《时之笛》是二维动作冒险进入三维时代的关键设计样本。它没有仅把旧地图变成立体，而是重新解决镜头、目标、移动和谜题之间的关系，让复杂空间可以通过有限按钮被清晰操作。',
'Z 锁定把敌人与角色组织到可读的相对关系中，情境动作减少操作负担，迷宫通过空间结构与道具能力逐步提出问题。镜头不再只是观看工具，也成为战斗和探索规则的一部分。',
'时间变化、音乐与空间回访共同改变熟悉地点的意义。同一地点在不同人生阶段呈现不同情绪，使成长不仅由剧情告知，也由玩家对空间的记忆来感受。',
'锁定的概念与三维探索并非全部始于它；更准确的评价是将这些设计组织成极具影响力的范式。原作的镜头和操作也受到当时硬件条件限制。',
[['系列前史','《塞尔达传说：众神的三角力量》','探索、道具与迷宫之间的互相解锁关系，是三维化前的重要基础。'],['直接开发背景','《超级马力欧 64》','任天堂开发访谈明确讨论了三维目标锁定问题在此前开发中的积累。'],['系列后续','《梅祖拉的假面》','在相近基础上把时间循环推成更集中的结构核心。']],
[['Nintendo · 原开发团队访谈：Z 锁定','https://iwataasks.nintendo.com/interviews/3ds/zelda-ocarina-of-time/1/2/'],['Nintendo · 二维到三维的开发背景','https://iwataasks.nintendo.com/interviews/3ds/zelda-ocarina-of-time/1/1/']]);
exhibit('wow',2004,'魔兽世界','WORLD OF WARCRAFT','Blizzard Entertainment',['world','culture'],'fable','#e1c28c','把持续在线的世界，变成日常社会。',
'《魔兽世界》不是大型多人在线角色扮演游戏的起点，却是这一类型进入大众视野的重要代表。它把已有的持续世界、职业协作与角色成长，组织成更具可读性的任务路线与长期生活节奏。',
'任务引导玩家从一个区域进入下一个区域，副本与职业分工产生协作需求，装备成长和公会组织又把一次游玩连接到未来约定。世界因此既提供个人目标，也制造持续的人际依赖。',
'角色名、公会身份、集合地点与共同经历会在游戏外继续存在。它的内容不只来自开发者设计的任务，也来自玩家形成的组织、仪式与记忆，这是持久在线世界独特的媒介能力。',
'后续资料片长期改变了系统，2004 年首发不能与任意当代版本混为一谈。日常参与和固定团队也会变成时间义务，社会黏性与玩家负担是同一结构的两面。',
[['类型前史','《Ultima Online》与《EverQuest》','持久世界、玩家社会和团队冒险已存在，本作对进入门槛与任务节奏作了新的组织。'],['世界观前作','《魔兽争霸 III》','把此前战略游戏中的角色和地理转化为可亲身穿行的空间。'],['类型后续比较','《最终幻想 XIV》','可比较持续运营世界如何在个人叙事、组队内容和社群生活之间分配重心。']],
[['Blizzard · 魔兽世界官方网站','https://worldofwarcraft.blizzard.com/']], '2004 首发；后续版本机制另有演变');
exhibit('minecraft',2009,'我的世界','MINECRAFT','Markus Persson · Mojang',['world','design','culture'],'gallery','#a5cdb1','把游戏交给玩家继续创造。',
'《我的世界》把生存游戏、建造玩具和创作平台结合到可直接理解的方块系统中。它的代表性不是地图无限大，而是玩家可以反复改变环境，并把这种改变变成个人表达、协作目标和可传播的内容。',
'采集、合成与建造形成从资源到工具、再到更大行动范围的循环。统一的方块尺度降低组合门槛，生存模式制造目标压力，创造模式则释放空间表达，两者共享同一种材料语言。',
'一座建筑既是作品，也是玩家耗费时间和共同合作的记录。游戏允许规则系统与想象力相互补充，因此它能承载私人住所、复杂装置、教育活动或多人社会，而不要求所有人追求同一个结局。',
'2009 是首次公开开发阶段，正式 1.0 版发布于 2011 年。后续红石、更新和创作者生态的全部成就不能倒写成最初版本；开放创造也需要社群管理与长期维护。',
[['设计前史','《Infiniminer》与《Dwarf Fortress》','方块挖掘建造、程序世界与系统化生存是理解早期创作背景的重要参照。'],['同类比较','《Terraria》','可比较采集、建造和探索如何在二维空间中得到另一种组织，而不把相似视为单向继承。'],['媒介扩展','教育、服务器与创作者内容','其后续影响不只体现为某一款续作，也体现在游戏成为生产其他体验的平台。']],
[['Mojang · Minecraft 官方网站与教育产品','https://www.minecraft.net/']], '2009 首次公开；2011 正式发行');

;

/* awards.js */
/* Original critical essays; award years refer to ceremonies, not port releases. */
function accession(d){
  const [id,order,title,en,maker,genre,style,color,themes,features,headline,intro,chapters,verdict,media,relations]=d;
  if(games.some(g=>g.id===id))throw new Error('Duplicate accession: '+id);
  games.push({id,order,year:Math.floor(order/10000),title,en,maker,genre,mode:'单人',style,color,themes,features,tags:[],personal:false,edition:'原始发行版；后续移植配图另行标注',impact:headline,position:'',innovation:'',unique:'',boundary:'',sources:[[media[0],media[1]]],relations,review:{headline,intro,sections:chapters.map(c=>({title:c[0],paras:c.slice(1)})),pull:headline,verdictTitle:'本馆判断',verdict,media:{name:media[0],url:media[1],note:media[2]}}});
}
accession(['oblivion',20060320,'上古卷轴 IV：湮灭','THE ELDER SCROLLS IV: OBLIVION','Bethesda Game Studios','动作角色扮演','fable','#b6ad7c',['奇幻','帝国','冒险'],['开放世界','公会任务','角色养成','自由探索'],
'真正诱人的不是拯救帝国，而是在帝国里过另一种人生。',
'离开下水道时，眼前的湖水与远处的遗迹提供了一种朴素而强大的承诺：这些地方都可以去。《湮灭》的力量不是主线不断催促你成为英雄，而是允许你带着一封重要的信，先去做盗贼、角斗士或炼金术士。它把角色扮演从剧情中的身份选择扩展为日常行动的选择，也把自由带来的拖沓、荒谬和失控留在了作品内部。讨论这部游戏，必须同时承认这两面。',
[
['自由从角色表走进生活','种族、星座、自定义职业和主要技能共同决定开局，但角色的样貌更多来自之后的习惯。反复使用一项技能会推进它的成长；开锁、潜行、施法和交涉因此不仅是通过关卡的手段，也是你在塑造的人。这套设计延续《晨风》，却通过即时旅行、任务标记和更直观的战斗反馈降低了进入门槛。它没有发明开放世界，重要贡献是让庞大的电脑角色扮演传统在新一代主机上变得更容易被理解。','代价同样具体。箭头会让人只盯着目标，快速旅行会省略地理距离，升级又可能带来敌人的同步变强。玩家想自由地生活，系统却要求考虑什么技能该算主要技能；这种角色幻想与成长算术的冲突，是原版最值得批评的结构问题。'],
['支线像短篇小说集','公会任务的好处不在数量，而在经常改变你以为自己正在做的事情。画作中的世界、围绕一场聚会展开的暗杀、竞技场里的身份悲剧，都让常见的探索和战斗拥有特别的语境。黑暗兄弟会尤其擅长把任务目标转化为表演：你不只是清空一个房间，还要考虑别人如何理解房间里发生的事。','这解释了为什么很多人记住支线胜过主线。帝国危机提供背景压力，公会却给予持续的社会身份。任务不必在地图上无限分叉，只要行动过程、口吻与奖励建立清晰的组织文化，就足以让玩家觉得自己加入了一个群体。'],
['一座有生活秩序、也会露馅的舞台','NPC 的作息、吃饭、交谈和巡逻让城镇拥有演出之外的时间。它们当然没有真正独立的生活，重复台词和突兀表情还会揭穿幻觉；但当规则偶然相撞，卫兵追捕、路人反应与玩家的小动作就会组成计划之外的故事。此处的沉浸来自可以干预，而非每一帧都逼真。','西罗帝尔明亮的林地与古典配乐也值得单独评价。它们给探索留出舒展的呼吸，与湮灭门后的焦灼红色形成对照。原版的人脸和近战动画今天显得粗糙，不过环境的温暖仍能说明：奇幻世界不一定靠黑暗和残酷才具有吸引力。'],
['等级同步削弱了什么','当沿途敌人与奖励持续随玩家等级变化，世界容易失去自身的危险层级。升级本该扩大行动空间，却有时只是换来更耐打的对手；同一段探索在数值上更辛苦，在决策上未必更丰富。它解决了随便走就误入死地的问题，却削弱了战胜原先不可战胜之物的成长感。','重复的洞穴结构和湮灭门进一步放大这种疲劳。专业评价不能只把自由当作挡箭牌：内容允许跳过，不等于内容本身的变化不足就不存在。最合适的游玩方式是让好奇心决定节奏，而不是把地图清空当成目标。'],
['站在《晨风》之后，通向《天际》','《湮灭》可以看作两种价值之间的桥：前作更陌生、更依赖阅读的世界，与后作更直观、更强调整体幻想的旅行。它的公会叙事、可拾取物件和技能使用制，仍属于同一套模拟生活的传统；技术呈现与操作入口的升级，则让这套传统进入更广的受众。','2006 年 VGA 年度游戏记录了当时的认可，但不能替代今天的判断。本馆收藏的是 2006 年原作。2025 年重制增强版改变的画面和部分成长规则，需要另行讨论，不能倒过来算成原版已经完成的改进。']
],
'它是一部不够整齐、却让人愿意住进去的角色扮演游戏。最值得保存的是公会短篇与生活系统相遇时产生的身份感；最大的缺陷则是等级同步把探索的自然起伏磨得过平。适合愿意偏离主线、接受旧式操作并自己决定旅程重心的人。',
['RPGFan · 2006 年 Xbox 360 版评测','https://www.rpgfan.com/review/the-elder-scrolls-iv-oblivion-2/','评测肯定世界规模与定制空间，同时指出主线被自由探索稀释、战斗与技术存在瑕疵。'],
[['直接前作','上古卷轴 III：晨风','更陌生的文化、文本与探索引导，是理解本作简化方向的起点。'],['直接后作','上古卷轴 V：天际','进一步压缩职业入口，用更统一的地域幻想承载自由生活。','skyrim']]]);

accession(['bioshock',20070821,'生化奇兵','BIOSHOCK','2K Boston / 2K Australia','第一人称射击','horror','#4aada7',['反乌托邦','海底都市','科幻'],['环境叙事','能力组合','资源管理','作者表达'],
'一座海底城市，让“听从任务指令”也成为值得怀疑的行为。',
'《生化奇兵》最先令人信服的是空间：装饰艺术的奢华仍在，城市的秩序却已经腐烂。玻璃之外是不能逃离的深海，玻璃之内是把理想写成广告、把身体改造成商品的人。这不是一段剧情套上一层射击外壳，而是让武器、商业设施、录音和建筑共同讲述一个社会如何理解自由，最后又如何被自己的逻辑吞噬。以下评论保留关键转折。',
[
['射击的对象不只有敌人','枪械提供直接伤害，质体则让电、火、念力等能力进入战斗。看到积水时可以思考导电，面对安保设施可以考虑黑入或利用它攻击敌人，搬动物体也可能替代浪费弹药。它继承《网络奇兵 2》的资源压力与环境互动，但把复杂的角色系统压缩为更容易读懂的动作选择。','真正有趣的不是“能力很多”，而是战前观察会改变战中的成本。大老爹不是普通杂兵的放大版：是否现在交战、在哪里布置陷阱、有没有足够补给，构成一段小型准备过程。敌人因此成为一种局部生态，而不仅是沿路刷新的一组靶子。'],
['极乐城首先是一个论点','城市的建筑把财富与技术进步展示在最显眼的位置，维护城市的劳动与失败者则退到背后。玩家不断从辉煌的陈述走进失败的现场，广告和录音之间的落差成为叙事动力。环境并非只是补充世界观；它经常比角色口中的自我辩护更可信。','录音日志也有局限。它允许玩家边行动边听，但容易把复杂的人物降为等待拾取的解释材料。优秀的环境叙事并不意味着没有信息灌输，而是即使错过几段录音，城市的价值秩序仍能从场景和规则中被感受到。'],
['道德选择与经济选择并不等价','小妹妹提供一条显眼的道德轴线：眼前力量与对弱者的态度发生关系。问题在于，奖励平衡会影响选择的重量。若善行长期获得相近的资源补偿，玩家便未必真的牺牲了什么；一个看似尖锐的问题可能被系统悄悄化解。','因此本作更有穿透力的部分，是对玩家接受指令这一习惯的审视。许多游戏把服从目标视为天然行为，它却利用这种约定制造不安。这里的思想性不是出现几个哲学名词，而是让操作者意识到自己的参与方式也有被安排的成分。'],
['美术与声音把城市变成身体经验','铜绿、暖灯、漏水与旧时代流行音乐互相冲撞，使极乐城既迷人又难以信任。空间并不总靠黑暗吓人，反而常让熟悉的奢华失去正常用途：商业陈列成了暴力现场，公共广播仍维持热情，生活却早已崩塌。声音给危险提供方向，也让文明残余比怪物更令人不安。','这种统一性使画面老化后作品仍有身份。纹理精细度可以被后来者超越，所有视觉材料共同服务一个社会寓言的组织方式，却不能简单靠提高预算复制。它也证明写实射击之外存在另一种大制作美学。'],
['经典的边界仍然清楚','重复的黑客小游戏、后段战斗的惯性与部分较直白的收束，会让前半程的神秘逐步退去。复活机制降低挫败，却也会削弱资源战的危险感。游戏在大众射击与沉浸模拟之间选择了折中，不能因思想表达出色就把其系统深度说成没有代价的全面胜利。','2007 年 VGA 年度游戏只是其时代坐标。《生化奇兵 2》继续钻研城市与战斗，《无限》换用另一座极端社会；而与《传送门》并置时，还能看见同一时期两种对任务权威的不同质疑。它们是有价值的比较关系，不应轻率写成彼此直接影响。']
],
'值得收藏的核心是规则、空间与思想之间的相互支撑。它并非最自由的沉浸模拟，也不是枪感最纯粹的射击游戏，却让大众动作体验容纳了对自由和服从的反思。愿意观察环境、接受适度资源压力的玩家，会比只追求战斗效率的人读到更多。',
['WIRED · 2007 年评测','https://www.wired.com/2007/08/bioshock-review/','评测关注道德处境、环境表达与超能力战斗，也批评黑客小游戏的重复。'],
[['设计前史','网络奇兵 2','资源紧张、录音叙事与能力构筑，是本作的重要创作传统。'],['同代对照','传送门','两者都让目标指令本身进入叙事讨论，表达路径不同。','portal']]]);

accession(['gta-iv',20080429,'侠盗猎车手 IV','GRAND THEFT AUTO IV','Rockstar North','开放世界动作','terminal','#91a9bd',['犯罪','移民','都市'],['开放世界','驾驶','社会讽刺','角色叙事'],
'自由城越像一个真实的地方，美国梦就越难轻松兑现。',
'尼克来到自由城时，城市先是一张被亲人夸大的明信片，随后变成租住的房间、要还的债和不得不接的工作。《GTA IV》把系列熟悉的犯罪升迁故事压低了色温。它仍允许荒唐驾驶和大规模混乱，但主角的疲惫与城市的重量不断提醒玩家：拥有行动自由，与真正摆脱过去，并不是同一件事。',
[
['从地图面积转向街区密度','相比《圣安地列斯》的多城跨度，本作把精力集中到一座更具质感的都市。街道的坡度、不同区域的建筑、车流与行人的细碎反应，让重复经过一条路也能形成地理记忆。城市不必每隔几步都塞入活动，交通和空间本身就可以传达阶层与生活方式。','从行业角度看，这是开放世界评价方式的一次重要转向：更大不再是唯一答案，物理反馈、动画和环境行为可以增加单位空间的可信度。它不是现实城市模拟器，却善于在玩家最常接触的界面上制造一致的重量感。'],
['沉重的驾驶是一种审美选择','车辆的侧倾、制动距离和碰撞惯性，要求玩家提早读路。它不像更轻快的街机驾驶那样随手扳回方向；追逐会因为一个过快的弯道突然失控。喜欢精确爽快的人可能觉得迟钝，喜欢把车当作有质量物体的人则会觉得城市因此成立。','枪战加入更明确的掩体与瞄准反馈，使系列从混乱交火走向较可控的战术推进。但关卡依旧经常用大量敌人延长任务，掩体机制的改善没有完全解决射击结构单调的问题。反馈升级与战斗深度，应该分开评价。'],
['尼克让讽刺拥有了受伤的身体','广播、广告与虚构互联网继续嘲讽消费社会，主线却不只满足于让玩家笑。尼克的战争经历与迁徙身份，让“来这里重新开始”变成一个不断受现实反驳的愿望。他与亲友的相处，也把自由城从资源地图变成有人情债的地方。','这种写法并不总与自由游玩相容。玩家在街头制造的混乱，与剧情里对暴力后果的严肃态度可能距离很远。它没有消除开放世界的叙事矛盾，而是让矛盾更显眼：系统鼓励的玩耍方式，有时比剧本愿意承认的更残酷。'],
['朋友来电与被安排的自由','保龄球、酒吧和朋友邀约让关系不只发生在过场里。这些日常活动最初能提供真实的陪伴感，频繁出现后却容易变成管理好感的负担。系统想表达朋友需要时间，玩家感受到的也可能只是另一种任务提醒。','同样，部分长任务的失败重来会让试错成本偏高。细节越丰富，重复一段已知流程时越容易感到它在占用时间。专业回看应承认这些体验阻力，而不能把所有不便都美化成写实。'],
['它为系列留下了另一条道路','《GTA V》后来强调多主角切换、更开阔的地域反差和更鲜明的娱乐节奏；IV 则保留了更集中的人物视角与阴郁城市气质。两者不是简单的新旧替代，而是开放世界如何服务不同情绪的对照。','2008 年 VGA 年度游戏肯定的是当时这一整套城市体验。本馆以原版为评论对象；后来的 PC 技术状况和整合版本需要另行核对，不把移植问题或后续内容混入当年的设计结论。']
],
'《GTA IV》的不可替代性在于自由城与尼克彼此塑形。它的驾驶、社交与任务重试都可能令人不耐烦，但这些问题不妨碍它成为观察开放世界如何承载移民叙事与城市气质的关键作品。它最适合被当作一座有情绪的城市慢慢认识。',
['GamesRadar+ · 2008 年 PS3 版评测','https://www.gamesradar.com/grand-theft-auto-iv-2/','评测强调城市沉浸感与整体娱乐表现，同时并未将作品视为毫无缺陷。'],
[['系列前史','侠盗猎车手：圣安地列斯','从地域广度与成长系统，走向更密集的城市表现。'],['直接后作','侠盗猎车手 V','以多主角和洛圣都的明亮反差重新组织系列。','gta-v']]]);

accession(['uncharted-2',20091013,'神秘海域 2：纵横四海','UNCHARTED 2: AMONG THIEVES','Naughty Dog','动作冒险','fable','#c8a678',['寻宝','冒险','雪山'],['电影化叙事','攀爬','掩体射击','线性流程'],
'电影式游戏的魅力，在于让你亲手跨过那道正在坍塌的边缘。',
'德雷克从悬挂在雪崖边的列车中醒来时，玩家并不需要先了解复杂的世界设定。抓住、爬上去、别掉下去，动作已经解释了一切。《神秘海域 2》最强的能力，是让观赏与操作在同一个节拍上发生：你知道它经过精密编排，却仍会因为最后一次跳跃是自己完成的，而把惊险记成自己的经历。',
[
['线性并不意味着没有设计','本作的大部分路线有明确的唯一方向，攀爬也不是自由解题。但引导、视线与危险变化形成一条细致的节奏曲线。玩家先看见目标，再在移动中理解障碍，最后完成一个看似险些失败的动作。难度未必很高，参与感却来自不断交还给玩家的控制。','这类设计的价值不在分支数量，而在每一步是否值得执行。它沿用《古墓丽影》等作品的冒险传统，将攀爬、掩体和脚本化灾难组织得更紧密。所谓电影化并非取消玩法，而是把玩法的时间安排得像剪辑。'],
['列车把场景变成一个动词','列车段落并非只在背景播放移动风景。车厢之间的跳跃、不断变化的交火距离与结构破坏，让空间处于持续变动中。地形既是战斗场所，也是事件本身；玩家必须在移动平台上适应新的位置关系。','城市追逐、雪地与遗迹又不断更换视觉和操作温度。强度较高的射击之后，安静步行和轻量解谜给人整理情绪的时间。若只截取爆炸片段，就会忽略它真正高明的是把爆炸放在了什么位置。'],
['角色关系让动作值得被关心','德雷克的魅力不是永远正确，而是玩笑、犹豫和求生本能之间的摇摆。伙伴对话把说明任务的工作转化为关系交流，角色动作与表情又让彼此熟悉、猜疑和依赖不必总靠台词讲清。寻宝故事因此有了比宝物更贴近人的牵引。','但这种轻松也有边界。主角在过场里的可亲，与流程中持续杀敌的数量并不总能协调。作品选择冒险片的夸张约定来容纳它，玩家是否接受这一约定，会直接影响对故事可信度的评价。'],
['枪战够用，却不是所有时刻都同样出色','垂直空间与掩体给战斗提供位置变化，潜行也能在一些遭遇开局减少压力。不过射击本身的精确感和敌人反应并非同类作品中最干净利落的，后段高强度敌人和持续交火可能压过原本优雅的节奏。','轻量解谜有助于让更多玩家顺畅前进，也意味着谜题很少要求长时间推理。它擅长让你像冒险家一样经历一段故事，而不是让你真的承担考古学家式的复杂判断。这是清楚的取舍，不必被包装成任何口味都适合的完美。'],
['它确立的是一种制作尺度','2009 年 VGA 年度游戏记录了本作在当时的冲击。更长远的价值，是它展示了动画、场景破坏、表演、音效与交互如何共同承担叙事，而不是把故事全推给过场。行业里的电影化大作因此有了一个极具说服力的参照。','《神秘海域 4》后来增加人物回望与更宽阔的遭遇空间，《最后生还者》则让同一工作室把手工编排转向更沉重的资源与伦理压力。它们共享制作经验，却拥有不同的情绪目的，不宜简单归为一种公式。']
],
'这是一部用完成度证明线性价值的动作冒险。它未必提供最多自由或最深战斗，却在操作、景观和人物之间建立了极为顺畅的接力。若你期待一段紧凑、有人情味的寻宝旅程，它至今仍是理解电影化游戏为何成立的好入口。',
['GamesRadar+ · 2009 年原版评测','https://www.gamesradar.com/uncharted-2-among-thieves-review/','评测特别重视环境变化、叙事与整体冒险体验。'],
[['系列起点','神秘海域：德雷克船长的宝藏','提供人物、寻宝与动作框架，续作提升了整体节奏。'],['同工作室演进','最后生还者 第 II 部','同样重视手工场景与表演，却把参与感引向更不安的情绪。','tlou2']]]);

accession(['rdr',20100518,'荒野大镖客：救赎','RED DEAD REDEMPTION','Rockstar San Diego','开放世界动作','western','#be694c',['西部','家庭','时代终结'],['开放世界','骑行','死亡之眼','角色叙事'],
'当边疆不再属于亡命徒，回家也成了一场无法自主的远征。',
'约翰·马斯顿追逐的并不是更高的江湖地位，而是从过去手里赎回一个普通家庭的未来。《荒野大镖客：救赎》让开放世界拥有一种逐渐收紧的方向感：荒野看似无边，国家、旧友与承诺却不断决定你必须去哪里。它的西部不只是一种装饰，而是一个关于自由如何被时代重新定义的舞台。',
[
['空旷本身就是内容','草原、尘土、山脊和远处的小镇之间有足够距离，让骑行不只是菜单前的等待。地形轮廓、天气与路边事件会不断轻微改变旅行的感受。它把都市开放世界里密集的交通和人群，换成有节制的相遇，证明内容密度也可以由预期和间隔来组织。','关键不是每次出门都遇到稀有事件，而是世界似乎并不完全以任务为单位存在。野生动物、陌生人的求助与突然的冲突，给穿越提供了不确定性；马则成为感受地理的媒介，让路途与角色的漂泊身份贴合。'],
['死亡之眼把枪手幻想变成可操作规则','减缓时间与标记目标，把西部片里瞬间决定生死的对峙转化为玩家可以控制的节奏。它降低了连续精准射击的门槛，同时保留选目标和出手时机的判断。普通掩体交火因这一机制而具有明确的类型身份。','问题也正在这里：如果太多战斗都依赖同一套清场方法，幻想会稳定成立，策略却容易趋同。任务中的驾车、骑马和枪战组合不总能持续提供新判断，数量很多的敌人有时只是延长流程。'],
['一个想退出故事的人','马斯顿不像典型的上升型犯罪主角，他的目标是结束旧生活。这使他与奇人、官员和旧日关系的相遇带上疲惫的幽默。世界仍然会把人的野心写成闹剧，主角却不能只把一切当笑话，因为家人是具体的牵制。','不触及关键结局也可以看出本作的结构：它持续让私人承诺与公共权力产生摩擦。玩家为了回归日常而完成暴力任务，行动上的前进未必意味着处境上的自由，这种落差赋予旅程一种宿命感。'],
['音乐知道何时应该出现','大量自然声与克制的配乐，使少数完整歌曲进入旅途时具有异常鲜明的记忆力。声音不是持续填满空白，而是等待玩家已经用身体感受到距离之后，再替这段路命名。景观、移动和情绪在这里形成共同的时间。','旧版动作与控制并非处处轻便。转身、掩体切换和同伴跟随会暴露年代感；但审视这些阻力时，也应区分有意保留的步调与纯粹不够顺畅的交互，不能把两者统统归为沉浸。'],
['先有终局，再有前传','它继承《Red Dead Revolver》的西部血统，也借用了 Rockstar 已有的开放世界任务组织经验。2018 年《救赎 2》作为前传，让玩家理解旧关系如何走向这里；原作则拥有更直接、更紧凑的主题轨迹。先玩哪一部会改变情绪顺序，但不会让另一部失去价值。','2010 年 VGA 年度游戏对应的是当年作品，不是后来重新发行时加入的技术选项。将它与前传并列收藏，能看见相同题材如何在不同制作规模下，把日常与历史之间的距离写成游戏。']
],
'本作的价值是把西部的终结感写进旅行和任务，而不仅是写进对白。它的枪战会重复，操作也有旧时代的棱角，却在空旷景观、歌曲与马斯顿的家庭愿望之间建立了不可替代的情绪关系。',
['GamesRadar+ · 2010 年评测','https://www.gamesradar.com/red-dead-redemption-review/','评测肯定世界丰富度与整体完成度；本馆更关注它如何用空旷、旅途和家庭动机组织情绪。'],
[['题材前身','Red Dead Revolver','更关卡化的西部动作传统，不能与本作开放世界直接等同。'],['故事前传','荒野大镖客 2','补全马斯顿旧日关系的形成过程。','rdr2']]]);

accession(['skyrim',20111111,'上古卷轴 V：天际','THE ELDER SCROLLS V: SKYRIM','Bethesda Game Studios','动作角色扮演','fable','#b5c7ce',['北欧奇幻','荒野','巨龙'],['开放世界','技能成长','模组文化','自由探索'],
'一个好世界，会让你忘记自己最初为什么走上这条路。',
'《天际》的典型时刻并不是完成预定任务，而是在途中看见一处废墟，顺着山路走进去，出来时已经拥有另一段计划。它的北方省份把山、遗迹、城镇和传说连接成可以不断偏航的旅行。角色扮演不再主要依靠开局选定的职业说明，而是通过几十小时里反复做出的行动逐渐形成。',
[
['先行动，再决定自己是谁','技能随着使用成长，专长树把长期偏好变成更明显的能力倾向。取消传统职业选择，让玩家可以先试弓箭、法术或双手武器，再逐步形成路线。双手分配装备与法术则让构筑以更直接的方式进入操作。','这种开放并非没有损失。法术系统的一些自由组合被压缩，不同公会的准入与身份也未必足够排他。你可以成为很多组织的核心人物，却不一定真正感到这些身份之间的冲突；自由兼容一切时，角色的独特性可能变薄。'],
['地标比任务清单更早吸引视线','山峰、城堡、龙的巢穴和古老墓室给地图提供清晰的方向感。玩家即使没有读取完整的任务说明，也能对远处产生一个具体问题：那里是什么，我怎样过去？道路上的小事件又不断把这个问题改写。','优秀的开放世界往往不需要每个地点都同样复杂。天际的强项是将视觉承诺、短途旅行和可获得回报持续连接起来。弱项则是洞穴和墓穴里相似的敌人与机关容易显露生产模板，尤其当玩家连续清理同类地点时。'],
['龙裔的力量需要一个足够冷的世界','龙吼把主线身份直接转化为能力，让古老语言不仅是背景知识。巨龙与山脉的尺度、合唱与冷色景观形成统一的北方幻想。配乐有时宏大，有时退回轻微的旋律，为漫长步行留出安静。','与《湮灭》较温暖的古典奇幻相比，本作的地域气质更集中。它的审美胜在整体可辨认性：即使单独的动画与材质已经过时，只看天际线、石造遗迹和雪地色彩，也能认出这个世界。'],
['战斗与剧本并没有同样自由','近战命中反馈、敌人战术和队友寻路都存在粗糙处。潜行弓箭之所以成为广泛讨论的玩法，也折射出部分系统组合比其他路线更省力、更稳定。数值成长可以维持回报，却不能完全替代战斗互动的变化。','任务常允许多种到达方式，关键情节却经常沿预定路线收束。游戏提供的是行动与生活安排的自由，不是每段故事都拥有同等深度的分支。承认这种区别，才能理解它为何极易让人沉迷，也为何有人玩久了会觉得人物只是通向下一个地点的接口。'],
['模组让作品超出首发版本','模组社群为角色扮演补上新规则、视觉、任务与生活细节，使同一作品成为持续被改写的平台。这不是原版设计的全部功劳，但开放的工具传统与足够有吸引力的世界，为后续创作提供了土壤。','2011 年 VGA 年度游戏属于原始发行版本。本馆不会把多年模组、特别版和周年版的改进全部追认给首发版；它的历史地位应当同时包含原版创造的入口，以及玩家长期参与后形成的文化生命。']
],
'《天际》最伟大的成就是让偏离计划成为旅程的主要乐趣。它并非战斗和分支叙事的最高峰，却用鲜明地域幻想、低门槛成长与持续可改写性，创造了一种极具生命力的开放世界生活。',
['PC Gamer · 原始评测回刊','https://www.pcgamer.com/the-elder-scrolls-v-skyrim-review/','评测重视玩家自行发现的冒险与开放世界的持续吸引力；回刊页面不等于新版评测。'],
[['直接前作','上古卷轴 IV：湮灭','从职业、等级同步与公会传统理解本作的简化与保留。','oblivion'],['开放世界对照','塞尔达传说：旷野之息','同样奖励偏航，但更依靠物理规则和地形互动。','botw']]]);

accession(['walking-dead',20120424,'行尸走肉：第一季','THE WALKING DEAD: SEASON ONE','Telltale Games','叙事冒险','comic','#b49b70',['末日','亲情','伦理'],['对话选择','限时抉择','章节叙事','角色关系'],
'决定故事重量的，不总是你改变了什么，也可能是你愿意为谁负责。',
'李与克莱门汀的关系让《行尸走肉》第一季拥有了比灾难规模更清楚的核心。玩家不是抽象地拯救世界，而是在恐惧、饥饿与不完整信息中，尝试成为一个孩子可以依靠的人。它削弱了传统冒险游戏的谜题负担，把最困难的操作移到语言和判断上：当没有足够时间想清楚时，你会先说什么？',
[
['把解谜压力移到人际压力','传统点击冒险往往要求寻找唯一正确的物品组合，本作则让对话选项和有限时间承担紧张感。说出一句话的后果不总是立刻可知，沉默本身也可能成为一种态度。玩家因此不只是破解作者的谜底，而是在暴露自己的优先级。','动作与探索并没有消失，只是为人物处境服务。补给不足、路线危险和身体脆弱，让一段交谈不只是可任意重读的文本。轻量操作帮助更多人进入故事，但偶发的快速反应段落仍可能显得机械。'],
['情感上的分支与结构上的分支','很多选择改变的是关系、对白或你对自己的理解，未必让主线走向完全不同的终点。如果把它当作一棵无限扩张的故事树，确实会失望；它更像一段有确定大方向、但参与者态度会改变意义的经历。','这种设计值得肯定，也应接受批评。强调“角色会记住”会提高玩家对长期后果的期待，若实际反馈过轻，承诺就会透支。评价关键不是结局数量，而是作品是否在自己的叙事尺度上认真回应了选择。'],
['照顾一个人比赢得辩论更难','李需要在一群同样害怕、同样有私心的幸存者之间周旋，但克莱门汀的存在改变了选择的目标。你可能为了眼前安全做出不愿被她看见的事，也可能为了保留某种做人方式承担风险。角色关系由此成为贯穿所有章节的隐形规则。','它有效地利用了游戏媒介的参与性：同样一件令人难过的事，亲手决定如何面对与被动观看，产生的责任感不同。这里不需要假装玩家真的拥有无限权力，有限的权力反而更容易让人意识到自身的局限。'],
['漫画式画面为不安留出距离','粗线条与略显僵硬的表演没有追逐电影级写实，反而让血腥与情绪可以处在同一套漫画语言中。配音、停顿与人物视线承担了大量细节。它说明人物可信度并不完全依赖最高成本的动作捕捉，关系建立的过程更关键。','技术问题则不能因此被忽略：卡顿、读档、镜头切换和不同平台的体验差异，都可能打断一段非常依赖连续情绪的故事。对叙事游戏而言，性能稳定不是附属指标，而是叙事结构的一部分。'],
['一季故事改变了冒险游戏的入口','分章发行把游戏组织成连续剧式的等待与讨论，选择统计又让私人判断进入社群比较。2012 年 VGA 年度游戏的意义，在于当年一部以人物与抉择为重心的冒险作品获得了大型奖项的中心位置。','它继承 Telltale 与更早点击冒险的传统，也与《暴雨》等互动叙事并处同一时代。后来大量章节式选择游戏借鉴了这种可辨认形式，但形式复制并不能自动复制李与克莱门汀关系的累积重量。']
],
'这部作品应该以人物关系的持续可信度来评价，而不是只数分支。它有收束明显和技术粗糙的问题，却证明游戏可以把“如何照顾别人”变成一条足够有力的主轴。建议按章节完整体验，并保留第一次选择的犹豫。',
['GamesRadar+ · 2012 年全季评测','https://www.gamesradar.com/the-walking-dead-review/','评测聚焦难以用简单对错判断的选择，以及由此形成的情绪记忆。'],
[['互动叙事对照','底特律：变人','以更可视化、规模更大的分支回应选择；两者的情绪目标不同。','detroit'],['类型传统','经典点击冒险游戏','从物品谜题的唯一答案，转向时间压力下的人际判断。']]]);

;

/* additions.js */
accession(['inquisition',20141118,'龙腾世纪：审判','Dragon Age: Inquisition','BioWare','角色扮演','fable','#77b58b',['奇幻','政治','伙伴关系'],['队伍构筑','战术暂停','对话选择'],
'当冒险者成为机构，拯救世界也意味着管理权力。',
'《审判》真正值得分析的，不只是它把地图做得比前作更大，而是它让玩家从游历者变成组织的中心。面对天际裂隙，你既要亲自战斗，又必须让相互猜疑的势力相信同一面旗帜。个人意志与机构惯性之间的距离，构成了它最有意思的角色扮演；庞大的地图则同时提供了舞台和负担。',
[
['一支队伍如何变成一种立场','BioWare 的长处仍然是让同行者带着自己的信仰进入旅程。法师、圣殿骑士、宗教与族群问题不只存在于背景设定中，也会进入伙伴对话，让看似务实的决定产生人际代价。玩家的身份因此由别人如何回应来确认。','这种结构使营地和据点成为叙事中枢。世界危机提供共同方向，私下谈话却不断揭示队伍并非一个声音。关系变化最有效的时候，并不是好感数字上涨，而是一个伙伴让玩家重新审视自己刚刚说出的政治判断。'],
['把微观战斗交给宏观构筑','即时行动与战术暂停并存，允许玩家在亲自操控和全队调度之间切换。职业定位、技能冷却、控制与防御资源决定队伍的稳定性；构筑的成效往往比连续精确输入更重要。它追求的是带领一群人解决问题的感觉。','代价是两套操作期待很难始终兼容。喜欢动作反馈的人可能嫌命中和移动不够利落，喜欢精密战术的人又可能觉得镜头与队友执行力不够可靠。系统有深度，但深度分布在准备和组合上，不能简单当作动作游戏衡量。'],
['壮丽的地图，分散的注意力','从荒野到沙漠，不同区域的尺度和光线让远征拥有地理差异。大空间使组织扩张变得可见，也让发现遗迹、营地和地方冲突具有合理容器。离开主线时，世界不会立刻失去可做的事情。','问题在于收集、清理和任务门槛有时把探索转化为清单管理。剧情正要求紧迫行动，地图却鼓励逐点完成琐事。较好的体验策略是按照兴趣离开区域，而非把最初的大地图清空；这是对其节奏弱点的补救，而非玩家的义务。'],
['组织幻想并不等于政治模拟','战争桌和据点建设让决策显得有重量：你的行动有情报、外交和后勤支持，不再像独行侠凭空改变整个大陆。这是把角色扮演扩展到组织层面的有效表现手段，也让权威本身成为主题。','但许多战略行动主要以文本和等待反馈，机构的长期运作并未发展成复杂模拟。需要区分表达与系统：游戏很擅长让你感到自己拥有影响力，却不是一套可以检验各种制度选择的政治沙盘。'],
['它继承了什么，又暴露了什么','《龙腾世纪：起源》的队伍传统在这里继续存在，但规模、跨平台制作与开放区域改变了叙事交付方式。《审判》代表大型角色扮演在那一时期追求内容广度的雄心，也提前显露了注意力被填充任务消耗的问题。','入选 2014 年 TGA 年度游戏，是这一作品历史位置的明确信号，却不意味着每个部分同样出色。它最不可替代的内容集中在人、信念和组织身份上；当这些主题被地图杂务打断，体量反而会削弱自己的优势。']
],
'值得收藏的是一群人如何围绕你的权力形成关系，而不只是庞大的待办地图。愿意主动管理支线节奏的玩家，更容易遇见 BioWare 最擅长的伙伴写作；期待紧凑战役或纯粹动作战斗的人，则需要接受它明显的折中。',
['PC Gamer · 2014 年评测','https://www.pcgamer.com/dragon-age-inquisition-review/','评测肯定庞大的战役与世界，同时指出持续存在的细部问题。'],
[['系列前作','龙腾世纪：起源','理解队伍战术与价值观冲突的直接起点。'],['后来对照','博德之门 3','同样强调伙伴，但用更开放的规则交互实现角色扮演。','bg3']]]);

accession(['overwatch',20160524,'守望先锋','Overwatch','Blizzard Entertainment','团队射击','gallery','#67b9de',['近未来','英雄','团队协作'],['角色分工','目标争夺','技能协同'],
'让枪法以外的能力，也能成为团队胜利的中心。',
'本展评述的是 2016 年初代《守望先锋》，以其六人团队、英雄切换和目标争夺为核心，而不是把续作的规则回填进历史。它的重要性在于重新分配了射击游戏中的参与方式：瞄准是贡献的一种，保护、治疗、封路和判断开团时机同样可以决定比赛。',
[
['英雄首先是一套动作承诺','轮廓、武器、音效与移动方式共同说明一个角色能做什么。重装者的体积、支援者的反馈、突击角色的节奏，使玩家在高速混战中仍有机会识别威胁。视觉个性不仅帮助传播，也服务于团队读图。','这套设计降低了进入射击游戏的单一门槛，却没有消除技巧。不同角色把要求放在追踪、预判、空间意识或资源管理上，允许玩家找到合适的入口，再逐渐理解整个队伍的运行。可亲近的外观与高强度协作在此并不矛盾。'],
['目标把六个人组织成临时共同体','占点和护送迫使队伍围绕空间与时间集结。一个人的击杀如果发生在错误位置，可能没有足够价值；一个及时的保护却能改变整轮进攻。胜负因此不仅由个人操作累加，也由贡献能否在同一时刻发生决定。','终极技能尤其强调这种时间协调。准备、诱骗和配合能够制造戏剧性逆转，但也可能让对局过分依赖某次组合释放。初学者眼里的热闹，需要通过理解冷却、站位与队伍状态，才能变成可以解释的战局。'],
['切换角色，就是在比赛中重新提问','初代允许玩家在对局中更换英雄，使失败不必只有“把枪打得更准”这一答案。对手占据高处、封锁入口或依赖某种阵形时，你可以调整职责，改变解决问题的方法。这是一种即时的团队构筑。','然而自由也带来社会摩擦。队伍可能缺少必要职责，玩家可能拒绝调整，而个人无法完全控制五名队友。其合作理想依赖陌生人沟通，最好的体验与最挫败的体验往往来自同一个结构。不能把社区问题简单归咎于输赢心态。'],
['世界观先于故事被记住','地图的小道具、角色语音和短篇动画共同营造一个已经发生许多故事的世界。它没有依赖传统单人战役建立第一印象，而是让人物的姿态和相互称呼承担了大量叙事工作。这种碎片式表达非常适合重复对局。','它也留下了期待与交付之间的距离：角色如此鲜明，玩家自然会想知道他们如何真正共同生活。多人竞技提供的是相遇的舞台，并非完整叙事的替代品。理解这一边界，才能同时看到美术传播的成功和故事体验的有限。'],
['一种成熟整合，而非凭空发明','它站在《军团要塞 2》等职业射击，以及技能导向竞技游戏的肩膀上。贡献不是第一个拥有职业或技能，而是把操作反馈、人物识别、地图目标与大众传播组织到高度一致的产品中。2016 年 TGA 奖项应放在这个整合能力上理解。','竞技服务持续变化，使这件展品还提出保存问题：初代规则、平衡和玩家文化并不等于今天同名品牌的全部内容。历史评论需要标明年代，否则后来调整会掩盖作品在上市时究竟解决了什么，也制造了什么。']
],
'初代《守望先锋》把团队射击中的英雄感分配给多种能力，这是它最值得留下的贡献。它适合愿意观察他人、调整职责的玩家；也应承认团队依赖和版本变化使其体验无法只靠个人努力保持稳定。本馆收藏的是这一具体设计阶段。',
['PC Gamer · 2016 年初代评测','https://www.pcgamer.com/overwatch-review/','以初代上市时的英雄、地图与团队体验作为评述参照。'],
[['设计先辈','军团要塞 2','职业轮廓、职责与目标模式提供重要类型背景。'],['射击对照','泰坦陨落 2','用移动和机甲转换塑造不同的个人能力曲线。','titanfall-2']]]);
games.find(g=>g.id==='overwatch').mode='多人竞技';

accession(['botw',20170303,'塞尔达传说：旷野之息','The Legend of Zelda: Breath of the Wild','Nintendo EPD','开放世界冒险','fable','#86b8a0',['自然','遗迹','探索'],['物理交互','自由攀爬','涌现解法'],
'当世界遵守可以学习的规则，远方就不再只是背景。',
'《旷野之息》把开放世界最重要的问题从“这里有多少任务”转向“我能如何抵达那里”。山坡、雨、火焰、金属和风都成为行动条件，玩家通过尝试建立对环境的理解。它的自由并非取消限制，而是让限制彼此作用，从而容纳设计师没有逐项指定的解法。',
[
['第一座高地就是一堂空间课','初始区域用寒冷、落差和分散目标教玩家观察。没有必要先记住大量图标：看见远处的塔或奇异地形，标记、移动、遇阻、改道，便构成一个完整循环。玩家的好奇心成为任务分配器。','攀爬和滑翔改变了地形的语法。山脉既是障碍，也是观察台和出发点；高度可以转换成移动距离。体力限制让路线仍然需要估算，因此自由不等于任意飞行，而是把规划嵌入持续行动。'],
['系统的价值，在于能相互解释','火可以影响环境，金属与雷电有关，物体可以被推动和利用。重要的并非单个互动有多复杂，而是规则在不同地点足够一致，使一次发现成为可迁移的知识。玩家因此敢于提出“也许这样可以”的假设。','这种一致性不是完美模拟现实。它选择性地抽取容易理解、容易组合的关系，再用视觉和声音说明结果。优秀之处在于让规则具有生产力：解决一场战斗的方法，也可能帮助跨越地形或完成谜题。'],
['武器会坏，节奏因此不断重置','耐久迫使玩家轮换装备、拾取敌人武器，避免过早找到一套永不变化的最优方案。战斗与探索的资源循环被紧密连接，场景中的爆炸物、高处和偷袭也因此更有吸引力。','但这一机制并非没有成本。珍贵装备可能因为舍不得使用而失去意义，反复整理背包也会打断流动。它维持了短期即兴，却削弱了一部分长期养成的依恋。评价它需要承认这种交换，而不是把所有不适都解释成玩家尚未理解。'],
['废墟让安静成为叙事','音乐经常让位于风、脚步与远处的声音，废弃设施和自然覆盖的建筑说明世界曾经经历什么。主要故事可以很稀疏，但旅行本身不断提供情绪：孤独、好奇、危险，以及突然出现的温暖。','与系列经典大型迷宫相比，神庙提供更短、更分散的谜题单元，强化探索节奏，也牺牲了某些长篇空间推理的满足感。敌人与部分奖励的重复，会在漫长游玩后减弱发现的新鲜度。系统开放并不能自动解决内容重复。'],
['回到传统，才有这次重写','它既回应初代《塞尔达》的自主探索，也继承三维系列建立的观察与交互传统。其行业影响主要表现为对开放世界导航、攀爬和系统组合的示范；不应把后来所有相似设计都直接归为它的发明。','2017 年 TGA 年度游戏肯定了这次重组的完成度。它真正难以替代的部分，是世界持续鼓励玩家形成自己的计划，并容许计划在途中变化。这种信任比地图尺寸更能解释它为什么成为讨论开放世界时的重要坐标。']
],
'这是一部把发现本身变成主要奖励的作品。愿意放下清单、尝试规则的玩家，会得到持续的自主感；需要密集剧情、复杂大迷宫或稳定装备成长的人，也可能感到失落。它的伟大在于清楚地选择了一种自由，并为此重写了整个世界。',
['GamesRadar+ · 2017 年评测','https://www.gamesradar.com/zelda-breath-of-the-wild-review/','评测高度肯定探索自由与系统设计，本文另讨论耐久、内容重复及迷宫结构的代价。'],
[['系列根基','塞尔达传说：时之笛','观察、锁定和三维空间语言的重要先辈。','ocarina'],['系统对照','艾尔登法环','同样用远景牵引探索，却以战斗风险组织世界。','elden-ring']]]);

accession(['god-of-war',20180420,'战神','God of War','Santa Monica Studio','动作冒险','fable','#789cae',['北欧神话','父子','成长'],['近身战斗','同伴协作','连续镜头'],
'让一个以愤怒闻名的人，重新学习如何与别人同行。',
'2018 年的《战神》并未抹去系列的暴力，而是改变了暴力发生的距离。镜头靠近奎托斯，斧头具有回收的重量，儿子则在战斗和旅途中持续回应他。重启因此不仅是换一套神话背景，更是把旧角色的力量放进一种需要克制、解释和照顾的关系。',
[
['近距离镜头改变了动作的标点','利维坦之斧的投掷与召回形成清晰节奏：离手时失去一部分近战能力，返回时又把声音、震动和动作汇聚成一次反馈。它既是武器，也是解谜和空间控制的工具，使战斗与环境交互拥有共同语言。','贴近肩后的视角增强身体感，也限制周边信息。方向提示和敌人音效帮助补偿，但大群战斗仍可能产生视野压力。它舍弃旧作较远镜头下的全局可读性，换取更亲密的力度；这一取舍决定了新作的动作性格。'],
['同伴不是等候过场的乘客','阿特柔斯的箭矢、提示与战斗参与，让父子关系进入玩家的操作循环。你会依赖他的帮助，也会听见他如何理解刚发生的事。亲密感来自许多小规模协作，而不只是剧本宣布两人关系改变。','这种伙伴设计受到明确控制，避免照看任务频繁打断战斗。好处是同行顺畅，代价是关系中的风险多由叙事安排承担。它并未模拟一个真正不可预测的孩子，而是精心选择哪些不确定性适合进入动作冒险。'],
['一段旅程，逐渐成为可以重读的地图','湖泊与周围区域为线性目标提供可回访的中心。新能力和水位变化让熟悉地点显露新的路径，支线则把神话从背景名词变成具体人物处境。旅程因此有推进，也有停留和回看。','装备等级、资源与技能拓展了构筑，但数字管理有时显得比动作本身更繁琐。反复出现的敌人类型与部分首领变体，也暴露了内容覆盖的有限。支线最好的价值在于补充关系和世界，而不是给每一场战斗更高数值。'],
['连续镜头是关系的形式','尽量保持连续的摄影把玩家锁在同一段同行经历里，减少传统剪辑带来的抽离。角色的停顿、转身与沉默因而更容易被观察，宏大神话的规模也被压回父子之间的距离。形式选择与主题相互支持。','不过无缝感并非完全没有接缝：狭窄通道、攀爬和移动对话承担了节奏与技术调度。它是一种高度制作化的连续体验，不应误解为玩家拥有未经安排的叙事自由。导演的控制始终很强，只是更少露出边框。'],
['重启的意义，是让过去继续产生后果','旧系列的历史赋予奎托斯的克制更多重量，新玩家则可以从父子冲突直接进入。游戏不要求所有人掌握相同背景，却让老角色的记忆成为新主题的资源。这是成熟系列转型时难得的平衡。','2018 年 TGA 年度游戏属于这一具体作品，不是《诸神黄昏》，也不是《荒野大镖客 2》。它的行业位置在于证明高预算动作系列能够围绕人物关系重构镜头、战斗和节奏，而不必彻底放弃原有的身体力量。']
],
'《战神》最出色的不是“动作加剧情”的简单组合，而是让武器手感、镜头距离和伙伴协作共同讲述克制。它的数值负担与敌人重复值得批评，但作为系列转型，它给出了主题如何真正进入制作决策的完整范例。',
['GamesRadar+ · 2018 年首发评测','https://www.gamesradar.com/god-of-war-review/','以 PS4 原作的叙事、动作和探索作为参照；本馆配图若来自 PC 移植会单独注明。'],
[['系列后续','战神：诸神黄昏','延续父子关系并扩展群像与战斗组合。'],['同伴叙事对照','最后生还者 第二部','同样让身体暴力承担人物表达，但采用不同的视角结构。','tlou2']]]);

accession(['sekiro',20190322,'只狼：影逝二度','Sekiro: Shadows Die Twice','FromSoftware','动作冒险','ink','#bb9272',['战国幻想','忠诚','武士'],['架势攻防','弹刀','潜行'],
'真正的成长，不在等级表里，而在你终于听懂刀锋的时候。',
'《只狼》把 FromSoftware 作品中的一部分选择收拢到一把刀上。少了丰富职业和多人助战，战斗却获得了更明确的语法：攻击、弹开、识破和跳跃不是各自独立的按钮，而是一场持续争夺主动权的对话。它因此既可能是一次极其纯粹的学习，也可能成为一道难以绕开的门槛。',
[
['生命值之外，还有一种胜利条件','架势让有效防御本身能够推动战斗。面对连续攻击，玩家不必总是撤退等待空隙，而可以用准确弹刀维持压力；对手的生命状态又影响架势恢复，进攻与防御因此互相解释。','这一结构改变了对危险的直觉。过度后退可能让已经建立的优势消失，主动靠近反而更稳定。最精彩的战斗并不是无伤炫技，而是玩家逐渐看懂对方节奏，从被动存活转向有意识地控制交锋。'],
['困难来自必须掌握的共同语言','危字攻击要求辨别招式而非只看一个警告：下段、突刺等不同威胁需要不同回应。系统以强烈后果训练观察，让成功显得具体可解释。忍具与道具有帮助，但通常不能完全替代基本功。','这也意味着容错路线比许多角色扮演作品更窄。卡在关键首领时，玩家无法同样自由地更换整个职业或依靠联机解决。将这种压力赞美为“公平”还不够；它确实排除了一部分身体条件、节奏偏好和学习时间不同的玩家。'],
['忍者的身体，让关卡向上展开','钩绳、屋顶和潜行提供与正面决斗不同的节奏。你可以先观察敌群，用暗杀削减风险，再决定何时进入公开战斗。纵向移动让传统危险路线多了一层空间判断，也让据点具有侦察价值。','潜行的精密程度并非专业潜入模拟的水平，敌人警戒有时容易被利用。它的主要职责是调节遭遇密度、支持忍者身份，而不是建立一套同等复杂的替代通关系统。把它当作战斗前的准备，会比期待完全隐身路线更合适。'],
['复生把失败变成一次局部判断','倒下后是否复起，会影响一场尚未结束的战斗。它减少了某些失败的立刻终止感，又用资源和限制防止无限续命。死亡不再只是关卡外的重试，也可能成为战场内部的一次决策。','与此同时，检查点、回程和重复遭遇仍然要求耐心。成功的高峰建立在不断练习之上，叙事节奏会因此受到个人技术影响。这不是自动成立的优点，而是一种将戏剧性部分交给玩家学习曲线的创作方式。'],
['从魂系传统中分离出自己的形状','篝火式休整、强敌与路线记忆仍能看见系列家族相似性，但《只狼》的架势和固定主角使其不能简单等同于换皮《黑暗之魂》。它把角色扮演的多样性换成动作体系的一致性。','战国幻想的破败、怪诞与忠诚主题，为这种执着提供了语境。2019 年 TGA 年度游戏认可的是一套高度聚焦的作品；其影响也应理解为动作设计的鲜明示范，而不是证明所有游戏都应该采用同样严格的挑战。']
],
'《只狼》用极少数核心动作创造了丰富的交锋，是本馆对“深度不等于选项数量”的重要例证。它要求玩家接受反复学习，也保留明显的进入门槛；一旦读懂架势，战斗就会从等待机会变成自己制造机会。',
['PC Gamer · 2019 年评测','https://www.pcgamer.com/sekiro-review/','评测讨论其高强度挑战与战斗体系；本文将角色构筑收缩视为明确取舍。'],
[['设计血缘','黑暗之魂','共享危险空间与失败学习，却采用不同的防御逻辑。','dark-souls'],['动作对照','师父','同样以短促、可练习的近身动作建立成长。','sifu']]]);

;

/* late-awards.js */
accession(['tlou2',20200619,'最后生还者 第二部','The Last of Us Part II','Naughty Dog','动作冒险','horror','#87a7a0',['末世','创伤','人性'],['潜行战斗','环境叙事','多重视角'],
'当动作足够令人投入，叙事还能否让你怀疑自己的投入？',
'《最后生还者 第二部》把制作精度与道德不适放在同一套体验里。它的潜行战斗比前作更灵活，人物演出和环境细节极为细密，却不愿把顺畅的行动简单包装成正当的胜利。作品最值得讨论的，是它如何利用参与感制造冲突，以及这种强烈作者意图会在何处过度施压。',
[
['身体在环境里寻找缝隙','俯卧、闪避、跳跃与更复杂的遭遇空间，使角色可以在草丛、室内和高低差之间转换。战斗经常从隐蔽开始，在失误后变成短促冲突，又在转移位置后重新获得控制。潜行和公开交火因此不是截然分开的两种模式。','资源限制让每次开枪、制作和靠近都带有机会成本。敌人的搜索与相互呼应增强了被追踪的感觉，但这仍是为戏剧节奏设计的系统，并非无限聪明的对手。理解它的可读线索，才能在紧张中做出有根据的判断。'],
['细节不是装饰，而是世界的证词','被遗弃的店铺、住宅与公共设施让灾难显得有具体历史。搜集物资的路线也常是阅读路线：你因生存需要进入一个房间，却发现那里曾经属于某个人。环境叙事由此与核心循环交织。','细密制作也会带来惯性。抽屉搜寻、狭缝穿行和反复进入废弃空间，在漫长流程后可能变成可预期的动作。写实反馈能增强存在感，却不能自动抵消重复；作品的体量使其节奏问题更容易被放大。'],
['视角结构主动抵抗简单归队','本馆不展开关键情节，但必须指出：游戏通过调整观察位置，让玩家面对自己先前判断的局限。它不是一个任意选择立场的沙盒，而是一部要求你陪伴不同处境的作者作品。其伦理力量来自被迫看见，而非自由选择。','这种方法也有争议。玩家可能认为理解已经形成，剧本却仍在反复强调同一主题；或者觉得行动被安排后，责任又被交回给自己。强烈情绪不等于论证自然成立，批评它的操控感并不必然意味着拒绝复杂人物。'],
['表现力的进步也包括进入方式','面部、呼吸、运动和声音把情绪放进细小的身体变化里。与此同时，大量可调整的辅助选项使不同需要的玩家有机会接近这套体验。对行业而言，制作野心不只体现在看得见的画面，也体现在谁能够实际参与。','难度与辅助并非取消作品表达。它们允许玩家调节操作负担，而主要情境仍然保留。这提醒我们，不应把高压叙事与唯一的操作门槛捆绑；同一部作品可以保持作者性，同时为进入方式提供更多空间。'],
['它的历史位置应容纳分歧','前作建立的角色关系是理解续作的重要基础，续作则冒险改变观众对延续故事的期待。2020 年 TGA 年度游戏反映其获得的行业认可，但奖项不能消除玩家对结构、长度与人物处理的不同判断。','它的不可替代性在于，极高完成度的商业动作冒险被用于制造难以轻松消费的情绪。它未必在每个时刻都做到克制，却使关于参与、同情与暴力表现的讨论难以绕开具体游玩过程。']
],
'这是一部值得认真讨论、也允许严厉批评的作品。潜行空间、演出与辅助设计有明确成就，篇幅和主题重复则会影响接受程度。建议在了解前作后进入，并把不适作为分析的起点，而不是把赞同或反对当作唯一正确的观展方式。',
['GamesRadar+ · 2020 年评测','https://www.gamesradar.com/last-of-us-part-2-review/','评测肯定环境与战斗，也讨论写作过度和主题重复的问题。'],
[['直接前作','最后生还者','续作的人物关系与情绪前提。'],['西部对照','荒野大镖客 2','同样通过漫长陪伴讨论暴力生活的代价。','rdr2']]]);

accession(['elden-ring',20220225,'艾尔登法环','Elden Ring','FromSoftware','动作角色扮演','fable','#9ba586',['黑暗奇幻','神话','废墟'],['开放世界','构筑自由','高难度战斗'],
'在一条难走的路之外，始终还能看见另一条路。',
'《艾尔登法环》把魂系作品的危险与不确定性放进广阔地理中。失败不再总意味着沿同一路线立即重试：玩家可以绕行、探索、改变构筑，再带着新知识回来。开放世界由此不只是放大关卡，而是重新安排了挑战、逃离与成长之间的关系。',
[
['远景是一种邀请，也可能是一种误判','城堡、黄金树和破碎地形构成强烈方向感。游戏不会总先告诉你某处是否适合当前能力，玩家需要通过实际遭遇判断风险。地图的吸引力来自可见目标与未知危险同时存在，而非只靠任务标记承诺奖励。','坐骑和较自由的移动降低了大地图试探成本，使探索能够在高压战斗之外呼吸。进入大型传统迷宫后，路线收紧、捷径和敌人布局又重新强调细读空间。广阔与紧密交替，是它比单纯面积更重要的结构优势。'],
['构筑提供多种面对困难的身体','武器、战技、法术与召唤让玩家改变战斗距离和节奏。一个难以近身的敌人，可能在另一套配置下呈现不同问题。角色成长不仅是数值变大，也包括找到适合自己理解方式的工具。','这种丰富并不等于所有选项同样清楚或平衡。装备说明、属性需求和隐藏交互需要投入研究，部分强势方案也可能压缩尝试空间。自由越多，解释责任越大；新玩家有时需要外部资料，才能意识到自己实际上拥有其他办法。'],
['战斗读招与角色表演之间的张力','敌人的延迟、连段和范围攻击不断挑战玩家对安全窗口的判断。成功要求观察、距离管理和资源分配，而不只是迅速按键。优秀首领使学习过程具有清晰阶段，让失败能够转化成下一次行动的知识。','然而后段一些高强度连段、伤害压力与重复敌人，会让耐心被消耗而非增长。开放世界减轻了早期堵点，却无法保证每场最终挑战都同样优雅。把所有挫折解释为应得的训练，会掩盖遭遇设计本身的质量差异。'],
['故事藏在遗迹的相互关系里','碎片文本、人物处境与建筑分布共同构成历史感。玩家不是按完整年代顺序接受故事，而是从残余推断曾经的秩序。这种叙事让探索与解释结合，也允许不同理解暂时共存。','它同样会造成角色任务难以追踪、重要事件容易错过的问题。模糊可以激发讨论，也可能只是让人失去线索。评价时应区分富有意义的留白与交互信息不足；两者不能因为同样神秘就被一并赞美。'],
['把魂系传统转化为更宽的旅程','《黑暗之魂》的路线记忆、危险管理与碎片叙事，在这里被置于更多出口之中。它没有抛弃压力，而是允许玩家自行调节何时面对压力。与《旷野之息》相比，探索的主要回报更紧密地连接战斗能力与世界秘密。','2022 年 TGA 年度游戏说明这一扩展获得广泛认可，但其价值不在于证明开放世界优于线性关卡。相反，游戏最有力的时刻往往来自二者交替：远行积累期待，精密迷宫兑现期待。']
],
'《艾尔登法环》最珍贵的自由，是允许暂时承认自己还没有准备好。它以庞大的构筑和空间选择容纳不同成长路线，也留下重复、信息晦涩和后期压力不均的问题。愿意观察和改道的人，会得到一段极具个人形状的旅程。',
['PC Gamer · 2022 年评测','https://www.pcgamer.com/elden-ring-review/','以原作的开放世界与魂系结构为参照，不将后续扩展内容计入首发评述。'],
[['设计根基','黑暗之魂','危险、捷径和失败学习的直接家族传统。','dark-souls'],['开放世界对照','旷野之息','以规则组合和地形自由组织另一种探索。','botw']]]);

accession(['bg3',20230803,'博德之门 3','Baldur’s Gate 3','Larian Studios','角色扮演','fable','#b69dba',['奇幻','伙伴关系','道德选择'],['回合制战术','规则交互','分支叙事'],
'当规则愿意认真回应你的奇思妙想，角色扮演才真正发生。',
'《博德之门 3》的雄心不是提供最长的对话树，而是让对话、地形、道具、职业与失败共同改变旅程。它把桌面角色扮演中“能不能试试这样”的提问，翻译成可被计算机执行的交互。系统当然有边界，但它频繁承认玩家的计划，因而让角色不只是剧本中的称呼。',
[
['一场战斗可以从战斗之外开始','高差、视线、潜行、可移动物体和法术作用，使开战前的准备具有意义。队伍站在哪里、谁先进入谈话、环境中有什么，都可能改变随后局势。胜利因此不只发生在技能栏里，也发生在对场景的理解中。','回合制为复杂选择提供思考时间，但同样增加了学习负担。动作资源、豁免、专注和职业细节需要逐步消化。游戏的开放性建立在规则知识上；新手若只看伤害数字，容易错过控制、辅助和位置带来的价值。'],
['骰子让不完美也成为旅程的一部分','检定使角色能力在谈判、探索与危险处理中可见。一次失败可能打开不同处境，而非立即宣布游玩无效。它鼓励玩家接受人物的局限，让故事与“我想扮演谁”之间形成真实摩擦。','但不是所有失败都同样有趣，读档也始终是玩家可选择的方式。不能把接受骰子当作道德要求。更值得赞赏的是作品为许多不理想结果准备了回应，使玩家有理由继续，而不仅是因规则规定必须继续。'],
['伙伴既是队伍资源，也是独立的人','同伴带着私事、欲望与风险参与主线，他们会评价玩家，也需要玩家判断是否信任。战斗编成与情感关系因此相互影响：你可能因为喜欢一个人而调整队伍，也可能因共同经历重新理解其立场。','大量表演与分支让人物反应显得具体，但触发顺序、营地事件和任务状态仍可能暴露系统接缝。如此密集的回应不可能处处平滑，尤其当玩家以非常规顺序推进时。规模令人惊叹，技术与逻辑成本也真实存在。'],
['自由来自精密生产，而非无限生成','玩家感觉世界愿意配合，背后是规则系统与大量手工内容互相支撑。系统负责让物体和能力可组合，写作与演出负责让结果有人情味。只有规则会显得冷，只有分支则难以容纳即兴；两者结合才形成其说服力。','这种制作方式不应被轻率推广为所有工作室都必须达到的基准。题材积累、团队经验、开发周期和抢先体验反馈共同构成条件。行业意义在于展示一种成功的生产组合，而不是证明内容越多、选择越多就必然更好。'],
['它既继承经典，也继承拉瑞安自己','《龙与地下城》的规则传统提供基础，早期《博德之门》提供系列身份，《神界：原罪》则是理解拉瑞安环境交互与合作经验的重要路径。把成功完全归于怀旧，会忽略这些不同来源如何被重新组织。','2023 年 TGA 年度游戏是明确的奖项依据。其不可替代性在于，让高密度作者内容与玩家的非常规计划频繁相遇。后段节奏、管理负担和状态复杂性值得批评，却不削弱这种“你的办法也算数”的核心成就。']
],
'这是一部把角色扮演落实到规则反馈中的作品，适合愿意学习、试验和接受意外的人。它的丰盛需要时间，也会带来管理与节奏负担；最好的进入方式是先形成自己的角色和兴趣，再决定哪些可能性值得追随。',
['PC Gamer · 2023 年评测','https://www.pcgamer.com/baldurs-gate-3-review/','评测高度评价系统自由与角色扮演空间，本文同时讨论复杂度与内容生产成本。'],
[['开发传统','神界：原罪 2','环境交互、回合战术与合作设计的直接前史。'],['队伍叙事对照','龙腾世纪：审判','同样强调伙伴，却采用不同的战斗与组织结构。','inquisition']]]);
games.find(g=>g.id==='bg3').mode='单人 / 合作';

accession(['expedition-33',20250424,'光与影：33 号远征队','Clair Obscur: Expedition 33','Sandfall Interactive','角色扮演','fable','#ab8b93',['奇幻','哀伤','艺术'],['回合制战斗','即时闪避','队伍构筑'],
'在回合之间加入一次心跳，也让美丽承担失去的重量。',
'《光与影：33 号远征队》以鲜明的美术和死亡倒计时建立入口，却需要通过战斗与人物证明自己不只拥有一个好概念。它把回合选择与实时回应结合，让计划和身体反应彼此打断；这种混合带来强烈参与感，也构成媒体评价分歧的重要原因。',
[
['世界观首先改变了人如何生活','周期性的消逝威胁不是单纯终极反派的借口，而是影响城市仪式、出发和告别的共同前提。远征因此同时带着公共使命与私人失去，角色的希望从一开始就不是轻松的胜利想象。','绘画感的场景、时代风格混合与音乐建立了近乎舞台化的情绪。它们的价值在于使世界拥有可辨认的审美，而不只是把画面推向写实极限。不过视觉隐喻本身不能代替人物发展，情绪最终仍要由具体行动承担。'],
['敌方回合不再是等待时间','闪避、招架和跳跃要求玩家在对手行动时继续观察。回合制的资源安排与动作节奏由此叠加：前者决定战略，后者影响一次计划能否顺利兑现。战斗不再只有选择菜单的一种参与方式。','代价是两类期待可能冲突。想慢慢思考的人仍需面对即时反应，喜欢纯动作的人又受到回合流程约束；读招失败也可能压过先前的策略准备。这不是谁理解错误，而是混合系统天然需要支付的兼容成本。'],
['不同角色需要不同的思考方式','队伍成员并非仅仅换一种元素攻击，而以各自资源与状态机制组织行动。装备、技能和被动效果让玩家尝试组合，找到能互相支持的输出与生存路径。角色个性由此部分进入战斗规则，而非只存在于对话。','随着选项增长，强势组合与伤害优化可能让部分遭遇失去原先紧张。另一方面，不愿深入构筑的人又可能把困难全部归于反应速度。较好的评论必须同时观察系统和输入，不能只用“像传统日式角色扮演”概括整套战斗。'],
['线性方向与探索欲之间的尺度','区域探索、支路与世界移动提供了主线之外的发现，同时保持相对明确的叙事方向。它没有追求无限展开的开放世界，而是让审美与事件密度维持在较集中范围内。规模选择本身也是制作判断。','一些空间的可读性和移动反馈，未必与其视觉表现同样成熟。景观很美不等于路线总是清楚，镜头和地形边界也可能打断投入。中等规模作品的鲜明创作意志值得肯定，具体交互上的粗糙则仍应被指出。'],
['奖项之外，保留真实的意见分歧','它获得 2025 年 TGA 年度游戏，因此进入本馆的年度序列。长期行业影响仍需要时间观察，不能因新近获奖就直接授予历史里程碑或 Ocean 荣誉。现在能够判断的，是它已呈现的结构、表达与完成度。','专业媒体也没有给出完全一致的答案：RPG Site 的评价积极，PC Gamer 则对实时动作融入回合战斗的效果更保留。这种分歧很有价值，提醒我们同一机制可能被体验为更投入，也可能被体验为额外干扰。']
],
'这件展品代表一种鲜明、愿意冒险的现代角色扮演。美术、音乐和人物情境提供强烈入口，混合战斗则决定你是否愿意长期停留。它值得完整体验与讨论，但获奖不会替它免除节奏、读招和空间交互方面的批评。',
['PC Gamer · 2025 年评测','https://www.pcgamer.com/games/rpg/clair-obscur-expedition-33-review/','该评测对实时战斗成分持保留意见；可与下列 RPG Site 评测对照阅读。'],
[['类型对照','博德之门 3','同为队伍角色扮演，但更强调规则交互与分支。','bg3'],['动作对照','只狼：影逝二度','都重视读招与招架，整体战斗结构却截然不同。','sekiro']]]);
games.find(g=>g.id==='expedition-33').sources.push(['RPG Site · 2025 年评测','https://www.rpgsite.net/review/17273-clair-obscur-expedition-33-review']);

;

/* history.js */
accession(['pacman',19800522,'吃豆人','Pac-Man','Namco','街机动作','terminal','#7bbac2',['迷宫','追逐','街机文化'],['路线规划','风险奖励','高分挑战'],
'只用一张迷宫，把逃跑、贪心与反击变成共同语言。',
'《吃豆人》的直观常被误认为简单。屏幕没有复杂镜头，没有长篇说明，却同时呈现目标、危险、资源与退路。玩家几秒内就能开始，随后却会不断发现路线选择的代价。它的历史贡献不只是一个黄色角色广为人知，更是让空间判断与鲜明个性在极少信息中同时成立。',
[
['所有信息都在眼前，压力仍然成立','豆子标记尚未完成的区域，幽灵的位置说明风险，通道连接决定可选择的路线。玩家不用寻找任务目标，却始终需要判断先清哪一段、何时穿越中央、是否值得回头。信息公开不等于决策容易。','迷宫把局部安全与全局效率分开：眼下能躲开的方向，可能把最后几颗豆子留在最危险位置。随着空白区域扩大，地图本身记录了你的行动历史。一次局面的形成可以追溯到此前的选择，因此失败具有可复盘性。'],
['大力丸让猎物暂时改写规则','力量翻转把追逐关系突然倒置。玩家不只获得喘息，还被高分奖励诱惑去追逐敌人。有限时间使反击必须计算路径，贪心则可能把角色带到效果结束后的不利位置。一个道具同时承担节奏、风险与情绪变化。','这种设计比单纯无敌更有表现力：危险没有被永久清除，而是被暂时转化为机会。玩家会在逃跑时计划反击，在反击时担心恢复常态。可辨认的声音与颜色帮助传达变化，使复杂的心理无需文本解释。'],
['对手的个性首先体现为行为','不同幽灵共同形成包围压力，玩家逐渐学会观察其移动，而不只是把它们看作随机障碍。有限行为规则经过组合，可以呈现像是有意图的追逐；这说明角色性不必先由背景故事建立。','但它也保留早期街机的严厉：速度提高、重复地图与记忆路线会逐渐占据体验。高手对规律的掌握可能把即兴压缩成执行。原作不是无限变化的系统，其持久深度来自有限棋盘上的精炼，而不是内容不断生成。'],
['从游戏角色到大众文化形象','黄色轮廓、进食动作和有趣的幽灵，让游戏在离开机台后仍能被识别。The Strong 将其列为 2015 年世界电子游戏名人堂首批成员，并讨论它跨越玩具、音乐和电视的传播。历史标签在这里有明确的文化证据。','这不意味着它独自发明了角色商业化，或直接改变了全部人类历史。更准确的判断是：它成为电子游戏进入大众日常文化的重要早期范例，也展示了抽象规则如何通过角色形象被更广泛的人群记住。'],
['版本差异也是这件展品的一部分','街机原作、家用移植和后来的变体不应混为一谈。画面布局、操作与行为差异会实质改变节奏，某个移植的缺点不能直接用于评价原作。后续《Ms. Pac-Man》等作品则通过变化迷宫继续讨论重复与新鲜感。','今天重看它，最值得学习的是信息组织：目标清楚、风险可见、反馈立即，而一次翻转就足以制造故事。现代作品可以从中借鉴表达效率，却不必复刻投币时代的所有惩罚。历史收藏不是要求设计永远停留在过去。']
],
'《吃豆人》以极低的理解门槛提供持续的空间决策，是游戏规则与流行角色相互成就的典型。原作的重复和速度压力限制了部分人的长期兴趣，但其可读性、风险翻转和文化传播，足以构成具体而可靠的入馆理由。',
['HonestGamers · 街机版回顾评测','https://www.honestgamers.com/2368/arcade/pacman/review.html','作为街机版玩法回顾；文化地位另参见 The Strong 名人堂档案。'],
[['时代对照','太空侵略者','同样以有限画面和明确目标组织持续压力。','space-invaders'],['角色传统','超级马力欧兄弟','继续将鲜明角色与可学习的规则结合。','mario']]]);

accession(['civilization',19910901,'文明','Sid Meier’s Civilization','MicroProse','策略模拟','gallery','#9facb4',['历史','社会','帝国'],['回合制策略','科技树','城市经营'],
'“再来一回合”的背后，是把漫长历史变成相互牵连的选择。',
'1991 年的《文明》把探索、城市、科技、战争和制度装进一张可操作的地图。它不是准确模拟人类历史的机器，而是一套关于发展与竞争的规则模型。它最有力量的地方，是让眼前的小决定在许多回合之后显露后果；最需要警惕的地方，则是模型的简化容易被误认为历史本身。',
[
['城市把不同时间尺度连接起来','定居位置决定资源与扩张条件，生产选择影响近期安全，也影响长期能力。造一个单位还是一项设施，并不存在脱离局势的唯一答案：当前风险、邻近势力和未来目标会改变同一个选项的价值。','回合结构让玩家有时间检查这些关联。短期完成一个项目，中期争取一种技术，长期实现胜利，多个目标错开结束，持续制造下一次行动的理由。“再来一回合”由结构产生，不只是奖励频繁出现。'],
['科技树让未来成为可以计划的路线','研究把历史知识转化为依赖关系，允许玩家选择自己优先追求的能力。它给予长线规划可见形状，也使军事、经济和探索不再完全分离：一个方向的投入可能改变另一个方向的选择。','但树状进步很容易暗示所有社会都应沿同一条路径前进。真实历史充满交换、断裂与多种价值，不能被简单排列成落后到先进。游戏的教学价值在于激发提问和系统思考，而非替代历史学习。'],
['地图不只是领土，也是一组关系','探索揭示资源、邻居和通道，外交与战争让地理具有政治含义。信息不完整时做出的扩张决定，会在后来遇见他者时被重新评价。世界从空白变为相互制约的局势，是每局最有吸引力的成长过程。','与此同时，胜利导向与扩张机制容易把其他社会压缩为竞争对象，把发展理解为持续增长。这样的价值预设需要被指出。专业评论不应因为题材涉及文明就自动称其深刻，而应检查哪些历史关系被规则保留，哪些被排除。'],
['界面承担了一种新的叙事职责','数字、地图和顾问信息不以电影方式讲故事，却让玩家记得某次危机、一次晚到的科技或一个关键城市。叙事来自系统后果被人解释，角色往往不是预写人物，而是你长期投入的共同体。','原作的信息呈现、重复管理与后期操作负担，以今天标准看并不轻松。地图扩大后，许多决策会变成例行检查。后来的系列作品不断调整这一问题，说明核心循环成功，并不代表所有管理成本都同样值得保留。'],
['一项整合成就，而非孤立起源','它与桌面策略、早期电脑战略和城市模拟拥有清晰的时代联系。The Strong 的名人堂档案将它放在这些传统中理解；PC Gamer 对开发者的回顾也说明，回合制形态来自具体设计选择，而非一开始就注定。','本馆赋予历史标签，是因为它成为电脑大型回合策略的重要坐标，并长期示范如何把许多相互依赖的子系统组织为一局旅程。不是因为它客观证明某种文明优于另一种，更不是把游戏中的胜利公式当作社会发展的答案。']
],
'《文明》值得收藏的，是它让宏观过程变成可参与、可反思的决策网络。原作的界面与管理负担需要历史视角，历史观的简化也应被批判。带着这些边界再玩，才会看见策略游戏如何既激发想象，也暴露自身模型的偏向。',
['PC Gamer · 系列起源与开发者回顾','https://www.pcgamer.com/games/strategy/civilization-is-the-most-iconic-turn-based-series-of-all-time-but-sid-meier-considered-making-it-an-rts-it-could-have-easily-gone-in-different-directions/','这是一篇开发历史回顾，不冒充 1991 年首发评测；正文为本馆独立机制评论。'],
[['设计背景','Empire 与模拟城市','早期战略与城市模拟提供理解其系统整合的背景。'],['开放创造对照','我的世界','同样生成个人叙事，但减少统一胜利目标的约束。','minecraft']]]);
games.find(g=>g.id==='civilization').edition='1991 年 DOS 原作；早期发行仅以年份展示';

accession(['half-life-2',20041116,'半衰期 2','Half-Life 2','Valve','第一人称射击','terminal','#8eacb6',['科幻','反乌托邦','反抗'],['物理交互','连续叙事','场景节奏'],
'当一张桌子既能挡路，也能救命，世界就不再只是布景。',
'《半衰期 2》把物理从视觉效果提升为一种持续参与的语言。玩家仍在一条高度导演化的路线中前进，却能够搬动物件、改变局部条件，并在战斗中利用环境。它的成就不是突然给予无限自由，而是在可控流程中频繁证明：眼前的世界会对你的动作作出有意义的回应。',
[
['物理需要被关卡使用，才成为设计','重量、浮力和碰撞不只是演示技术的借口。关卡把物体位置与通路、障碍和安全联系起来，让玩家逐渐学习哪些关系值得尝试。规则通过操作被理解，而不是一次性写在帮助菜单中。','重力枪把这种学习扩展到战斗：场景物件可以成为工具、掩护或攻击材料。玩家会以新的眼光看待普通杂物，因为它们不再只有装饰身份。技术、关卡与武器因此指向同一个体验目标。'],
['第一人称也能容纳精密演出','角色在玩家所在空间里行动和说话，面部与身体表演提供细致信息。镜头大多留在主角视点，使叙事保持同行感；你不是切出去观看电影，而是站在一个正在发生的场景中。','然而观看自由并不等于剧情自由。某些段落仍需要等待人物完成安排，玩家的沉默也让关系呈现出特殊距离。它展示的是如何隐藏和柔化导演控制，而非真正取消控制。理解这一点，才能准确评价其沉浸。'],
['不断换节奏，却保持旅程连续','步行、载具、恐怖氛围和城市战斗交替，使一个核心操作体系承担不同强度。空间尺度与敌人组织不断变化，防止射击只剩重复清场。优秀段落往往先建立一种期待，再用新的环境关系改变它。','部分载具行程和物理谜题也可能在今日显得拖长。技术新鲜感会随时代下降，节奏就必须独自接受检验。承认这一点并非否定当年的突破，而是区分首次惊奇与长期仍然成立的设计品质。'],
['它还处在电脑游戏生产方式的转折处','Source 技术与围绕 Valve 游戏形成的创作生态，让本作的意义超出单次战役。Steam 与原作的发行关系，则提示软件获取、更新与长期访问逐渐进入游戏体验本身。这里的历史贡献属于作品与平台共同构成的时代背景。','不能把此后全部数字发行或模组文化归功于一款游戏，它们都有更早先例。更审慎的判断是，《半衰期 2》成为这些变化被大量玩家具体感知的重要节点，同时也留下对平台依赖与作品保存的长期问题。'],
['继承初代，再把世界交回给手','初代《半衰期》已发展连续第一人称叙事，续作在物理、角色演出和场景规模上继续推进。同属 Valve 的《传送门》则以更聚焦的规则谜题展示另一种可能，二者的共同点是把技术能力转化为可学习的交互。','本馆历史标签着眼于这种方法：游戏不是把故事、技术与玩法分别做强就能自动成立，而要让它们彼此需要。《半衰期 2》有明显年代感，却仍是观察这种整合如何工作的清晰样本。']
],
'这件展品最值得重新体验的，是物理如何进入关卡节奏，而不是孤立欣赏一个曾经先进的引擎。它的线性控制与部分拖长段落并未消失，但当环境从布景变成工具，第一人称冒险的表达空间确实被拓宽了。',
['PC Gamer · 2004 年评测重刊','https://www.pcgamer.com/games/fps/half-life-2-review-uk/','原评测强调物理成为核心玩法；重刊日期不作为游戏首发时间。'],
[['直接先辈','半衰期','连续第一人称叙事与场景调度的基础。'],['同一创作生态','传送门','把一组空间规则集中转化为教学与叙事。','portal']]]);

accession(['dark-souls',20110922,'黑暗之魂','Dark Souls','FromSoftware','动作角色扮演','horror','#9da197',['黑暗奇幻','衰败','孤独'],['互联关卡','耐力管理','失败学习'],
'一扇从里面打开的门，可以比一段胜利动画更令人难忘。',
'《黑暗之魂》并不只靠高难度获得身份。它把空间、资源、死亡和叙事绑在一起：你为什么害怕走远，为什么记住一个拐角，为什么发现捷径时突然安心，都来自同一套结构。理解它，应从这种相互依赖出发，而不是只计算首领需要失败多少次。',
[
['地图在记忆中逐渐折叠','前半段许多区域互相连接，电梯、门和绕路让原本遥远的地点突然靠近。地图不只是用来走过的容器，也是需要理解的对象。捷径改变了资源消耗和心理距离，因此发现本身具有实际力量。','这种结构依赖玩家记忆方向、敌人和休息点。缺少明确导航让空间更重要，也让迷失更可能发生。它的探索满足感并非无成本：对方向感、耐心和连续游玩时间的要求，都应被纳入评价。'],
['耐力把每个动作变成承诺','攻击、防御和翻滚共享压力，贸然连击会让下一次应对变得困难。武器距离与出手节奏使战斗重视判断，而不是单纯提高按键速度。看懂敌人之后，朴素的一击也能具有充分意义。','构筑提供不同进入方式，盾牌、远程、魔法和装备负重影响风险管理。它并非只有一种正确技术路线，但信息说明并不总充分。玩家社区补足许多知识，也让作品的实际体验部分延伸到游戏之外。'],
['死亡留下可追回的东西','损失与回收机制让失败后的路线带上新的情绪。返回并不只是重复，因为你知道危险，也知道自己留下了什么。这个循环让地形学习与资源管理互相驱动，使勇气成为一个可反复调整的判断。','当回程过长、镜头失控或技术表现妨碍判断时，惩罚则可能失去教育价值。原作部分区域的帧率与后段完成度问题，不能被“受苦美学”一笔带过。严厉需要足够清楚和可靠的规则支持。'],
['残余比说明更能表达衰败','人物对白、物品文字与建筑关系提供不完整历史。世界显得已经经历漫长耗损，玩家只能从残余理解曾经的秩序。叙事方式与艰难跋涉相互呼应，使孤独并非纯粹背景音乐制造的情绪。','留言、幻影、召唤与入侵又让孤独中出现他人痕迹。帮助和威胁可以来自同一连接方式，形成非常特殊的社会气氛。其规则复杂且不透明，但正是这些有限接触，使陌生人有时比持续陪伴更令人记得。'],
['类型坐标来自一组关系的传播','《恶魔之魂》是不可跳过的直接先辈，《黑暗之魂》则以世界连接和更广泛传播巩固了这一设计传统。后来的“魂类”讨论借用其名字，但耐力、检查点或高难度的单项相似，不能自动证明完整继承。','本馆以它对动作角色扮演讨论与设计实践的长期影响授予历史标签。2021 年金摇杆玩家投票将其选为终极年度全时代游戏，是一种接受史证据，而不是客观证明它高于所有作品的定理。']
],
'《黑暗之魂》的力量在于让学习世界成为成长，而不只是提高角色数值。它有技术、信息与后段质量上的真实缺陷，却以空间和风险的紧密联系建立了持续影响行业的范式。值得收藏的是这套关系，而不是把困难本身奉为荣誉。',
['GamesRadar+ · 2011 年评测','https://www.gamesradar.com/dark-souls-review/','评测讨论探索、战斗与异步联网，也明确指出镜头和帧率问题。'],
[['直接先辈','恶魔之魂','死亡回收、世界联机与挑战结构的重要前身。'],['设计后续','艾尔登法环','用广阔地理为同一家族的挑战提供更多绕行路线。','elden-ring'],['动作分支','只狼：影逝二度','以固定主角与架势攻防重组战斗。','sekiro']]]);

;

