games.forEach(g=>{
 const old=artworks[g.id]||{};Object.assign(g,old);
 const main=museumPictures[g.id];
 const original=old.image?{url:old.image,source:old.imageSource,caption:g.title+' · '+(g.id==='pokemon'?'原版像素画面（官方虚拟主机资料）':g.id==='doom'?'《DOOM + DOOM II》再发行版截图':'官方版本素材'),note:'保留来源原图；未做像素放大'}:null;
 g.pictures=[main,original].filter(Boolean);
 if(main){g.image=main.url;g.hero=main.url;g.imageSource=main.source;}
});

;

