/* editorial.js */
/* Original editorial prose. Media notes are short attributed paraphrases, not reproduced reviews. */
function E(id,order,genre,mode,themes,features,headline,intro,headings,paragraphs,pull,verdictTitle,verdict,media){const g=games.find(g=>g.id===id);Object.assign(g,{order,genre,mode,themes,features,review:{headline,intro,headings,paragraphs,pull,verdictTitle,verdict,media}})}
E('death-stranding',20191108,'动作冒险','单人＋异步联网',['科幻','末日','荒野'],['开放世界','运输建设','慢节奏','作者表达'],
'跋涉不是抵达故事之前的空白，跋涉就是故事。',
'多数开放世界都希望你忘记路途的成本。《死亡搁浅》却让你低头看脚下：一块石头、一条河、一件放错位置的货物，都可能改变下一分钟的行动。它让人产生感情的方式很特殊——先让世界显得难以穿越，再让一个素未谋面的人留下的东西，替你分担这段困难。理解这一点，才能理解它为什么既令人着迷，也令人不耐烦。',
['先学会走路，再理解世界','一座桥的价值，来自它省下的艰难','孤独如何变成共同生活的证据','解释得太多，也可能削弱感受'],
['开局的身体并不是一台无所不能的探索机器。货物堆得越高，越需要管理重心；看似近在眼前的直线，可能被河流和坡度变成高风险路线。于是地图从一张目的地清单，变成一组需要预判的条件。玩家逐渐记住的不是哪个图标给多少奖励，而是哪里能安全过河、哪里值得留下梯子。熟悉世界的过程，也是在形成自己的地方知识。',
'建设系统之所以有效，是因为设施先有使用价值，才有象征价值。如果道路一开始就完备，沿途的感谢很可能只是装饰性文字；当玩家经历过徒步运输，看到别人的道路材料与避雨设施，劳动才获得可感的尺度。持续升级装备又产生另一重变化：第一次艰难穿越的路，后来可能成为高效率运输网络的一部分，地图的意义随能力与公共投入重新分配。',
'视听最有力量的时刻，常发生在行动已经延续一段时间之后。环境声维持身体与空间的距离，远处的目的地给长镜头一个方向，音乐进入时便不只是抒情背景，而像对一段劳动的回应。它仍大量使用电影演员与过场，但最独特的表达并不依靠明星面孔。真正难以从截图中传达的，是玩家先付出了时间，才对一片景色产生所有权般的记忆。',
'这种设计也很容易被自己的解释欲打断。复杂术语、反复讲述的连接主题和菜单操作，有时会把原本已经由行动表达的情绪重新说一遍。运送并非天然有趣，玩家需要接受它的速度与重复，才可能读出设施建设之后的变化。因此它的分歧不是简单的“懂不懂艺术”，而是不同的人愿不愿意承担相同的体验成本。'],
'当帮助真正改变了一段路，连接才不再只是一个词。',
'一次值得保留的设计冒险',
'本馆珍藏它，因为它扩大了大型游戏可以要求玩家关注的事物。它不需要在每段演出和每场战斗中都完美，才能证明运输、劳动与陌生人的善意足以支撑一部作品。适合愿意慢下来、观察路线变化的人；如果期待持续密集的动作刺激，它会是一段需要重新调整节奏的旅程。',
{name:'GamesRadar+ · Death Stranding 评测（2019）',url:'https://www.gamesradar.com/death-stranding-review/',note:'该评测批评冗长解释对节奏的影响。这也提示我们：体验本身成立，并不意味着所有叙事表达都同样有效。'});
E('death-stranding-2',20250626,'动作冒险','单人＋异步联网',['科幻','末日','荒野'],['开放世界','运输建设','潜行','电影化叙事'],
'当通向彼此的道路越来越多，连接的答案反而复杂起来。',
'续作最困难的问题，往往不是还能增加什么，而是增加之后会失去什么。《死亡搁浅 2》让行动更灵活，场景更壮观，运输工具与战斗选择更充足；它必须面对的考验，也由“送货能不能成为游戏”变成“当困难更容易被解决，送货还会不会留下原来那种重量”。',
['从证明一种玩法，到扩展一种生活','自由选择，让旅程有不同的速度','更大的舞台，仍需要安静的距离','便利与摩擦之间没有永久答案'],
['前作要求玩家花时间建立对这套世界的信任，第二部则面对两类观众：已经习惯跋涉的人，以及被视听奇观吸引的新来者。续作的组织更主动地展示工具和变化，减少某些漫长等待。这样做能够扩大体验入口，却也意味着初次看见公共建设的惊喜不可能原样重现。对老玩家而言，重要的发现不再只是“这里能造桥”，而是熟悉的方法在新条件下是否仍然可靠。',
'潜行、绕行与正面战斗的并存，让玩家有机会选择自己愿意承担的成本。一个危险区域可以被看作火力问题，也可以被看作路线问题。这种弹性提高了系统的包容度，但作品仍需要地形、天气和运送条件保持足够分量，否则所有路线最终都会变成效率最高的那一种。好的选择并非菜单里选项多，而是每种方法都保留独特的时间、资源与风险账单。',
'更复杂的画面能够让荒野显得真实，却无法单独制造孤独。真正重要的是大场景如何安排可行动的方向，以及在人物和目的地之间留下多少时间。角色演出与音乐扩大了情绪强度，长距离移动则让这些情绪慢慢沉淀。可以把它看作两种节奏的交替：一部分邀请玩家接受作者的戏剧，另一部分把解释权交给正在行走的人。',
'续作越体贴，越容易触及前作的一项隐性资产：麻烦本身有时就是主题。如果工具把所有阻力都抹平，帮助和依赖也会变轻；但刻意保留阻力，又可能让新玩家觉得重复。这不是一道能够靠“更多内容”自动解决的题。评价本作，需要同时考察它如何改善操作，以及这种改善是否改变了行为原本的情绪后果。'],
'更自由的旅程，也需要值得认真面对的阻力。',
'成熟化，并不意味着问题已经结束',
'它值得与第一部并置，因为两部作品共同构成一个很少见的设计讨论：新玩法如何从激进提案变成可以容纳更多人的系统。第二部的行业地位仍需时间，但对路线、行动选择和情绪节奏的调整已经足够具体。最好将它当作一次重写问题的续篇，而不是只检查它比前作多了多少东西。',
{name:'TechRadar · Death Stranding 2 评测（2025）',url:'https://www.techradar.com/gaming/death-stranding-2-on-the-beach-review',note:'评测肯定动作改善，同时认为运输与探索仍是核心。这里的关键正是扩展是否保住原作的重心。'});
E('spider-man',20180907,'动作冒险','单人',['超级英雄','城市'],['开放世界','高速移动','连击战斗','电影化叙事'],
'最成功的超级英雄改编，让移动本身成为目的。',
'真正检验一款蜘蛛侠游戏的，不是它能让多少熟悉的反派登场，而是任务结束之后，你是否还愿意再摆荡几个街区。Insomniac 的答案建立在身体感上：城市不再只是一张通往剧情的地图，而是不断邀请玩家完成下一个动作的空间。它对成熟公式的依赖很明显，但对“成为蜘蛛侠”这件事的执行也足够准确。',
['纽约首先是一张动作地图','轻松流畅，并不等于没有设计','能力越强，日常困境越有分量','熟悉的开放世界，怎样避免疲惫'],
['楼宇高度、街道宽度和可见的远方共同决定摆荡的节奏。玩家不需要逐一计算每根蛛丝的物理细节，却能从加速、跃出和落地的反馈中感到自己在参与。这里有大量隐形的体贴：动画过渡吸收不完美的输入，镜头替玩家强调速度，环境密度持续提供新的方向。它用合理的辅助换取英雄幻想，而不是把每次失误都变成对操作能力的惩罚。',
'战斗也遵循相似原则。普通攻击可以迅速建立流畅的连击，真正的变化来自目标选择：先处理远处威胁，还是把身边的敌人抛向空中？把环境物件变成武器，还是保留道具应对下一波？这种结构让美观动作与战术决策共享同一套输入，不必等玩家完全掌握系统才开始呈现角色魅力。精通带来的奖励，是更有章法地调度混乱。',
'彼得作为普通人的窘迫，为强大的操作能力提供了必要对照。城市中的声音与人物关系把宏大危机拉回一张具体的生活网络：英雄可以轻易跨过一栋楼，却无法用相同方式跨过责任。故事的有效之处不只是制造危险，而是让玩家已经喜欢上的能力承担情感代价。熟悉角色的人能看到改写，不熟悉的人也能理解人物为什么无法一直留在空中。',
'据点、收集与重复犯罪事件在较长游玩后会露出生产模板。问题并不在于地图上有图标，而在于这些图标是否还能提出新的动作问题。部分切换角色的流程虽然拓展叙事视角，却可能削弱已经建立的速度感。它的高完成度因此集中在核心循环，而不是平均分配给所有任务；想评估它，应当将摆荡与战斗的长久吸引力和内容重复分别讨论。'],
'当城市适合一具身体，角色就不再只存在于过场里。',
'一个成熟公式的准确落点',
'它进入圣殿的理由，是把授权角色的能力与玩家高频行动紧密地连起来。它既不是第一部开放城市蜘蛛侠，也没有发明连击战斗，却证明了精细整合本身可以创造难以替代的体验。若想理解商业动作游戏如何让大量玩家迅速获得身体上的愉悦，这是一件很好的展品。',
{name:'GamesRadar+ · Marvel’s Spider-Man 评测（2018）',url:'https://www.gamesradar.com/marvel-spider-man-ps4-review/',note:'评测同时指出熟悉的开放世界模板与流畅核心玩法，提供了判断它“成熟整合”价值的直接对照。'});
E('spider-man-2',20231020,'动作冒险','单人',['超级英雄','城市'],['开放世界','高速移动','双主角','电影化叙事'],
'速度翻倍之后，城市与人物能否一起长大？',
'《漫威蜘蛛侠 2》最直接的承诺，是让玩家更快、更自由地穿过纽约。蛛网翼拓展了空间，双主角扩展了人物关系，共生体能力又把力量的诱惑推到操作层面。但一部优秀续作不仅需要更强烈的第一印象，还要让增加的地图和人物，在有限流程里获得相称的意义。',
['移动升级，改变的不只是赶路时间','两位英雄，共享一种操作语言','力量的诱惑需要手感，也需要铺垫','当所有东西都想成为高潮'],
['蛛网翼让建筑之间的穿行加入了更长的滑翔距离，风道和开放水域因此获得新的设计价值。地图扩大如果只带来更长通勤，玩家很快会转向快速移动；当移动方法本身变化，扩张才有机会成为体验。速度提升还要求城市更快地交出视觉线索，否则流畅会变成失去方向的滑过。续作的技术表现，正是在这种高速可读性里体现实际用途。',
'两位主角需要足够相近，才能避免每次切换都像重新学习；也需要足够不同，才能让人物身份进入战斗。共享基础动作提供连续性，不同能力则改变处理敌群的方式。这个折中适合大众动作冒险，但也意味着两人不会像两个完全独立的游戏。双主角的真正回报，是同一座城市能够承载不同的家庭、朋友和情感负担。',
'共生体的威力不仅可以在剧情里被描述，也能通过进攻范围与攻击表现被感知。游戏利用这种直接的力量反馈，让人物变化有身体层面的证据。不过演出越强调强大，叙事越需要足够篇幅安置失控的过程；否则玩家可能先接受了一套好用能力，再被故事要求迅速改变对它的态度。动作系统和人物弧线之间的速度差，是评估这一部分的重要角度。',
'更密集的事件让流程很少缺乏刺激，但也会压缩反派和配角的停留时间。开放世界支线承担着补足人物生活的职责，若玩家只追主线，感受到的故事比例又会不同。这里没有必要用“全面超越”或“毫无创新”概括：移动与技术整合可以明确进步，叙事分配却仍有独立的得失。续作的完成度需要逐层拆开，而不是被规模一个数字决定。'],
'技术让切换更快，写作才让两个人都值得停留。',
'一次强大而拥挤的续作扩展',
'本馆把它与 2018 年作品并列，观察同一种核心快感如何被延长。它展示了高速移动、双主角和高规格演出的整合能力，也提醒我们：续作增加的每项资源，都需要重新安排注意力。若最在意城市穿行与动作奇观，它极具吸引力；若关心人物发展，则更值得与前作和《迈尔斯·莫拉莱斯》一起读。',
{name:'GamesRadar+ · Marvel’s Spider-Man 2 评测（2023）',url:'https://www.gamesradar.com/marvels-spider-man-2-review/',note:'评测高度评价城市视觉、战斗与移动。本馆在此之外进一步讨论双主角和高密度演出的注意力分配。'});
E('wukong',20240820,'动作角色扮演','单人',['中国神话','东方文化','奇幻'],['首领战','章回叙事','高难度','作者表达'],
'当神话不再只是背景，而成为必须亲手面对的存在。',
'《黑神话：悟空》的吸引力，首先来自一个足够具体的承诺：让中国神话中的形象拥有可以被观察、判断和对抗的身体。造像、山门、妖怪与棍棒动作共同构成世界，但它不满足于让玩家参观。每场首领战都要求把视觉奇观拆解成出招、距离和窗口，文化材料因而进入了一次真实的学习过程。',
['一场首领战，是认识陌生者的过程','棍势与法术，怎样组织进攻意图','章回之间，文化拥有自己的声音','壮丽景观不总是清晰的道路'],
['首领的外形如果只提供辨识度，玩家很快会只记住血条；当体态、动作节奏与攻击范围彼此呼应，角色才能在战斗中成立。悟空的重要成果，是让遭遇具有较强的个体性。玩家不仅学习何时闪避，也在判断对手的表演欲、停顿与欺骗。连续失败后的胜利因此不只是数值成长，而是原本陌生的动作逐渐成为可理解的语言。',
'法术与变身给近身攻防提供调整节奏的工具，但法力和冷却限制又阻止它们永久接管战斗。棍势的积累与重击兑现，让玩家必须考虑何时继续施压、何时保留机会。它和魂系共享遭遇学习等特征，却没有必要被简化成某个既有类型的复制品：战斗资源与能力组合的组织方式，决定了玩家如何表达进攻，而不只是如何避免受伤。',
'章末动画让不同形式的视觉表达进入同一部作品，短暂改变观看规则。游戏中的建筑与造像又给这些段落提供文化触感：它们不是抽象的“东方元素”，而让空间带有材料、年代与信仰的重量。对于熟悉《西游记》的人，改写和留白带来额外阅读；对于不熟悉的人，形象与冲突仍能先建立感性关系，知识可以在游玩之后继续补充。',
'视觉真实不等于行动范围清楚。看起来能走的地方被挡住，会削弱玩家对场景的信任；区域规模扩大之后，首领之间的连接也未必同样充实。评价它的探索，必须与美术质量分开。同时，国产工业意义值得认真记录，却不该变成免于讨论缺点的护盾。越希望它为后来者打开道路，越需要具体指出哪些能力已经建立，哪些环节还值得继续改善。'],
'最有力量的文化表达，让观众成为参与者。',
'值得庆祝，也值得认真拆解',
'它的入馆理由横跨两个层面：一方面是富有辨识度的遭遇与视听，另一方面是中国团队将本土文化组织成高规格买断作品的具体实践。前者需要靠一场场战斗解释，后者需要靠长期作品验证。把二者分开，才能既保留它带来的振奋，也给予它作为游戏本身应有的严肃评价。',
{name:'PC Gamer · Black Myth: Wukong 评测（2024）',url:'https://www.pcgamer.com/games/rpg/black-myth-wukong-review/',note:'评测特别关注首领设计和鲜明角色，并认为单用“魂类”不足以解释其特点；这也是本馆采用机制分析而非单一类型归类的原因。'});
E('metro',20190215,'第一人称射击','单人',['末日','荒野','东欧'],['区域探索','资源管理','潜行','具身界面'],
'离开地下之后，世界更开阔，生命却没有变轻。',
'《地铁：离去》最值得肯定的，不是终于让玩家看见更多天空，而是没有因为走上地表就忘记系列的身体感。呼吸、枪械、污染与照明仍然贴着人物存在。列车把区域连成一趟旅程，停留和出发之间有了生活的差别；因此它的半开放结构，与标准清单式大地图拥有不同的节奏。',
['列车不是菜单，而是旅程中的家','资源压力要制造判断，也可能制造琐碎','用一层面罩，把风景变成环境','半开放结构的收益与代价'],
['传统线性射击擅长控制每一分钟的强度，开放世界擅长提供自己的路径。《离去》用章节保留作者控制，再在区域内部释放探索。列车尤其重要：它让同行者不必只在任务需要时出现，而能够在间歇里交谈、休息和延续关系。世界变化因而不是加载一张新地图那么简单，玩家带着同一群人的经历离开旧地方，也把新的见闻带回熟悉的车厢。',
'弹药与零件的价值来自下一次危险，而不是抽象库存。武器改装让搜刮所得可以迅速转化成行动差异，少量资源也可能决定潜行还是交战。然而检查容器、维护武器和反复寻找补给会占用大量注意力，必须靠环境与遭遇保持新鲜。当资源匮乏只剩重复劳动，它就会从末日生存的语法变成延长流程的摩擦；作品最有趣的时刻，是两者仍保持平衡的时候。',
'面罩并不是一个永久不变的屏幕滤镜。污染、破损与擦拭把玩家和环境连接起来，提醒人眼前的景观具有真实危险。枪械上的粗糙材料、手部动作和声音也持续给物品提供重量。这种表达不需要随时用台词强调末日：角色只是为了继续前进而照料工具，世界已经通过这些动作说明了自己的规则。它的沉浸来自具体依赖，而非单纯减少界面。',
'区域探索能产生未经主线安排的记忆，也暴露敌人反应、路径与脚本之间的限制。若玩家期待完全自由的系统模拟，会发现作者仍强烈决定着很多过程。迟缓交互有时增强脆弱感，有时又阻碍紧张场面中的精确操作。它的意义恰好在这种折中：给线性旅程更多呼吸空间，却仍坚持一条可以被共同讨论的公路叙事。'],
'所谓末日，是你开始认真照料每一件能让自己活下去的东西。',
'一趟拥有停顿的末日旅程',
'本馆珍藏它的区域结构与具身表达。它让开放不必等于无限扩张，也让真实不必等于繁复模拟；列车、环境和同行者共同构成一段有方向的旅程。适合喜欢沉浸式世界、愿意容忍一定动作摩擦的人。阅读技术成就时，还应将原作与后来增强版的渲染升级分别理解。',
{name:'PC Gamer · Metro Exodus 评测（2019）',url:'https://www.pcgamer.com/metro-exodus-review/',note:'评测肯定枪械手感与改装，同时指出敌人反应和持续搜刮的局限，体现了沉浸感与操作负担之间的张力。'});
E('astro',20240906,'三维平台','单人',['科幻','明亮世界'],['精密跳跃','触觉反馈','关卡创意','轻松入门'],
'轻盈不是浅薄，而是复杂制作最终呈现出的从容。',
'《宇宙机器人》看起来毫不费力：跳跃清楚，机关活泼，几乎每走一小段就有新玩意出现。但这种轻盈背后，是对动作距离、失败成本和信息密度的严格控制。它让玩家迅速理解规则，又及时带来变化，不需要用沉重叙事证明严肃性，也不依赖长期养成维持参与。',
['先让跳跃值得信任','一个能力，足够长出一座小世界','触觉是空间信息，不只是振动','怀旧可以点缀，不能替代好关卡'],
['平台游戏最基本的承诺，是让玩家相信看到的空间与能够完成的动作相符。落点、角色阴影、悬浮修正和边缘判断共同建立这种信任，失败才更容易被理解为自己的判断问题。宇宙机器人不急着先展示复杂规则，而先让跑、跳、击打本身具有愉悦。这是看似基础、实际上最难靠额外内容补救的品质。',
'新能力的价值不只在第一次演示。一个关卡会先让它解决明确问题，再改变高度、移动条件或时机，让相同工具产生不同用途。设计在玩家完全厌倦之前收束，又把下一次惊喜留给新的地方。这种高变化密度需要大量内容制作，也需要敢于结束一个已经有效的点子，避免用重复填满关卡长度。',
'手柄反馈可以提示材料变化、力量释放和环境反应，把屏幕之外的感官变成阅读世界的一部分。真正有效的硬件展示应当让玩家更懂当前动作，而不只是知道设备能产生多少种震动。这里的触觉与声音、动画相互支持；即使暂时不注意技术，玩家也能把它们体验为“这个东西碰起来就是这样”。',
'熟悉的 PlayStation 角色提供收藏与辨认的快乐，但如果拿掉这些符号，平台动作依然需要独立成立。它的成功在于多数时候能够通过这个检验。相反，快速更换机制也意味着部分创意刚展开便结束，追求长期精深练习的人可能希望它再多停留。大众进入门槛与机制深挖，不必被强行当成同一种目标。'],
'成熟的设计，有时表现为玩家根本没有意识到自己正在被教会。',
'一部把工艺藏进快乐里的作品',
'它值得入馆，因为它证明精确、短促与充满变化的游戏仍有巨大表达力。可爱外观不妨碍严密结构，硬件展示也可以成为真正的玩法。它与马力欧等平台传统共同构成一条长线：设计师通过空间变化与反馈，帮助玩家持续发现自己的能力。',
{name:'GamesRadar+ · Astro Bot 评测（2024）',url:'https://www.gamesradar.com/games/platformer/astro-bot-review/',note:'评测认为，即便去掉手柄附加特性，精准响应的基础动作仍足以支撑乐趣。这区分了硬件加分与核心设计。'});
E('re4',20230324,'动作恐怖','单人',['生存恐怖','阴郁世界'],['越肩射击','资源管理','格挡','经典重制'],
'重制经典的真正工作，是重新设计玩家为什么会害怕。',
'当你可以边走边瞄准，原来围绕“站定射击”成立的一场战斗就已经改变了。《生化危机 4：重制版》面对的核心任务不是恢复记忆中的每一处墙面，而是让熟悉的村庄、城堡和敌人，在新的操作能力下重新具有压力。好的重制由此成为一次解释，而不是一层外观更新。',
['危险必须追得上更灵活的里昂','刀具让防御成为有成本的主动行为','熟悉的路线，陌生的节奏','保留记忆，也接受气质发生变化'],
['现代移动射击给玩家更多空间，敌人的迫近方式也需要重新安排。人群包围、投掷物与近身威胁让视野前方不是唯一需要处理的方向。射中一个目标之后，是追求击杀还是利用短暂硬直离开夹击？这种瞬间判断维持了原作的核心吸引力，却不要求玩家照搬旧操作。压力来自更灵活的双方，而非仅仅提高敌人的血量。',
'格挡给近身危险增加了漂亮而直接的回答，但刀具耐久阻止它变成免费的永久保险。资源因此不只存在于弹匣和药草里，也存在于一种救命能力的剩余次数中。玩家要决定何时争取主动，何时保留工具，何时为失误支付维修成本。反应技巧和长期管理在同一件装备上相遇，使战斗层次比单纯新增按键更丰富。',
'场景再设计的乐趣在于熟悉感与预判失效交替出现。老玩家能够认出目的地，却未必知道新的围堵、路线或人物行为；新玩家则获得一条独立成立的冒险。商人和背包仍提供节奏缓冲，升级选择让下一次出发带着具体期待。它理解了经典的身份不只属于关卡清单，也属于紧张、整理、喘息和重新进入危险的循环。',
'更严肃的表演与更真实的环境改变了原作略带夸张的娱乐气质。有人会喜欢这种凝聚，也有人会想念更古怪的对白与节奏，这不是只看清晰度就能解决的偏好。重制版的优秀也不应使原作退出历史：两者之间操作规则与情绪结构的差异，反而是理解游戏如何随时代变化的最好材料。'],
'让玩家更强之后，仍能让危险成立，才是重制的本事。',
'值得与原作同时留下',
'这是一件关于再设计的展品：它保留核心循环，重构压力来源，也形成自己的动作表达。对于首次接触的人，它足以作为独立作品阅读；对于熟悉原作的人，它提供一次辨认“哪些记忆来自场景，哪些来自规则”的机会。圣殿将两个版本分别收藏，正是为了保留这种比较。',
{name:'GamesRadar+ · Resident Evil 4 Remake 评测（2023）',url:'https://www.gamesradar.com/resident-evil-4-remake-review/',note:'评测着重肯定紧张战斗与喘息间隙的节奏平衡；这种节奏比单独的画面升级更能解释重制的完成度。'});
E('gt7',20220304,'驾驶模拟','单人＋在线多人',['汽车文化','现实世界'],['车辆收藏','精密驾驶','摄影','博物馆叙事'],
'一辆车先成为知识，再成为收藏，最后成为身体的记忆。',
'GT7 对汽车的理解，并不止于“用什么跑得更快”。车辆也可以是设计史、制造工艺、童年海报和时代欲望的集合。它用驾驶、收藏、摄影与介绍把这些关系组织起来，让不了解汽车的人有进入路径，也让懂车的人能够为细节停留。这种文化框架，决定了它与纯粹竞速游乐场的不同。',
['驾照把复杂运动拆成可以练习的判断','一座车库，可以有博物馆的逻辑','驾驶之外的时间，是否仍有意义','热爱汽车，不代表接受所有获取门槛'],
['制动点、重心变化和出弯油门很难通过长篇说明真正掌握，短小训练却能把错误压缩成一次可复现的反馈。GT 的传统长处，是让玩家围绕很具体的动作改进：早一点刹车，晚一点转向，少一点急促修正。成绩进步来自对同一段路更准确的认识，因此车辆和赛道不是内容数量，而是具有长期学习空间的组合。',
'咖啡厅菜单把收藏安排为有主题的阶段，品牌与车辆介绍又把性能数字放回历史。此时获得一辆车，不只是换到更强的装备，也可能理解一种工业选择：为什么某个年代偏爱轻量，为什么某类布局适合特定用途。博物馆式叙事最有价值的地方，是让知识回到下一次观看和驾驶之中，而不是完成后立即被遗忘的解锁文字。',
'摄影与展示让车辆拥有比赛之外的存在方式。光线、材质、车身比例与背景之间的关系，可以让一名不追求最快圈速的玩家建立自己的审美参与。这扩大了“赛车游戏玩家”的定义：收藏者、摄影者与竞赛者能够分享同一组对象。与此同时，菜单和介绍若打断了想立刻上赛道的人，也会显得累赘；产品必须容纳不同深度的热爱。',
'车辆获取的经济节奏、联网要求和赛事编排，会直接影响文化承诺是否可信。欣赏一辆车和拥有足够条件驾驶它，是两种不同的体验；当获取成本过于突出，收藏可能从探索转成等待。优秀的物理和展示不应遮住这些问题，单人追赶式赛事也不必然提供与真人竞赛相同的战术。它的优点与缺点，恰好分布在车库和赛道之间。'],
'收藏的意义，是让对象拥有性能之外的来历。',
'把热爱组织成一套可参与的文化',
'本馆从 GT7 学到的，是展示对象与讲述历史可以形成同一个循环。它的价值并非每项机制都新，而是让驾驶、收藏与知识不断相互说明。对汽车文化感兴趣的人，可以在竞速之外找到长久吸引；评价它时，也应该把驾驶工艺与获取经济分别审视。',
{name:'GamesRadar+ · Gran Turismo 7 评测（2022）',url:'https://www.gamesradar.com/gran-turismo-7-review/',note:'评测赞赏物理表现与单人挑战，同时指出部分单人赛事更接近追赶而非完整竞赛，提示驾驶质量与赛事结构应分别判断。'});
E('rdr2',20181026,'动作冒险','单人＋在线多人',['西部','历史','荒野'],['开放世界','慢节奏','电影化叙事','环境细节'],
'一个时代的消逝，先发生在日常生活的细节里。',
'《荒野大镖客：救赎 2》愿意把时间花在很多看似不必要的动作上：照料马匹、穿过营地、听完一段并不立刻给奖励的对话。它用这些时间建立了一个世界的重量，然后让人物在这个世界里面对变化。其力量来自长期陪伴，而最大的争议也来自同一个选择——不是每个玩家都愿意以相同速度生活。',
['细节只有形成关系，才成为世界','营地让人物在任务之外继续存在','自由世界与严格任务的两套逻辑','慢动作如何积累情绪，又如何制造负担'],
['草木与天气只是可信世界的一部分，动物、路人、物品和声音之间的连续性更为关键。一次停留能否遇见合乎地方气质的事情，某个动作是否得到恰当反馈，决定风景会不会成为生活空间。高制作成本的真正价值，在于大量细节彼此一致；如果只把它们当作“做了多少动画”的清单，就会漏掉这些细节共同维护的行动预期。',
'营地不是简单的任务分发站。人物通过闲谈、争执和共同劳动显示关系，让主线事件拥有持续背景。玩家能够先对一个人的习惯产生认识，再理解他在关键情节中的行为。电影可以高效介绍人物，游戏的独特优势则是允许相处变得并不高效：你可能错过一段谈话，也可能在无意中听到让某个角色突然具体起来的细节。',
'在荒野自由行动时，玩家可以自行安排目标；进入主线任务后，却常需要遵循规定路线和时机。这种落差不是偶然瑕疵，而是两种设计追求的碰撞：系统希望玩家自由，电影式演出需要控制。作品在许多时刻靠精彩调度使人接受控制，但限制仍然存在。把它称为“完全自由的世界”，会掩盖其实际的作者性。',
'缓慢动画让人物具有体重，也让重复搜刮与移动占据时间。对一部分人，这些时间积累了栖居感；对另一部分人，它们会反复阻断意图。两种感受都合理。作品最动人的地方往往是细节终于转成情绪的时候，但不能因此认定每个冗长动作都有同样必要。讨论节奏，应该具体到它提供了什么感受，以及要求玩家支付多少耐心。'],
'你不是只记得发生了什么，也会记得曾经怎样生活。',
'一部以陪伴积累重量的西部作品',
'它值得收藏，是因为它将高规格生产能力投入一种不急于兑现的情绪结构：日常先存在，变化才有代价。世界密度、角色关系与表演共同支撑这份重量，同时留下自由与控制的明显张力。它适合愿意停留和观察的人，也适合作为讨论开放世界是否必须始终高效的案例。',
{name:'PC Gamer · Red Dead Redemption 2 PC 评测（2019）',url:'https://www.pcgamer.com/red-dead-redemption-2-review/',note:'该文将作品和角色的高评价与 PC 首发稳定性问题分开。本馆同样保留版本口径，不把移植问题当成 2018 年原作的全部表现。'});
E('detroit',20180525,'互动叙事','单人',['科幻','人工智能','社会议题'],['多分支','双主角／多主角','道德选择','电影化叙事'],
'选择之所以沉重，是因为故事不必为你的失误停止。',
'很多游戏把失败理解为一个需要撤销的状态，《底特律：变人》却经常让失败继续生长。调查不充分、回答太迟或判断错误，都可能改变后来还能看见什么。它最有吸引力的不是抽象的“结局很多”，而是让玩家意识到自己正在关闭某些可能；这个意识，比一张庞大分支图更接近互动叙事的核心。',
['倒计时改变了道德判断的质地','三个人，三种接近社会的距离','流程图既是邀请，也是诱惑','议题的宏大不能自动保证复杂'],
['没有时间压力时，选择很容易变成搜索最优答案。倒计时、调查线索与关系状态把决定放回情境：你知道的并不完整，能够采取的行动也不完全相同。因此一个按钮的意义依赖之前做了什么。它把简单输入放进复杂后果中，降低操作门槛，却没有完全降低心理成本；这正是电影式互动能够成立的原因。',
'不同主角分别面对亲密关系、职业任务与公共行动，给同一世界提供不同尺度。玩家在视角切换时携带额外信息，却不能保证人物同样知道，这种信息差制造了戏剧张力。三条线也让作品不必只靠宏大宣言表达冲突，家庭和搭档关系中的小选择，能够比抽象社会比喻更直接地建立情感。',
'章节后的流程图将未走过的路显露出来，让一次经历成为可以研究的结构。它有助于理解后果，也会诱使玩家立即回头修正，追求所有分支都被点亮。于是第一轮的承担与后续的完成主义产生区别：前者像在生活，后者像在校对。作品两种玩法都支持，却会带来不同感受；想保留选择重量的人，可以先允许自己的路线不够完美。',
'仿生人的社会处境借用了现实历史的许多符号，这让议题容易辨认，也可能使复杂问题被过快地压缩。高规格表演能够增强可信感，却不能代替对立场和制度的细致推演。评价时，分支工程、人物情绪与政治隐喻需要分别讨论。它能够令人投入，也能够引发质疑，这种并存比简单宣布它“深刻”更有讨论价值。'],
'一条没有选过的路，也会参与塑造已经走过的故事。',
'把叙事网络变成可以承担的经历',
'它是互动电影生产能力的代表，也是一件能用来讨论选择设计边界的作品。技术与表演使后果看起来具体，多视角让责任不只停在一个人物身上。它不要求动作熟练，适合喜欢人物与分支的人；但丰富的后果并不意味着所有议题都同样细腻，本馆保留这种区别。',
{name:'GamesRadar+ · Detroit: Become Human 评测（2018）',url:'https://www.gamesradar.com/detroit-become-human-review/',note:'评测肯定其叙事野心与完成度，同时预见作品会带来分歧。这里的分歧也是阅读议题表达的重要入口。'});
E('portal',20071010,'空间解谜','单人',['科幻','实验室','黑色幽默'],['空间推理','短篇体验','环境叙事','极简规则'],
'你以为自己在解决房间，直到发现房间正在定义你。',
'《传送门》从一条非常清晰的空间规则出发，却没有停在机械谜题合集。随着玩家理解成对传送门如何改变距离与动量，测试设施的秩序也逐渐变得可疑。学习和怀疑发生在同一条路上：你越会使用系统，就越可能不再完全接受系统给出的解释。',
['有限规则，足够改变整个空间','教学应当让人产生发现感','一个声音如何占据一座设施','短篇的力量，来自及时结束'],
['两点之间的距离不再由走廊长度决定，而由可放置传送门的表面关系决定。玩家需要把空间想象成可以重新连接的结构，落差也能被转译成通过另一扇门的速度。规则数量很少，但每个新房间都改变已有元素的排列，因此问题不断更新。它的深度来自组合和视角转换，不必靠大量技能或库存维持复杂。',
'早期谜题把变量拆得清楚，让玩家在相对安全的环境里试验。之后才开始要求把多个理解连在一起，成功便像自己发现了一种可能，而不是照着说明书填空。设施背景使教学有了故事上的理由，也让重复测试显得有意为之。即使某一步需要多次尝试，失败通常仍在帮助理解同一条可见规则。',
'GLaDOS 的存在并不依赖频繁出现在镜头中。语言、停顿与不合情理的指令使空房间产生人格，玩家逐渐学会听出制度化口吻里的裂缝。干净表面与隐藏空间之间的对照，又让建筑承担叙事。黑色幽默因此不是谜题之间的奖励，而是和规则一起塑造玩家对世界的判断。',
'它的流程短，使机制和情绪能够在疲劳出现之前结束。以时长衡量价值的人可能觉得不够，但短篇也减少了创意被摊薄的机会。相反，少量动作要求和第一人称空间判断仍可能让完全没有游戏经验的人遇到门槛；“规则少”并不等于所有人都能立刻熟练。它的简洁是高度组织后的结果，不是未经设计的空白。'],
'最好的谜题，不只打开一扇门，也改变看待门的方式。',
'几乎没有多余部分的机制寓言',
'它进入圣殿，是因为机制、教学、空间和角色口吻彼此服务，形成一部体量克制却完整的作品。它也提醒行业，创意并不总需要数十小时才能具有分量。理解它的前身《Narbacular Drop》，再阅读《传送门 2》的扩展，会看到一个核心想法如何从学生实验成长为成熟表达。',
{name:'GamesRadar+ · Portal 评测',url:'https://www.gamesradar.com/portal-review/',note:'这份同期评测可作为回看作品的入口。本馆重点讨论它如何将空间规则、教学和叙事组织在同一流程中。'});
E('it-takes-two',20210326,'合作冒险','强制双人合作',['家庭','童话','明亮世界'],['非对称合作','分屏','关卡创意','轻松入门'],
'关系不是一段对白，而是两个人必须一起完成的动作。',
'《双人成行》从设计第一步就确定了一个前提：另一个人不是可有可无的帮手。两位玩家的工具、视角和时机必须相互补充，故事才能继续。它把合作从菜单选项提升为整部作品的组织原则，也因此获得许多单人游戏很难复制的笑声、争执和默契。',
['互补能力，比共同开火更接近合作','每一章都在重新分配两个人的关系','家庭物件为何适合变成冒险空间','高变化密度，也有必须付出的代价'],
['如果两个人拥有完全相同的工具，合作很容易退化成各做各的。这里的能力经常一方创造条件、另一方完成动作，迫使玩家解释自己的需要。真正的关卡因此不只存在于屏幕里，也存在于现实对话：你能不能等一下，能不能告诉我刚才发生了什么？这种沟通成本被转成主要乐趣，使熟悉游戏的人也不能简单替搭档完成全部体验。',
'不断更换机制会重置两人的熟练度差距。某一段更擅长瞄准的人掌握主动，下一段可能轮到善于观察或掌握节拍的人。能力变化因此既提供新鲜感，也改变合作中的权力分配。失败通常允许较快恢复，使沟通不会被过高惩罚反复打断。它让玩家愿意尝试夸张的动作，而不是为避免拖累搭档而变得畏缩。',
'熟悉物件被放大之后，空间立刻同时拥有亲切和陌生两种属性。玩具、工具和日常设施可以成为机关，不需要长篇解释就能让玩家理解材料特征。婚姻叙事则为这趟共同劳动提供主题，尽管角色说出的和玩家实际体验到的并不总是完全一致。作品最有效的时刻，是让现实搭档自己形成默契，而不是由角色替他们宣布关系已经改变。',
'快速切换机制意味着某些有趣规则刚开始变深就被放下，追求系统精通的人可能感到意犹未尽。强制合作也要求两人的时间和耐心匹配，操作水平悬殊时仍可能产生负担。它的包容性来自反馈与重试设计，并非完全没有门槛。评价一部合作作品，不能只看单个人能否完成，更应看两人如何一起经历困难。'],
'关卡的另一半，有时就在坐在你身边的人那里。',
'合作成为作品的语法',
'本馆珍藏它，因为它让题材与玩法在“必须一起行动”这一点上拥有持续联系。它的变化密度、能力互补和低重试成本共同维护了两人关系。它尤其适合愿意交流的搭档，而不仅是寻找第二个手柄的人；与《逃出生天》和《双影奇境》并置，还能看到这条团队路线如何持续演化。',
{name:'GamesRadar+ · It Takes Two 评测（2021）',url:'https://www.gamesradar.com/it-takes-two-review-hazelight/',note:'评测肯定持续变化的合作体验。本馆进一步关注这些变化如何让两位现实玩家重新分配沟通和主动权。'});
E('titanfall-2',20161028,'第一人称射击','单人＋在线多人',['科幻','机甲'],['高速移动','关卡创意','短篇战役','竞技对战'],
'跑过一面墙，射击游戏的空间就不再只有地面。',
'《泰坦陨落 2》不满足于让玩家在掩体后找到更好的射击角度。它要求你把墙面、落差和空中路线看作可以持续行动的空间，然后在高速之中判断何时进攻。单人战役又把这一套运动基础放进不断变化的关卡构思，让“接下来是什么”成为持续的吸引力。',
['移动本身就是战术','短战役如何容纳高密度创意','BT 为什么不只是一个大号武器','越流畅的动作，越需要清晰的空间'],
['地面射击通常把位置与移动分开：先占位，再开火。铁驭的能力让两者更紧密地重叠，移动中的路线选择会不断制造新的攻击角度。优秀玩家的差异不仅是命中率，还包括怎样让滑行、跳跃和蹬墙保持连续。它提高了操作的表达空间，也意味着新玩家需要逐步摆脱停在安全位置等待敌人的习惯。',
'战役经常围绕一个新的空间条件建立关卡，而不只是增添更坚固的敌人。著名的时间切换段落使同一位置对应不同危险与通路，移动基础因此得到新的解释。创意被集中展开后及时结束，下一段再提出另一个问题。这种节奏承认短篇也可以完整，不需要把每个好点子重复到足以支撑数小时才算有价值。',
'泰坦带来另一种尺度：当铁驭依靠轻快与路线生存，机甲依靠力量和装备应对战场。进入与离开驾驶舱改变身体感，也让 BT 的存在始终具有实际用途。叙事中的信任因此得到操作支持，人物关系不是只在过场里建立。玩家反复依赖同一个伙伴完成行动，机器逐渐从系统功能变成可以记住的对象。',
'高速战斗需要环境轮廓和路线信息足够清楚，否则速度会使空间变得不可读。多人竞争的上限也很高，初学者面对熟练玩家可能难以理解自己如何失败。单人战役和多人模式共享基础，却服务于不同节奏；不能因其中一种短暂失衡就否定另一种的价值，也不能因一段精彩关卡就假定全部流程同样惊人。'],
'最精彩的射击瞬间，有时先由脚下的路线创造。',
'一部懂得及时交出新问题的战役',
'它的入馆价值是动作与关卡之间的高度配合，以及用实际合作为人机关系建立重量。它不一定靠最长流程留住人，却用密集变化形成清晰记忆。对线性动作冒险感兴趣的人，尤其值得观察它如何让熟悉的移动规则在不断改变的空间中保持生命力。',
{name:'PC Gamer · Titanfall 2 评测（2016）',url:'https://www.pcgamer.com/titanfall-2-review/',note:'评测强调高速移动的技巧空间，以及滑行、跳跃和蹬墙连续使用时的表达能力。'});
E('witcher-3',20150519,'角色扮演','单人',['黑暗奇幻','文学改编'],['开放世界','道德选择','任务叙事','角色养成'],
'一份不起眼的委托，也可以承载一个世界的伦理。',
'《巫师 3》最重要的成就，未必在于主线有多宏大，而在于它经常让支线拥有足够完整的动机与后果。一个看起来只是除掉怪物的任务，可能逐渐变成关于恐惧、利益和伤害的判断。开放世界因此不只是任务分布的容器，而成为无数局部生活相互挤压的地方。',
['职业身份，使选择拥有具体语境','调查改变的应当是理解，而不只是进度','世界的黑暗来自生活，不只是色调','好故事也会遭遇重复的操作'],
['杰洛特不是可以任意捏成的空白角色。他有专业能力、社会位置与既有关系，玩家的选择在这些条件中发生。这样做减少了身份自由，却增加了判断的密度：收取报酬和介入不公之间，职业中立和私人感情之间，都有清楚张力。玩家不必每次从零决定“我是怎样的人”，而是在一个既定人物的边界内解释他会怎样行动。',
'追踪与调查最有价值的结果，不是让下一处标记亮起来，而是改变玩家对事件的理解。委托人的说法未必完整，怪物也未必能独自解释恐怖的来源。作品在许多任务里让战斗成为结论之前的一个环节，而不是所有问题的最终答案。选择的后果又可能延后出现，使玩家难以立刻获得简单的道德成绩单。',
'战争与贫困如果只作为背景形容词，很快就会被壮丽风景抵消。这里的小人物、地方传闻与私人欲望让宏观环境落到具体生活中。音乐和地域美术帮助区分地方气质，台词则给冲突提供个性。一个村庄值得记住，往往不是因为地图面积，而是因为玩家记得这里的人曾经如何解释自己的困境。',
'任务写作的完成度不代表所有操作都同样多变。反复使用感官追踪、相似遭遇和地图兴趣点，可能让玩家在优质故事之间经历较机械的连接。动作战斗与装备成长也应单独评价，而不能被文本声誉全部覆盖。它展示了作者叙事如何大规模进入开放世界，同时仍保留了这种生产方法需要填充、组织与重复的现实。'],
'好的支线，让地图上的一个点拥有自己的理由。',
'开放世界可以被认真写作',
'它值得留在圣殿，因为它改变了许多玩家对支线应有质量的期待。文学基础、固定主角与任务制作共同建立了一种成熟方法：让宏大世界由局部冲突构成。它尤其适合愿意阅读人物动机与延迟后果的人；如果只用地图大小或动作强度评价，会错过它最有分量的部分。',
{name:'PC Gamer · The Witcher 3: Wild Hunt 评测',url:'https://www.pcgamer.com/the-witcher-3-review/',note:'评测将丰富故事与压迫性的世界气质作为核心评价。本馆据此进一步讨论任务写作如何进入开放空间。'});
E('sifu',20220208,'动作格斗','单人',['武术','东方文化'],['高难度','格挡','重复精进','年龄机制'],
'真正升级的不是角色，而是拿着手柄的人。',
'《师父》把一种常见却容易被忽略的游戏经验放到中心：同一个房间，第一次看是混乱，后来再看却能读出秩序。敌人数量没有减少，玩家已经知道该站在哪里、先处理谁、何时不该急着进攻。衰老把每次失误刻在角色身上，重来则把经验留在玩家这里。',
['群战首先是一道位置题','死亡之后，时间成为可见的成本','动作电影的漂亮，来自正确判断','重复需要让人看见自己的进步'],
['被多人包围时，单纯提高攻击频率通常不能解决问题。位置、敌人出手顺序和可用物件共同决定安全窗口，主动移动可以让一个敌人暂时挡住另一个敌人。结构值又使攻防不只围绕生命数字展开。你需要阅读局面，而不是把一套熟悉连招强塞进每个房间；武术感由这种判断产生，不只来自动作动画。',
'复起避免一次失败立即终止尝试，却让年龄持续累积。这样一来，玩家可以继续看见后续内容，但到达时的状态由之前表现决定。关卡重访有了明确目标：不是机械重复，而是用更少代价完成已知过程。年龄把长期资源与即时技巧连在一起，提醒玩家每次侥幸过关和真正掌握之间仍有区别。',
'场景构图、动作节拍和环境物件让战斗具有电影式观赏性，但镜头并不替玩家完成核心时机。一次漂亮的连贯行动之所以有满足感，是因为它来自判断和执行的吻合。场景色调又把关卡分成清晰记忆，不需要庞大地图才能形成旅程。它把制作资源集中在能够反复经受游玩的空间，而非只供一次观看的规模。',
'高门槛的教学和重复练习可能让进步发生之前，耐心就已经耗尽。对于不能清楚识别自己为何失败的人，衰老只会放大挫败。因此难度的价值不能由“很难”本身保证，而要看反馈能否把失败变成知识。它的故事相对克制，也意味着玩家需要主要从行为而非长篇人物发展中寻找主题。'],
'同一条走廊没有变，变的是你阅读它的能力。',
'把精进过程做成了作品的形状',
'《师父》的集中是它的力量。它用年龄、群战和关卡重访，使修炼不只存在于题材，而发生在玩家反复行动之中。它适合愿意把熟悉空间当作练习对象的人；同样也需要承认，严苛学习并不适合所有人。它的珍贵，在于规则与主题如此直接地相互解释。',
{name:'PC Gamer · Sifu 评测（2022）',url:'https://www.pcgamer.com/sifu-review/',note:'评测将其定义为受功夫与武术电影启发、具有挑战性的单人动作作品。这里重点分析挑战如何通过年龄和重复学习形成意义。'});
E('re4-2005',20050111,'动作恐怖','单人',['生存恐怖','阴郁世界'],['越肩射击','资源管理','遭遇设计','类型转折'],
'当瞄准要求你停下，所有靠近的脚步都有了分量。',
'今天回看 2005 年的《生化危机 4》，最容易犯的错误是只注意不能移动射击。这个限制并不是孤立的笨拙，而与敌人速度、硬直、空间围堵共同形成战斗。它让玩家在“留下完成一次攻击”和“立即重新站位”之间不断切换，恐惧由此被重新组织成一连串清晰、紧迫的动作判断。',
['越肩镜头如何重新分配信息','敌人的身体成为解题线索','背包与商人，让危险拥有间奏','夸张与恐怖可以同时成立'],
['镜头靠近角色后，敌人的动作和命中部位变得更容易观察，周边视野却相应收窄。玩家能更精确地处理面前的危险，也更需要留意身后的空间。这不是单纯从旧镜头换到新镜头，而是把信息优势和信息盲区重新安排。由此建立的临场感，与早期固定镜头利用不可见区域制造不安的方式既相通又不同。',
'头部、腿部与武器的反馈让每一枪不只是减少生命。一次硬直可以换取体术、移动或喘息，玩家开始把弹药看作控制场面的工具。敌群持续压缩空间，于是最好的选择未必是先杀死一个人，而可能是打断最危险的行动。战斗具有可读性，却不因此失去紧张，因为精准判断仍需要在有限时间里兑现。',
'商人让战斗之后的资源获得未来方向：修整背包、出售物品和升级武器，都在为下一段危险做准备。背包空间把携带能力可视化，整理本身成为一种短暂秩序，与外部世界的混乱形成反差。关卡由此不必始终保持最高压力，松弛的片刻反而帮助下一场战斗重新变得有效。',
'作品的台词、奇观和敌人设计经常带着夸张的娱乐性。它可以在恐怖中保留荒诞，避免所有情绪都被同一种阴沉覆盖。这样的气质和后来的重制版本并不完全一致，也说明“更真实”不总等于“更接近经典”。同时，旧操作与部分时代性设计仍可能构成门槛；理解它为何成立，不意味着要求所有现代玩家都必须喜欢。'],
'限制并非天然落后，关键在于整个游戏是否围绕它成立。',
'必须以原作身份被看见的经典',
'它的重要性来自镜头、敌群与资源系统形成的整体，而不只是一项经常被引用的历史标签。与重制版并读，能够清楚看见操作便利如何改变危险。圣殿单独收藏它，是为了避免用后来的版本替原作回答所有问题，也为了保留它独特的幽默、节奏与动作张力。',
{name:'Nintendo Life · Resident Evil 4 GameCube 评测（2006）',url:'https://www.nintendolife.com/reviews/gamecube/resident_evil_4',note:'评测认为旧式控制在新视角下获得了更自然的作用，这正说明操作应与镜头和遭遇一起评价。'});
E('gta-v',20130917,'动作冒险','单人＋在线多人',['城市','犯罪','社会讽刺'],['开放世界','双主角／多主角','系统互动','长期运营'],
'一座城市，同时容纳作者的剧本和玩家的胡闹。',
'《GTA V》的规模当然显眼，但真正难以复制的是它的整合：驾驶、射击、任务演出、交通秩序与讽刺性声音，必须在同一座城市里保持连续。玩家可以追随三名主角的故事，也可以暂时放弃故事，观察一个系统如何回应自己。它既是一部被写好的作品，也是一处不断产生意外事件的舞台。',
['城市的可信度，来自系统之间的接缝','三位主角，使任务可以像电影一样剪辑','讽刺不只在台词里，也在日常声音中','单人作品与线上生态，需要分开评价'],
['一个开放世界并不会因为包含很多活动就自动成立。从步行进入载具，从街道转入任务，从一次碰撞演化为警察追逐，每一次转换都可能暴露系统的边界。GTA V 的工业能力集中在让这些边界足够顺畅：玩家未必关注具体技术，却能持续保有行动意图。自由感往往就来自不同系统愿意接住前一个动作的后果。',
'多主角让叙事可以跨越不同社会位置，也让大型任务不必困在一具身体里。切换把任务节奏交给玩家和作者共同调度，视角变化本身具有戏剧性。但这并不等同于真正自由编排整个行动，许多任务仍要求按脚本推进。它的特色是一种精细控制的切换能力，而不是对所有故事可能性的无限开放。',
'广播、广告、路人谈话和空间分布共同塑造洛圣都的文化气质。即使暂时不推进剧情，城市也在继续表达消费欲望与社会矛盾。讽刺因此不只是几段尖刻对白，而成为日常噪音。然而讽刺对象过多、口吻持续尖酸，也可能让人物缺乏情感停留的空间；聪明与冷漠之间的距离，是作品值得继续讨论的一部分。',
'GTA Online 把空间转成长期内容与社交经济，延长了作品寿命，也改变了评价标准。单人叙事关心一次旅程如何结束，线上产品关心下一次为什么回来。两者共享资产，却不应共享所有功劳或问题。玩家创作与角色扮演社群也不是官方单人内容的简单延伸，它们说明城市作为平台可以被其他人重新解释。'],
'一个强大的世界，会产生作者没有亲手安排的故事。',
'工业整合能力的代表性样本',
'它的地位来自许多成熟系统在同一空间中协同工作，并让玩家拥有持续制造事件的能力。它不是所有机制的发明者，也不能仅靠长寿解释伟大；作为大型开放世界的集成作品，它提供了足够多具体细节，说明规模怎样真正转化为体验。',
{name:'PC Gamer · GTA 5 PC 评测（2015）',url:'https://www.pcgamer.com/gta-5-review/',note:'PC 版评测特别讨论第一人称模式的完整动画投入。该模式属于后续版本，不能倒写成 2013 年首发就具备的功能。'});
E('pong',19721129,'街机对抗','本地双人',['体育','抽象世界'],['极简规则','即时反馈','街机文化','轻松入门'],
'两块球拍和一个光点，让屏幕从观看对象变成公共场地。',
'面对《Pong》，现代玩家很容易觉得没有什么可介绍：画面空旷，动作有限，也没有成长。但把这些熟悉的规则放回 1972 年，它们曾经完成了一次重要转变——让没有技术知识的人，看一眼就知道自己能改变屏幕上的事情。极少内容由此承载了巨大的媒介变化。',
['简单必须首先能够被理解','对手让有限规则保持变化','一台机器，也是一个社交空间','历史重要性与今天的乐趣不是同一问题'],
['Pong 不要求记忆复杂按键，也不需要先掌握世界观。球的方向、球拍的位置和得分结果都可以直接看见，动作与反馈之间的距离极短。这个结构把学习过程放进第一轮尝试：哪怕只观察别人玩，也能理解主要目标。对早期商业机器而言，这种可观察性极其重要，因为玩家未必愿意先阅读一份说明再投币。',
'规则有限不代表过程完全重复。另一个玩家会预判、诱导和犯错，节奏来自双方持续改变的判断。注意力集中到球路与反应，屏幕上的每一点变化都获得比复杂背景中更高的权重。它不靠内容更新维持每局差异，而靠对抗本身生成变化；这是许多后来竞技设计仍然使用的基本资源。',
'街机柜把操作绑定到一个现实地点，围观、轮换和短暂对抗构成游玩的一部分。今天通过小窗口看它的截图，很容易漏掉这种身体和空间关系。它不仅是一段程序，也是一件经过商业部署的公共器物，技术被装进一个能让陌生人迅速理解的形状，娱乐产业才有机会围绕它建立持续经营。',
'不能因为它对历史重要，就假定它会给现代玩家提供与大型作品相同的丰富度。它的节奏、变化和表现都很有限，长期吸引力依赖具体对手与场景。也不能把商业成功写成电子游戏的发明时刻。严肃收藏的意义，是同时说明它之前已经存在什么，以及它怎样让一种已有可能进入更多人的生活。'],
'屏幕上的变化第一次变得如此直接：这是你刚才做的。',
'媒介进入大众生活的清晰切面',
'Pong 作为展品，不需要借用现代内容规模证明自身。它让即时反馈、可理解操作与现实社交成为一个简单整体，展示技术如何转成大众行为。今天重看它，应当既保留对设计简洁性的欣赏，也把它放回街机柜、经营者与玩家共同形成的环境。',
{name:'The Strong · Pong 历史馆藏；早期作品采用历史研究视角',url:'https://www.museumofplay.org/games/pong/',note:'馆藏资料区分了 Pong 的大众商业影响与更早的电子网球游戏。本文采用历史回看，不伪造 1972 年的现代式媒体评测。'});
E('space-invaders',19780601,'固定屏幕射击','单人',['科幻','太空'],['街机文化','高分挑战','难度递进','极简规则'],
'敌人越来越少，压力却越来越大。',
'《太空侵略者》抓住了一种特别有效的紧张关系：玩家清除威胁，剩余威胁却不断逼近。屏幕范围固定，行动方向有限，局势的变化因此格外容易感知。它没有用复杂故事说服玩家坚持，而把“再来一局”的欲望组织在分数、失败和逐渐形成的技巧之间。',
['固定空间，也可以持续收紧','声音把压力变成可以听见的节奏','高分让一次游戏连接到下一次','经典的价值不需要都市传说作证'],
['掩体并不是永久安全的背景，敌阵也不是静止的靶子。它们在同一画面里不断改变，使原本宽裕的行动空间逐渐显得局促。玩家必须同时处理瞄准机会与生存空间，不能只根据眼前一个目标做决定。极少的视觉元素因而形成了相互制约的系统，清晰可见的危险比不可理解的突袭更容易促成重试。',
'重复的声音与敌阵变化建立身体上的紧迫感。画面没有现代电影式演出，节奏却可以通过简单结构持续升级。玩家不需要被告知“情况更危险了”，就能够从运动与声音的关系中读出压力。这种用系统状态组织情绪的方法，比任何一个外星人图案都更有持久的设计价值。',
'高分将游玩从一次输赢转成可以持续改进的表现。玩家不仅对抗敌人，也在对抗自己的纪录或他人留下的数字。失败保留了比较尺度，所以结束不是把全部经验清空，而是留下下一次尝试的目标。街机经营需要短循环，技巧成长需要长期线索，两者在分数上获得了有效连接。',
'以今天的标准看，它的动作和内容变化都有限，游戏历史也不能只由发行后的传说构成。著名的硬币短缺故事尤其不应未经考证便作为成就证明。更有说服力的分析已经存在于屏幕本身：它如何安排进攻、掩体、速度与得分，以及这种安排为何适合当时的街机空间。'],
'完成一部分目标，并不总意味着世界更安全。',
'将压力压缩进一个屏幕的作品',
'它值得入馆，因为它用易读规则建立了持续变化的难度与高分循环，并成为街机文化的重要符号。与《Pong》比较，可以看到大众电子游戏从双人对抗走向强烈单人挑战的一条路径；与后来的射击游戏比较，又能看见固定空间中许多至今有效的设计问题。',
{name:'The Strong · Space Invaders 历史馆藏',url:'https://www.museumofplay.org/games/space-invaders/',note:'早期街机采用历史馆藏资料与规则分析，不把后续移植或续作的功能混入 1978 年原作。'});
E('tetris',19840606,'益智','单人',['抽象世界'],['极简规则','空间推理','高分挑战','轻松入门'],
'你亲手制造混乱，也亲手让它消失。',
'《俄罗斯方块》没有角色替你承担命运，也没有剧情为紧张提供理由。越来越高的堆积已经足够说明一切。每次摆放既解决当前问题，也决定后面的选择会有多困难；当一排终于消失，释放来自你对同一空间状态的重新组织。如此抽象的规则，却能产生异常直接的情绪。',
['眼前的最佳选择，未必对未来最好','清除为什么会带来如此明确的满足','跨设备传播，依赖可读的核心','讨论一个系列，必须保留版本差别'],
['理想布局与及时消行之间始终有拉扯。等待某个形状可能保留更高收益，也可能不断积累风险；眼前补平一处缺口，有时会给之后留下更难处理的结构。玩家因此在局部和整体之间来回切换。时间限制阻止无限计算，又让已经形成的经验变成快速判断。深度不来自记住很多条规则，而来自同一规则在不同局势下产生不同代价。',
'堆积本身是看得见的压力，消行则让这份压力以非常直接的方式减少。玩家无需解释就能读懂情况，哪怕旁观者也能迅速理解某次挽救为何漂亮。它同时满足整理和冒险两种欲望：你希望空间整齐，又愿意暂时制造危险以争取更好的回报。抽象表面下，存在的是一组十分具体的心理权衡。',
'方块和边界不依赖语言，基本目标可以在很短时间里被观察出来。这样的设计适合进入不同尺寸屏幕和不同长度的闲暇时段，便携硬件又进一步放大它的日常性。但移植从来不是完全中性的：输入、屏幕比例与速度会影响判断，因此同一个规则核心也可以在不同设备上拥有不同身体感。',
'后来版本的暂存、旋转规则、联网竞技与视听表现都有自己的演化历史，不能一股脑算作 1984 年原作的功能。本馆以早期设计为坐标，同时借后续版本观察它的可扩展性。经典的生命力并不是从未改变，而是改变之后仍能辨认出那组关于空间、时间和风险的基本关系。'],
'一条规则可以很少，一次决定的后果可以很多。',
'纯规则也能拥有情绪曲线',
'它进入圣殿，是因为它用极少表达建立了极强可读性，并把瞬间满足与长期局势连在一起。对行业而言，它是一份关于设计经济性的持久示范；对玩家而言，它仍是一种可以不断重返的整理与冒险。以版本意识阅读它，比笼统称作“永远不变的完美游戏”更准确。',
{name:'Nintendo Life · Tetris Forever 评测（2024，历史合集）',url:'https://www.nintendolife.com/reviews/switch-eshop/tetris-forever',note:'该评测讨论历史合集的访谈与版本跨度，适合作为回看设计演化的入口；不是对 1984 原版的同期评测。'});
E('mario',19850913,'横版平台','单人／轮流双人',['奇幻','明亮世界'],['精密跳跃','关卡教学','隐藏探索','类型奠基'],
'第一关没有讲课，却已经改变了玩家看世界的方式。',
'《超级马力欧兄弟》的经典性，不能只用童年回忆解释。它把移动、风险和奖励安排在一个可以逐步学会的空间里，让玩家通过尝试形成规则理解。敌人、砖块和深坑不只是障碍物，而是设计师与玩家之间的语言；之后整场冒险，就是不断改变这些词的排列。',
['跳跃不是按钮，而是一种可学习的身体','关卡怎样让错误也有用','隐藏空间让熟悉的路保留秘密','简洁背后，同样有时代门槛'],
['奔跑速度会改变跳跃距离，落地位置又影响下一次动作。于是玩家不只是对准一个目标按键，而需要建立对角色惯性的预期。熟练之后，一连串地形可以被读成连续动作，单独的障碍逐渐变成节奏。手感的重要性正在于此：它必须稳定到足以被学习，又有足够差异让进步真实存在。',
'开场用相对清楚的空间安排让玩家认识敌人、方块和奖励；后续再组合这些元素，改变安全距离与时间条件。学习不是由一整页说明一次性交付，而被分布在实际行动里。失败如果能够让人看见自己误判了什么，就不会只剩惩罚。这种通过空间教会规则的方式，是后来平台设计持续讨论的重要传统。',
'隐藏奖励与捷径让地图不只服务于首次通过。玩家回到熟悉地方时，会开始注意之前忽略的高度、可疑砖块和路线差异。于是同一关卡可以承载求生、收集与速度三种不同目标。内容没有增加，观察方式却发生变化，这是作品能被反复游玩的重要原因，也说明重复价值不必总靠新的数值奖励提供。',
'原作的有限生命、续关方式和后期难度，仍可能令现代初学者感到严苛。它的教学清楚，并不代表每个人都能轻松通关。家用机市场的变化也不是一部软件独自造成，需要把硬件、渠道和其他作品一并纳入。去掉夸大的英雄叙事，反而更容易看清它在具体动作与关卡上的扎实贡献。'],
'好的关卡，会让玩家误以为知识是自己发现的。',
'一套仍在被使用的平台语言',
'它值得被收藏为可反复分析的设计样本：移动稳定、空间可读、规则通过变化而不是解释展开。即使今天更容易接触到丰富的后续作品，原作仍清楚展示了这些关系如何彼此成立。观看它，不只是在怀旧，也是学习游戏如何让第一次行动变成下一次行动的准备。',
{name:'HonestGamers · Super Mario Bros. 回顾评测',url:'https://www.honestgamers.com/9569/nes/super-mario-bros/review.html',note:'回顾文章关注滚动关卡不断带来的变化；开发背景同时参考文末任天堂访谈。'});
E('doom',19931210,'第一人称射击','单人＋多人',['科幻','恶魔','生存恐怖'],['高速战斗','迷宫探索','模组文化','技术转折'],
'它让空间成为动作，也让玩家成为后来内容的作者。',
'《DOOM》的速度只是第一印象。真正持续推动游玩的，是敌人、弹药、走廊和秘密之间不断变化的关系。它让第一人称空间兼具身体冲击与结构探索，又把内容开放给玩家改造。作品的影响因此既在屏幕之内，也在关卡制作、分享与对战形成的社群里。',
['一间房怎样成为战术问题','探索给高速战斗留下另一种节拍','技术的意义，是让空间及时回应','模组让作品的边界不再由发行日决定'],
['不同敌人的攻击方式让站位产生意义。玩家在移动中避开危险，同时判断用哪种武器解决眼前局面；房间的入口、落差与障碍改变选择价值。血量和弹药不能自动恢复到理想状态，又让一次交战的成本延续到之后。爽快因此并不等于没有管理，而是把判断压进较高速度，让资源和空间同时参与动作。',
'钥匙、开关与秘密把地图组织成需要理解的结构，短暂迷路也可能成为寻找联系的过程。它不始终沿着唯一走廊向前推进，而让玩家回看自己刚经过的地方。战斗与探索交替改变注意力：一部分时间关心下一秒，一部分时间关心整个区域。这种切换使作品不必单靠敌人数量不断提高强度。',
'原作的技术限制很明确，并不是今天意义上的完全三维世界，但设计把可用能力投入最能影响体验的地方。空间变化、光照与高速响应共同制造临场感，资源效率直接决定玩家能否连续行动。技术史不应只比较画面像素，也应该观察开发者如何选择值得计算的东西，并让这些选择服务于操作。',
'可替换的内容和制作工具使玩家能够重写关卡，社群由消费者变成延续作品的人。模组也让玩法想象超出官方原本的边界，改变了游戏的寿命结构。开放并不意味着自动产生优秀内容，但它提供了必要条件：一部作品不再只能等待原作者发布下一章，而能被不同的人用作表达基础。'],
'当地图可以被重写，游戏也成为一种创作语言。',
'速度与开放共同形成的经典',
'它的价值在于把技术效率、战斗空间与玩家创造结合起来。只讲画面冲击会漏掉关卡文化，只讲模组又会忽略原作本身扎实的动作组织。圣殿保留它，是为了看见技术与社群如何共同延长作品，也提醒我们不要把后来的三维能力倒置为 1993 年已经拥有的一切。',
{name:'Thumb Culture · Playing Doom…30 Years Later 回顾',url:'https://www.thumbculture.co.uk/playing-doom-30-years-later-a-retrospective-review',note:'回顾涉及不同版本的表现差异；本文以 1993 年 PC 原作为主体，不将移植限制混为原作设计。'});
E('pokemon',19960227,'角色扮演','单人＋本地通信',['生物收集','奇幻'],['收集养成','回合战斗','交换社交','类型奠基'],
'一只精灵的价值，可以来自战斗，也可以来自送给你的人。',
'《宝可梦 红／绿》把一件看似私人化的事情——收集自己的队伍——放进了需要他人的结构。版本差异和通信功能使世界不能只靠一个人完全拥有。数字生物因此获得了数值之外的来历：在哪里遇见，为什么留下，曾经和谁交换。这是它能够超出单次冒险、进入生活关系的重要原因。',
['收集首先要让对象值得记住','回合战斗为不同队伍保留空间','版本差异把屏幕连到现实','开创性的社交，也有初代的粗糙'],
['生物的轮廓、名字、属性和成长构成了一个可以逐步认识的世界。捕获过程又让得到某个成员不是自动发生的奖励，而是一段需要准备与判断的小事件。命名和长期培养使相似数据拥有私人区别，一只未必最强的宝可梦也可能因共同经历而难以替换。系统在功能和情感之间留出了空间，收藏才不会只是列表打勾。',
'回合制让反应速度不再决定所有表现，玩家可以思考属性、技能和队伍配置。不同生物并非只是一条统一强度阶梯，而在条件和关系中呈现作用。即使早期平衡并不完善，队伍搭配仍允许个人偏好参与。游戏由此同时容纳喜爱某个形象的玩家与钻研对战的人，两种关注共享对象，却不必追求相同目标。',
'通信要求玩家真正接触另一个设备和另一个人，交换具有现实时间与地点。版本独有生物让合作有明确价值，交换进化又把社交嵌入成长路线。它也制造了不便和依赖，但正是这种不能独自完成的部分，使游戏在操场和朋友之间拥有延续。社交并非加在核心之外的聊天功能，而参与了收藏本身的结构。',
'初代存在繁琐操作、系统不平衡与版本问题，不能因为系列后来取得巨大文化影响便忽略它们。现代版本改善了许多进入门槛，也可能改变早期那种需要互相询问的知识环境。红／绿与海外红／蓝并非完全相同的发行对象，讨论媒体回顾时应保留版本区别，避免把整个系列的成熟能力一次性归给起点。'],
'完成自己的收藏，有时意味着先认识另一个人。',
'把数字生物变成关系的载体',
'本馆珍藏初代，是因为它让收集、培养与现实交换构成一个循环。它的影响当然离不开动画、卡牌与长期经营，但软件已经提供了这套共享世界的核心关系。与后续作品比较，更能看见哪些改善降低了摩擦，又有哪些早期不便曾经意外地制造了交流。',
{name:'Nintendo Life · Pokémon Red and Blue 回顾评测（2009）',url:'https://www.nintendolife.com/reviews/2009/04/pokemon_red_and_blue_retro',note:'媒体回顾对应海外红／蓝版，用于观察初代系统的持续吸引；本馆展品年份与版本仍采用日本红／绿。'});
E('ocarina',19981121,'动作冒险','单人',['奇幻','时间旅行'],['三维探索','迷宫解谜','目标锁定','音乐交互'],
'成长，是同一个地方再也不以相同方式迎接你。',
'《时之笛》的技术与设计贡献经常被浓缩成 Z 锁定，但它真正完成的是一套三维冒险关系：怎样看见目标，怎样理解房间，怎样通过能力重新进入旧地方。时间变化又让这套空间关系获得情绪，玩家不是只听说自己长大，而会在再次抵达熟悉地点时感到世界已经不同。',
['三维化首先是一道信息组织题','道具不只解锁门，也改变房间的读法','音乐和回访让空间拥有记忆','历史范式仍然保留时代的棱角'],
['从二维到三维，玩家突然需要同时管理方向、距离和镜头。敌人在身体周围移动，如果视角不能稳定组织关系，战斗会先变成寻找敌人的困难。锁定与情境动作减少了这种无意义负担，让注意力回到进退与时机。它的影响不只是增加一个按钮，而是示范了怎样让复杂空间通过有限输入变得可以行动。',
'迷宫把新的道具能力放进局部谜题，再让玩家理解更大范围的空间结构。获得工具后回看旧房间，过去的阻碍可能成为现在的路径。成长因此不只增加伤害，而是改变观察方式。这套传统来自系列前史，三维空间让高度、视线和房间关系有了新的表达层次，也带来了理解整座迷宫的满足感。',
'音乐不是始终被动播放的伴奏，它也作为可以执行的动作进入世界。旋律与地点、人物和时间联系起来，使一次短小输入承载之前的记忆。儿童与成人阶段的回访又改变相同空间的气质，熟悉感与陌生感同时发生。地图因而可以讲述时间，并不需要每次都用全新场景证明故事正在推进。',
'原作的镜头、菜单和部分谜题在今天可能显得不够顺手，后来版本也做过针对性改善。历史影响不意味着所有细节都跨时代无损成立。评价它最好在两种视角间往返：一方面理解当年解决了什么，另一方面承认今天第一次接触的玩家仍会面对实际操作门槛。这样才能让经典保持可讨论，而不变成只允许敬仰的名字。'],
'回到同一座城，才知道时间真正改变了什么。',
'让空间成长与人物成长相互说明',
'它进入圣殿，是因为它把三维动作、迷宫能力与时间情绪组织成了一个整体。锁定系统只是其中最容易命名的一项成就，回访与音乐则说明它不仅建立操作范式，也探索了空间记忆的表达。与《梅祖拉的假面》并读，可以继续观察时间怎样成为游戏的结构，而不只是故事背景。',
{name:'Nintendo Life · The Legend of Zelda: Ocarina of Time N64 评测',url:'https://www.nintendolife.com/reviews/n64/legend_of_zelda_ocarina_of_time',note:'媒体回看作为整体评价入口，锁定与开发过程另参考文末任天堂原团队访谈。'});
E('wow',20041123,'大型多人角色扮演','大型多人在线',['奇幻','虚拟社会'],['团队协作','角色养成','公会社交','长期运营'],
'当下一次上线的理由，是有人正在等你。',
'《魔兽世界》让大型多人世界成为大量玩家的日常生活。它提供任务、装备和副本，却也生成约定、职责与共同记忆。一个角色不只是升级曲线，还可能是公会里别人认识的身份。理解它的持久吸引，必须同时看开发者制作的内容，以及玩家在内容之间形成的社会。',
['任务路线让广阔世界变得可以开始','职业分工把他人变成必要存在','服务器上的身份，也有现实连续性','黏性与负担，是同一种关系的两面'],
['一个持久世界对新玩家最大的困难，往往是太多事情同时存在，却不知道先做什么。区域任务提供逐步进入的路线，把地理移动与能力成长联系起来。它不是最早提供任务的在线角色扮演，但将世界可读性与大众进入路径结合得非常有效。玩家不必先理解全部系统，就能找到下一个有意义的目标，再逐渐接触组队、经济与更长期活动。',
'当不同角色负责承受伤害、恢复或输出，团队的成功就不能只由个人熟练度解释。每个人的行动影响他人的空间和机会，配合会生成信任，失误也可能带来冲突。这种依赖既是玩法，又是社会关系的来源：你记住某个人，不仅因为聊过天，也因为曾经共同解决过一场危险。',
'持续角色让过去经历可以累积。装备、称呼、集合地点和固定活动，都为重复上线提供连续性。玩家在同一世界里形成自己的仪式，很多记忆甚至不来自官方指定的高潮，而来自等待、赶路和突发事件。持久世界的独特之处，是允许内容之间的时间被人际关系填满，而不是所有意义都必须由开发者预先安排。',
'社交依赖也会转成时间义务。固定活动、成长差距和团队责任，可能让上线从期待变成压力。长期更新又不断改写门槛和目标，因此不能把任何一个当代版本视作 2004 年的静止延续。它既是作品，也是持续治理的服务；质量不仅在副本中，也在系统怎样分配玩家的时间、地位与参与机会。'],
'虚拟世界最真实的部分，常常是人与人之间的约定。',
'一件持续被玩家共同完成的展品',
'它的历史意义，是把成熟的大型多人结构带入更广泛的人群，并让个人成长与社会生活长久交织。收藏它不是宣布某一版本永久最好，而是记录一种媒介如何容纳组织、劳动和归属。阅读原版、怀旧服与后续资料片的差异，能够看到便利、挑战和社交依赖如何持续被重新权衡。',
{name:'PC Gamer · World of Warcraft Classic 评测（2019，怀旧服）',url:'https://www.pcgamer.com/world-of-warcraft-classic-review/',note:'这份评测以怀旧服回看早期玩法，不能当作 2004 年同期记录；本馆保留原版与后续服务演变的区别。'});
E('minecraft',20090517,'沙盒创造','单人＋在线多人',['生存','开放想象'],['自由建造','程序世界','玩家创作','探索'],
'世界并不急着告诉你目标，因为目标可以由你留下。',
'《我的世界》最有力量的邀请不是“这里什么都有”，而是“这里可以被你改变”。一块方块既是资源，也是墙壁、道路或装置的组成部分，作用由玩家的意图决定。生存提供紧迫，建造提供表达，多人则让一个想法需要被解释和协商。游戏由此成为工具，又没有完全离开游戏。',
['统一材料，使想象可以被快速执行','生存为自由创造提供第一份理由','一个建筑，也记录了一群人的关系','无限可能仍需要入口与边界'],
['统一的方块尺度简化了构造问题。玩家不用先掌握专业建模，就可以将想象转成可进入的空间；少量材料规则通过组合产生大量结果。限制并没有消灭创作，反而让别人更容易理解并加入同一套表达。这解释了为什么看似粗糙的外观不是纯粹技术不足，也成为共享创作语言的一部分。',
'第一夜的危险让采集与庇护具有明确意义，而一个临时住所又很容易长出新的欲望：更安全、更漂亮、更方便，或者仅仅更像自己的地方。目标在行动中自然生成，玩家不必始终等待任务列表。创造模式则移除部分压力，让表达成为主要动机；两种模式共享材料系统，却允许完全不同的时间节奏。',
'多人建造需要分工，也需要讨论什么值得做。一条路连向谁的房子，一块土地怎么使用，都可能承载实际关系。建筑因此不只是视觉结果，也是共同劳动的痕迹。玩家制作的视频、服务器与模组又把这种痕迹传播出去，作品不再只有官方内容可以被消费，还成为生产其他体验的基础。',
'自由度高的系统也可能让第一次进入的人茫然，不知道什么值得尝试。长期服务器需要管理，创作社群也并非自动友好；平台价值依赖工具、规则和人的共同维护。同时，2009 年公开版本、2011 年正式发行和后续多年更新必须区分。今天熟悉的许多能力来自漫长演化，不能把全部成熟结果压缩成一个天才瞬间。'],
'一座房子之所以重要，是因为有人决定它应该在那里。',
'游戏可以是一种持续创作的材料',
'它的入馆意义在于让玩家表达成为核心内容来源。生存、组合与分享相互支持，使同一个系统能够承担私人冒险、集体建设和更复杂的创作。它并非没有规则，而是把规则做成可被反复使用的材料；这种从完成作者目标到生成自己目标的转变，是电子游戏媒介的重要可能。',
{name:'PC Gamer · Minecraft 评测（2011）',url:'https://www.pcgamer.com/minecraft-review/',note:'评测强调创造空间与可记住的经历。对应正式发行阶段，本文同时保留 2009 年首次公开版本的历史坐标。'});

;

