/* app.js */
function museumPage(){return `<section class="spatial-page"><div class="spatial-heading"><div><p class="eyebrow">SPATIAL COLLECTION / 001—003</p><h1>每件物品，都通往一个世界。</h1></div><a href="#collection">返回珍藏柜 ↗</a></div><p class="spatial-touch-help">单指拖动视角 · 双指缩放 · 按住方向按钮移动</p><div class="spatial-stage" id="spatial-view"><div class="spatial-label"><span>DEATH STRANDING</span><p>死亡搁浅 · 常设空间展</p></div><p id="spatial-status" role="status">正在打开展厅…</p><div class="spatial-mode" role="group" aria-label="操作模式"><span>操作模式</span><button data-control-mode="cinema" aria-pressed="true">电影镜头</button><button data-control-mode="fps" aria-pressed="false">第一人称 FOV</button></div><div class="spatial-tools" role="group" aria-label="参观视角"><button data-view="lobby" aria-pressed="true">博物馆主厅</button><button data-view="hall" aria-pressed="false">死亡搁浅展厅 ↗</button><button data-view="spider" aria-pressed="false">漫威蜘蛛侠展厅 ↗</button><button data-view="west" aria-pressed="false">荒野大镖客 2 展厅 ↗</button><button data-view="land" aria-pressed="false">进入死亡搁浅实景</button><button data-view="bridge" aria-pressed="false">一座梯桥</button><button data-view="porter" aria-pressed="false">独行者</button></div><div class="spatial-bottom"><span id="spatial-help">电影镜头 · W / S 推近拉远 · A / D 左右环绕 · Q / E 下降上升 · 鼠标环绕</span><button id="spatial-motion" aria-pressed="false">自动环游</button><button id="spatial-rain" aria-pressed="true">雨幕 开</button><button id="spatial-home-view">标准视角</button><button id="spatial-reset">回到入口</button><button id="spatial-capture">拍摄纪念照 ↗</button></div><details class="spatial-lens"><summary>镜头 · 焦段与画质</summary><label for="spatial-focal">焦段 <output id="spatial-focal-value">35 mm</output></label><input id="spatial-focal" type="range" min="18" max="120" step="1" value="35"><button id="spatial-aa" aria-pressed="true">抗锯齿 开</button><button id="spatial-ssr" aria-pressed="false">屏幕空间反射 关</button><button id="spatial-dof" aria-pressed="false">景深 关</button><label for="spatial-aperture">光圈 <output id="spatial-aperture-value">F5.6</output></label><input id="spatial-aperture" type="range" min="0.95" max="8" step="0.05" value="5.6"><label for="spatial-focus">焦点距离 <output id="spatial-focus-value">18.0 m</output></label><input id="spatial-focus" type="range" min="0.5" max="100" step="0.1" value="18"><button id="spatial-focus-pick" aria-pressed="false">点击对焦</button></details><div class="spatial-pad" role="group" aria-label="移动控制"><button data-move="w" aria-label="W 前进或推近">↑</button><button data-move="a" aria-label="A 左移或左环绕">←</button><button data-move="s" aria-label="S 后退或拉远">↓</button><button data-move="d" aria-label="D 右移或右环绕">→</button><button data-move="q" aria-label="Q 下降">−</button><button data-move="e" aria-label="E 上升">＋</button></div><dialog id="spatial-photo"><div class="photo-heading"><span>你的展览纪念照</span><button autofocus aria-label="关闭照片预览">关闭 ×</button></div><img alt="当前三维视角与游戏圣殿策展文字组成的纪念照"><div class="photo-actions"><span>保留此刻的视角，把旅程带走。</span><a download="game-temple.png">保存 PNG 图片 ↓</a></div></dialog></div><div class="spatial-notes"><div><p class="eyebrow">THE FIRST CROSSING</p><h2>在抵达之前，先感受距离。</h2><p class="exhibit-description">苔原把人衬得很小。货物压在肩头，溪流横在前方，一架别人留下的梯子，让独自跋涉的人获得了与陌生人的连接。从博物馆中的梯子出发，点击传送门进入展厅，再走进这片荒野，换一个尺度理解《死亡搁浅》。你也可以选定一个角度，拍下一张属于自己的展览纪念照。</p></div><aside><span>展览档案 / 001</span><p>以现代美术馆的白盒子、挑高中庭与天窗采光为建筑灵感。游戏场景为本馆原创的风格化三维致敬，不是原作关卡或官方模型，也非 MoMA 建筑复刻。</p><a href="#game/death-stranding">阅读作品完整评测 ↗</a></aside></div></section>`;}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={query:'',genre:'',mode:'',theme:'',feature:'',sort:'curated',personal:false,tag:'',honor:''};let current='',galleryScroll=0,activeGame=null;
function img(g,which=0,hero=false,compact=false){const a=g.pictures?.[which]||g.pictures?.[0];const full=a?.url||g.hero||g.image,src=compact&&a?.thumbUrl?a.thumbUrl:full;return src?`<img src="${esc(src)}" data-fallback="${esc(full!==src?full:g.pictures?.find(p=>p.url!==full)?.url||'')}" alt="${esc(a?.caption||g.title+' · 官方游戏素材')}" ${hero?'fetchpriority="high"':'loading="lazy"'} decoding="async" width="${compact&&a?.thumbWidth||a?.width||2560}" height="${compact&&a?.thumbHeight||a?.height||1440}">`:'';}
function honorBadges(g){return `<div class="honor-badges">${g.personal?'<span class="honor ocean">✦ Ocean 精选</span>':''}${g.award?`<span class="honor annual">${g.award.year} ${g.award.program} 年度游戏</span>`:''}${g.historical?'<span class="honor historical">历史里程碑</span>':''}</div>`;}
function card(g){return `<a class="glass-card ${g.personal?'ocean-card':''}" href="#game/${g.id}" data-game="${esc(g.title)}" aria-label="阅读${esc(g.title)}完整介绍">${img(g,0,false,true)}<div class="card-top"><span class="card-year">${g.year}</span>${honorBadges(g)}</div><div class="card-copy"><h3>${esc(g.title)}</h3><p>${esc(g.review?.headline||g.impact)}</p><div class="card-tags">${[g.genre,g.mode,g.features?.[0]].filter(Boolean).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div></a>`;}
function failure(){document.querySelectorAll('#screen img').forEach(el=>el.addEventListener('error',()=>{if(el.dataset.fallback){el.src=el.dataset.fallback;delete el.dataset.fallback;el.onerror=()=>{el.hidden=true;el.parentElement.classList.add('image-failed')};return;}el.hidden=true;el.parentElement.classList.add('image-failed');if(el.parentElement.tagName==='FIGURE'){let c=el.parentElement.querySelector('figcaption');c.textContent+=' · 图片暂未加载，可在文末打开素材来源。';}},{once:true}));}
function homepage(){const ds=games.find(g=>g.id==='death-stranding');return `<section class="home-hero reveal" data-game="DEATH STRANDING">${img(ds,0,true)}<div class="home-copy"><p class="eyebrow">A MUSEUM OF INTERACTIVE CULTURE</p><h1>有些世界，<br>值得被永远记住。</h1><p>${games.length} 款游戏，跨越半个世纪。<br>走进那些改变玩法、拓展想象，<br>也在我们身上留下痕迹的作品。</p><div class="home-actions"><a class="pill primary" href="#collection">打开珍藏柜</a><a class="pill" href="#museum">进入三维展馆 ↗</a></div></div><div class="hero-caption"><span>本期展映 / DEATH STRANDING · 2019</span><span>1972 — 2025 / PERMANENT COLLECTION</span></div></section><section class="home-intro"><p class="eyebrow">BEYOND THE SCREEN</p><h2>一款游戏的伟大，<br>藏在你如何参与其中。</h2><p>一座桥为什么让人感激？一次跳跃如何改变三维世界？一个选择，又怎样成为自己的责任？在这里，画面只是入口。每件展品都从具体的游玩细节出发，追溯它的设计、作者与时代。</p></section><section class="home-focus"><div class="section-top"><h2>从这三扇门开始。</h2><a href="#collection">全部 ${games.length} 件馆藏 ↗</a></div><div class="focus-grid">${['wukong','gt7','portal'].map(id=>card(games.find(g=>g.id===id))).join('')}</div></section>`;}
const unique=key=>[...new Set(games.flatMap(g=>Array.isArray(g[key])?g[key]:[g[key]]))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'zh'));
function facet(key,label,field){return `<label class="facet"><span>${label}</span><select data-facet="${key}" aria-label="${label}"><option value="">全部</option>${unique(field).map(t=>`<option ${state[key]===t?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label>`;}
function collection(){return `<section class="page reveal"><div class="page-heading"><div><p class="eyebrow">THE COLLECTION</p><h1>珍藏柜</h1><p>找到一种玩法，走进一个世界。</p></div><div class="page-count">${games.length}<small>件作品</small></div></div><div class="control-panel"><div class="search-row"><label class="search-box"><span>搜索游戏、工作室或标签</span><input type="search" id="search" value="${esc(state.query)}" placeholder="搜索游戏、工作室或标签" autocomplete="off"></label><select id="sort" class="collection-sort" aria-label="馆藏排序"><option value="curated">策展顺序</option><option value="old" ${state.sort==='old'?'selected':''}>发行时间：早 → 晚</option><option value="new" ${state.sort==='new'?'selected':''}>发行时间：晚 → 早</option></select></div><div class="honor-filters" role="group" aria-label="入馆依据">${[['','全部馆藏'],['Ocean 精选','✦ Ocean 精选'],['年度游戏','年度游戏'],['历史里程碑','历史里程碑']].map(([key,label])=>`<button data-honor="${key}" aria-pressed="${state.honor===key}" class="${key==='Ocean 精选'?'ocean':''}">${label}</button>`).join('')}</div><div class="filters">${facet('genre','游戏类型','genre')}${facet('mode','游玩方式','mode')}${facet('theme','世界与题材','themes')}${facet('feature','体验特点','features')}</div><div class="filter-end"><span id="result" aria-live="polite"></span><button class="text-button" id="reset">清除筛选</button></div><div class="active-tags" id="active-tags"></div></div><div class="gallery" id="gallery"></div><p class="empty" id="empty" hidden>暂时没有同时符合这些条件的作品，试试减少一个筛选条件。</p></section>`;}
function matches(g){const terms=[g.title,g.en,g.maker,g.genre,g.mode,...g.themes,...g.features,...g.honors,...(g.award?[g.award.program,String(g.award.year)]:[])];return (!state.honor||g.honors.includes(state.honor))&& (!state.personal||g.personal)&&(!state.genre||g.genre===state.genre)&&(!state.mode||g.mode===state.mode)&&(!state.theme||g.themes.includes(state.theme))&&(!state.feature||g.features.includes(state.feature))&&(!state.tag||terms.includes(state.tag))&&terms.join(' ').toLowerCase().includes(state.query.trim().toLowerCase());}
function drawCollection(){let v=games.filter(matches);if(state.sort==='old')v.sort((a,b)=>a.order-b.order);if(state.sort==='new')v.sort((a,b)=>b.order-a.order);$('#gallery').innerHTML=v.map(card).join('');$('#result').textContent=`${v.length} / ${games.length} 件作品 · 筛选条件同时满足`;$('#empty').hidden=!!v.length;$('#active-tags').innerHTML=['genre','mode','theme','feature','tag'].filter(k=>state[k]).map(k=>`<button data-clear="${k}" aria-label="移除${esc(state[k])}筛选">${esc(state[k])} ×</button>`).join('');failure();}
function bindCollection(){let queued=false;const scheduleDraw=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;drawCollection()})};document.querySelectorAll('[data-honor]').forEach(b=>b.addEventListener('click',()=>{state.honor=b.dataset.honor;document.querySelectorAll('[data-honor]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.honor===state.honor));drawCollection()}));$('#search').addEventListener('input',e=>{state.query=e.target.value;scheduleDraw()});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;drawCollection()});document.querySelectorAll('[data-facet]').forEach(e=>e.addEventListener('change',()=>{state[e.dataset.facet]=e.value;drawCollection()}));$('#reset').addEventListener('click',()=>{Object.assign(state,{query:'',genre:'',mode:'',theme:'',feature:'',tag:'',personal:false,honor:''});renderPage('collection')});$('#active-tags').addEventListener('click',e=>{const b=e.target.closest('[data-clear]');if(b){state[b.dataset.clear]='';const s=document.querySelector(`[data-facet="${b.dataset.clear}"]`);if(s)s.value='';drawCollection()}});drawCollection();}
function timeline(){const sorted=[...games].sort((a,b)=>a.order-b.order),years=[...new Set(sorted.map(g=>g.year))];return `<section class="page timeline-page reveal"><div class="page-heading"><div><p class="eyebrow">THE HISTORY OF PLAY</p><h1>时间，把它们连在一起。</h1><p>沿作品首次发行的顺序，回看游戏语言的生长。</p></div></div><div class="decades" role="group" aria-label="跳转到年代">${[1970,1980,1990,2000,2010,2020].map((y,i)=>`<button data-decade="${y}" aria-pressed="${!i}">${y}s</button>`).join('')}</div><div class="timeline-controls"><span>横向浏览 · 触控板或滑动查看</span><div><button class="circle-btn" id="timeline-prev" aria-label="向前浏览">←</button><button class="circle-btn" id="timeline-next" aria-label="向后浏览">→</button></div></div><div class="timeline-track" id="timeline-track" tabindex="0" aria-label="1972 至 2025 年游戏时间线">${years.map(y=>`<section class="year-column" data-year="${y}" id="year-${y}"><div class="year-line"><h2>${y}</h2><span>${sorted.filter(g=>g.year===y).length} 件作品</span></div>${sorted.filter(g=>g.year===y).map(card).join('')}</section>`).join('')}</div><p class="timeline-note">按首次发行时间排列；同年作品按发行先后顺序展示。年份间距为阅读节奏设计，并非等比例年尺。《我的世界》以 2009 年首次公开版本入列，正式 1.0 版发行于 2011 年；重制版单独标记。</p></section>`;}
function bindTimeline(){const track=$('#timeline-track'),cols=[...track.querySelectorAll('.year-column')];const motion=matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';const update=()=>{const at=cols.reduce((best,c)=>Math.abs(c.offsetLeft-track.offsetLeft-track.scrollLeft)<Math.abs(best.offsetLeft-track.offsetLeft-track.scrollLeft)?c:best,cols[0]);const d=Math.floor(Number(at.dataset.year)/10)*10;document.querySelectorAll('[data-decade]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.decade===d)));$('#timeline-prev').disabled=track.scrollLeft<5;$('#timeline-next').disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-5;};track.addEventListener('scroll',update,{passive:true});document.querySelectorAll('[data-decade]').forEach(b=>b.addEventListener('click',()=>{const c=cols.find(c=>+c.dataset.year>=+b.dataset.decade);track.scrollTo({left:c.offsetLeft-track.offsetLeft,behavior:motion})}));$('#timeline-prev').addEventListener('click',()=>track.scrollBy({left:-Math.min(track.clientWidth*.85,700),behavior:motion}));$('#timeline-next').addEventListener('click',()=>track.scrollBy({left:Math.min(track.clientWidth*.85,700),behavior:motion}));track.addEventListener('keydown',e=>{if(e.target!==track)return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();track.scrollBy({left:e.key==='ArrowLeft'?-360:360,behavior:motion})}});update();}
function criteria(){return `<section class="page criteria reveal"><p class="eyebrow">CURATORIAL STATEMENT</p><h1>伟大，<br>不只有一条路径。</h1><p class="lead">游戏圣殿是一份持续展开的收藏判断。我们关心作品实际创造了什么，也关心这些创造为什么值得留下。</p><div class="admission-paths"><article><span class="honor ocean">✦ Ocean 精选</span><h2>独一份的珍视。</h2><p>Ocean 亲选的最高个人荣誉。保留原有精选名单，不因扩库自动增加。</p></article><article><span class="honor annual">年度游戏</span><h2>二十年的行业选择。</h2><p>覆盖 2006–2025 年：2006–2012 为 VGA，2013 为 VGX，2014–2025 为 TGA。年份标注获奖年，时间线使用发行年。</p></article><article><span class="honor historical">历史里程碑</span><h2>留下可追溯的改变。</h2><p>关注规则、技术、创作生态或文化传播的长期贡献，结合历史档案与具体作品分析。不是销量排名，也不将娱乐影响等同于推动全部人类历史。</p></article></div><p class="criteria-overlap">三类依据可以重叠。一件作品只入库一次；每个标签各自说明它为什么被留下。</p><div class="criteria-grid">${[['01','改变游戏的语法','一套新的交互关系、空间组织或叙事方法，是否让后来者拥有更多可能？区分首创与普及，也承认将已有设计组织到极高完成度的价值。'],['02','拥有自己的表达','视觉、声音与操作是否指向同一种体验？题材能否真正进入规则？一个不能简单用别的作品替换的世界，比笼统的“画面好、内容多”更值得讨论。'],['03','在行业中留下痕迹','观察技术、生产方法、传播和玩家文化的变化。销量与奖项可以提供背景，却不能代替对作品本身的判断；新作的长期影响仍交给时间。'],['04','允许个人的共鸣','Ocean 精选是本馆最高个人收藏荣誉，仅由 Ocean 亲自指定，以金色标识。年度奖项或历史影响不会自动授予，也不会替代个人选择。']].map(c=>`<article class="criterion"><span>${c[0]}</span><h2>${c[1]}</h2><p>${c[2]}</p></article>`).join('')}</div><div class="source-principle"><p>展文参考专业游戏媒体评测、开发者说明与历史资料，重新组织为本馆的原创评论。媒体观点会单独标注，不将转述写成亲自游玩的经历，也不将设计比较写成未经证实的影响关系。</p><p>档案画面保留作品版本信息。早期游戏的原始像素、历史包装和街机照片各有价值；高分辨率的摄影不等于原作本身采用高清渲染。</p></div><a class="pill primary" href="#collection">回到珍藏柜</a></section>`;}
function figure(g,i){const p=g.pictures?.[i]||g.pictures?.[0];return `<figure class="article-figure" data-game="${esc(g.title)}">${img(g,i)}<figcaption>${esc(p?.caption||g.title+' · 游戏场景')} ${p?.width?' / '+p.width+' × '+p.height:''}${p?.note?' · '+esc(p.note):''}</figcaption></figure>`;}
function relationLinks(r){const extra={'《黑暗之魂》与《风之旅人》':['dark-souls'],'《战神》与《黑暗之魂》':['god-of-war','dark-souls'],'《荒野大镖客：救赎》（2010）':['rdr'],'《半衰期 2》':['half-life-2'],'《镜之边缘》与《半衰期 2》':['half-life-2'],'《只狼：影逝二度》':['sekiro'],'《GTA III》→《圣安地列斯》→《GTA IV》':['gta-iv']};const ids=r[3]?[r[3]]:extra[r[1]]||[];return ids.length?ids.map(id=>{const g=games.find(g=>g.id===id);return g?`<a class="relation-entry" href="#game/${g.id}">阅读《${esc(g.title)}》完整展文 ↗</a>`:''}).join(''):'<span class="relation-context">背景关联资料 · 暂无独立展文</span>';}
function room(g){const a=g.review;const sections=a.sections||[{title:a.headings[0],paras:[a.paragraphs[0],g.position]},{title:a.headings[1],paras:[g.innovation,a.paragraphs[1]]},{title:a.headings[2],paras:[a.paragraphs[2],g.unique]},{title:a.headings[3],paras:[a.paragraphs[3],g.boundary]}];const alltext=[a.intro,...sections.flatMap(s=>s.paras),a.verdict].join('');const minutes=Math.max(5,Math.ceil(alltext.length/300));const next=games[(games.indexOf(g)+1)%games.length];return `<article class="room reveal" data-style="${g.style}" style="--game-color:${g.color}" id="article"><section class="room-hero" data-game="${esc(g.title)}">${img(g,0,true)}<div class="room-heading"><p class="eyebrow">${g.year} / ${esc(g.genre)} / ${g.personal?'OCEAN’S COLLECTION':'PERMANENT COLLECTION'}</p><h1>${esc(g.title)}</h1><p class="english">${esc(g.en)}</p><p class="deck">${esc(a.headline)}</p></div></section><div class="reading-bar"><a href="#collection">← 珍藏柜</a><span>${minutes} 分钟阅读 · 原创评论</span><details><summary>文章目录 ＋</summary><nav>${sections.map((s,i)=>`<a href="#game/${g.id}/chapter-${i}">${esc(s.title)}</a>`).join('')}<a href="#game/${g.id}/verdict">本馆结语</a><a href="#game/${g.id}/relations">作品关系</a><a href="#game/${g.id}/references">参考资料</a></nav></details><div class="reading-progress" id="progress"></div></div><div class="article-meta">${honorBadges(g)}${g.personal?'<p class="ocean-citation">OCEAN’S DISTINCTION · 本馆最高个人收藏荣誉。由 Ocean 亲自选定，奖项与历史地位不会自动授予。</p>':''}${g.historical?`<p class="admission-reason">历史入馆依据：${esc(g.historical)}</p>`:''}<dl><div><dt>首次发行</dt><dd>${g.year}</dd></div><div><dt>开发团队</dt><dd>${esc(g.maker)}</dd></div><div><dt>版本</dt><dd>${esc(g.edition)}</dd></div></dl><div class="full-tags">${[g.genre,g.mode,...g.themes,...g.features].map(t=>`<button data-tag="${esc(t)}" aria-label="筛选${esc(t)}游戏">${esc(t)}</button>`).join('')}</div></div>${['death-stranding','spider-man','rdr2'].includes(g.id)?`<div class="spatial-article-link"><a class="pill primary" href="#museum/${g.id}">走进《${esc(g.title)}》三维展厅 ↗</a></div>`:''}<div class="article-intro"><p class="byline">GAME TEMPLE EDITORIAL / 资料研究与策展评论 · 不涉及关键结局</p><p>${esc(a.intro)}</p></div>${sections.map((s,i)=>`<section class="review-section" id="chapter-${i}"><span class="section-number">${String(i+1).padStart(2,'0')} / ${esc(g.en)}</span><h2>${esc(s.title)}</h2>${s.paras.map(p=>`<p>${esc(p)}</p>`).join('')}${i===sections.length-1&&a.media?`<p class="media-note">评测参照：${esc(a.media.note)} <a href="${esc(a.media.url)}" target="_blank" rel="noopener noreferrer">${esc(a.media.name)} ↗</a></p>`:''}</section>${i===0?figure(g,1):i===1?`<aside class="quote-panel"><p>${esc(a.pull)}</p></aside>`:i===2&&g.pictures?.length>2?figure(g,2):''}`).join('')}<section class="verdict" id="verdict"><p class="eyebrow">THE TEMPLE’S VIEW</p><h2>${esc(a.verdictTitle)}</h2><p>${esc(a.verdict)}</p></section><section class="relations" id="relations"><h2>把这件作品放回它的星系。</h2><div class="relation-grid">${g.relations.map(r=>`<article class="relation-card"><span>${esc(r[0])}</span><h3>${esc(r[1])}</h3><p>${esc(r[2])}</p>${relationLinks(r)}</article>`).join('')}</div></section><details class="references" id="references"><summary>参考资料、版本与图像来源</summary><p>正文中的评价为本馆原创分析；下列媒体提供评测参照，官方资料用于核对机制与版本。复刻、移植、怀旧服评测均保留版本标注。展览图片随本站部署；下列链接保留原始来源与版本信息。</p><ol>${(a.media?[[a.media.name,a.media.url]]:[]).concat(g.sources).map(s=>`<li><a href="${esc(s[1])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a></li>`).join('')}${(g.pictures||[]).map(p=>`<li><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${esc(p.caption)} · 素材来源 ↗</a>${p.note?' · '+esc(p.note):''}</li>`).join('')}</ol></details><nav class="next-exhibit"><a href="#timeline"><span>CONTINUE THE JOURNEY</span>回到历史时间线</a><a href="#game/${next.id}"><span>NEXT EXHIBIT</span>${esc(next.title)} ↗</a></nav></article>`;}
function renderPage(page){const old=current;current=page;activeGame=null;$('#screen').innerHTML=page==='collection'?collection():page==='timeline'?timeline():page==='criteria'?criteria():homepage();document.querySelectorAll('[data-page]').forEach(a=>{if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=(page==='collection'?'珍藏柜':page==='timeline'?'时间线':page==='criteria'?'入馆标准':'Game Temple')+' · 游戏圣殿';if(page==='collection')bindCollection();if(page==='timeline')bindTimeline();failure();if(page==='collection'&&old==='game'){window.scrollTo(0,galleryScroll)}else window.scrollTo(0,0);}
function route(){window.templeCleanup?.();window.templeCleanup=null;const p=location.hash.slice(1).split('/');if(p[0]==='museum'){current='museum';activeGame=null;$('#screen').innerHTML=museumPage();document.title='空间展馆 · Game Temple';document.querySelectorAll('[data-page]').forEach(a=>a.dataset.page==='museum'?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));window.scrollTo(0,0);const host=document.getElementById('spatial-view');import(new URL('assets/spatial/gallery-11ea04cea6779a5c.js',document.baseURI).href).then(m=>{if(host.isConnected){window.templeCleanup=m.mount(host);const target={'death-stranding':'hall','spider-man':'spider',rdr2:'west'}[p[1]];if(target)host.querySelector('[data-view="'+target+'"]')?.click();}}).catch(()=>{if(host.isConnected)document.getElementById('spatial-status').textContent='三维展厅加载失败，请刷新重试。你仍可阅读下方展览说明。'});return;}if(p[0]==='game'){const g=games.find(g=>g.id===p[1]);if(!g){location.replace('#collection');return;}if(activeGame!==g.id){if(current==='collection')galleryScroll=window.scrollY;current='game';activeGame=g.id;$('#screen').innerHTML=room(g);document.querySelectorAll('[data-page]').forEach(a=>a.removeAttribute('aria-current'));document.title=g.title+' · Game Temple';failure();window.scrollTo(0,0);document.querySelectorAll('[data-tag]').forEach(b=>b.addEventListener('click',()=>{Object.assign(state,{query:'',genre:'',mode:'',theme:'',feature:'',personal:false,honor:'',tag:b.dataset.tag});galleryScroll=0;location.hash='collection'}));}if(p[2]){const target=document.getElementById(p[2]);if(target?.tagName==='DETAILS')target.open=true;document.querySelector('.reading-bar details')?.removeAttribute('open');target?.scrollIntoView({block:'start'});}updateProgress();return;}const page=['collection','timeline','criteria'].includes(p[0])?p[0]:p[0]==='principles'?'criteria':'home';renderPage(page);}
let scrollQueued=false;function updateProgress(){const p=$('#progress'),a=$('#article');if(!p||!a)return;const top=a.offsetTop,total=a.scrollHeight-window.innerHeight;p.style.width=Math.min(100,Math.max(0,(window.scrollY-top)/Math.max(1,total)*100))+'%'}window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(()=>{updateProgress();scrollQueued=false})}},{passive:true});window.addEventListener('hashchange',route);route();
